    echo -e "${BLUE}
Installation guide - Arch Wiki
${BOLD}For more information, see the wiki: \
${GREY}<https://wiki.archlinux.org/index.php/Installation_guide>${NC}"
}
###
### SHARED VARIABLES AND FUNCTIONS (ОБЩИЕ ПЕРЕМЕННЫЕ И ФУНКЦИИ)
### Shell color codes (Цветовые коды оболочки)
### Советы по Bash: Цвета и форматирование (управляющие последовательности ANSI/VT100)
### https://misc.flogisoft.com/bash/tip_colors_and_formatting
BLACK="\e[0;30m"; NC="\e[0m"  # No Color
DARKGRAY="\e[1;30m"; LIGHTGRAY="\e[0;37m"
LIGHTRED="\e[1;31m"; RED="\e[0;31m"
LIGHTGREEN="\e[1;32m"; GREEN="\e[0;32m"
BROWNORANGE="\e[0;33m"; YELLOW="\e[1;33m"
LIGHTBLUE="\e[1;34m"; BLUE="\e[0;34m"
LIGHTPURPLE="\e[1;35m"; PURPLE="\e[0;35m"; MAGENTA="\e[1;35m"
LIGHTCYAN="\e[1;36m"; CYAN="\e[0;36m"
BOLD="\e[1;37m"; WHITE="\e[0;37m"
GREY="\e[3;93m"
### Automatic error detection (Автоматическое обнаружение ошибок)
_set() {
    set [--abefhkmnptuvxBCHP] [-o option] [arg ...]
}
###
_set() {
    set -e "\n${RED}Error: ${YELLOW}${*}${NC}"
    _note "${MSG_ERROR}"
    sleep 1; $$
}
