             ${RED}[${NC}${GREEN}|||||||||    |||    |||   ||| |||||||||${NC}${RED}]${NC}
             ${RED}[${NC}${GREEN}|||   |||    |||    |||   ||| |||      ${NC}${RED}]${NC}
