#echo 'Если у Вас беспроводное соединение, запустите nmtui и подключитесь к сети.'
# If you have a wireless connection, launch nmtui and connect to the network.
##################
clear
echo ""
echo -e "${MAGENTA}
  <<< Установка первоначально необходимых утилит (пакетов) и запуск необходимых служб для системы в Archlinux 📦 >>> ${NC}"
# Installing the initially necessary utilities (packages) and running the necessary services for the system in Archlinux
#echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Установка утилит (пакетов) Мультимедиа, Офисных, Веб-браузеров и других, будут представлены в следующих скриптах (по названию позиций например: multimedia_prog.sh). ${NC}"
sleep 05
# clear
echo ""
echo -e " ${BLUE}:: ${NC}Установка и настройка начата в $(date +%T) "
# Installation and configuration started in $(date +%T)
echo ""
echo -e "${GREEN}=> ${NC}Для проверки интернета можно пропинговать какой-либо сервис "
#echo 'Для проверки интернета можно пропинговать какой-либо сервис'
# To check the Internet, you can ping a service
ping -c 2 archlinux.org  # Утилита ping - это очень простой инструмент для диагностики сети
# ping google.com -W 2 -c 1
## ping -l 3 ya.ru
echo ""
echo -e "${CYAN}==> ${NC}Если пинг идёт едем дальше ... :)"
# If the ping goes we go further ... :)
sleep 1
echo " Чтобы выполнить тест скорости поиска, выберите веб-сайт, который не посещался с момента запуска dnsmasq "
drill archlinux.org | grep "Query time"  # Тест dnsmasq
echo " Выполним опрос DNS-сервера: '1.1.1.1' (@cервер) с запросом archlinux.org (доменное имя интернет-ресурса) "
dig @1.1.1.1 archlinux.org  # для опроса DNS-серверов
echo ""
echo -e "${MAGENTA}==> ${NC}Давайте проверим наш часовой пояс ... :)"
# Let's check our time zone ... :)
timedatectl | grep "Time zone"
sleep 1
echo ""
echo -e "${BLUE}:: ${NC}Если NetworkManager запущен смотрим состояние интерфейсов"
# If NetworkManager is running look at the state of the interfaces
# Первым делом нужно запустить NetworkManager:
# sudo systemctl start NetworkManager
# Если NetworkManager запущен смотрим состояние интерфейсов (с помощью - nmcli):
nmcli general status
sleep 1
echo ""
echo -e "${BLUE}:: ${NC}Посмотреть имя хоста"
# View host name
nmcli general hostname
sleep 1
echo ""
echo -e "${BLUE}:: ${NC}Получаем состояние интерфейсов"
# Getting the state of interfaces
nmcli device status
sleep 1
echo ""
echo -e "${BLUE}:: ${NC}Смотрим список доступных подключений"
# See the list of available connections
nmcli connection show
sleep 1
echo ""
echo -e "${BLUE}:: ${NC}Смотрим состояние wifi подключения"
# Looking at the status of the wifi connection
nmcli radio wifi
sleep 1
############# Справка ############
### Посмотреть список доступных сетей wifi:
# nmcli device wifi list
## Теперь включаем:
# nmcli radio wifi on
## Или отключаем:
# nmcli radio wifi off
## Команда для подключения к новой сети wifi выглядит не намного сложнее. Например, давайте подключимся к сети TP-Link с паролем 12345678:
## nmcli device wifi connect "TP-Link" password 12345678 name "TP-Link Wifi"
## Если всё прошло хорошо, то вы получите уже привычное сообщение про создание подключения с именем TP-Link Wifi и это имя в дальнейшем можно использовать для редактирования этого подключения и управления им, как описано выше.
####################################
echo ""
echo -e "${BLUE}:: ${NC}Посмотрим данные о нашем соединение с помощью IPinfo..."
# Let's look at the data about our connection using IP info...
echo -e "${CYAN}=> ${NC}С помощью IPinfo вы можете точно определять местонахождение ваших пользователей, настраивать их взаимодействие, предотвращать мошенничество, обеспечивать соответствие и многое другое."
echo " Надежный источник данных IP-адресов (https://ipinfo.io/) "
wget http://ipinfo.io/ip -qO -
sleep 03
echo ""
echo -e "${BLUE}:: ${NC}Узнаем версию и данные о релизе Arch'a ... :) "
#echo "Узнаем версию и данные о релизе Arch'a ... :)"
# Find out the version and release data for Arch ... :)
cat /proc/version
cat /etc/lsb-release.old
sleep 02

clear
echo -e "${CYAN}
  <<< Установка обновлений для системы Arch Linux 🆙 >>> ${NC}"
# Installation of utilities (packages) for the Arch Linux system begins
echo ""
echo -e "${GREEN}==> ${NC}Обновим вашу систему (базу данных пакетов)?"
#echo -e "${BLUE}:: ${NC}Обновим вашу систему (базу данных пакетов)?"
# Update your system (package database)?
echo -e "${CYAN}=> ${BOLD}В сценарии (скрипте) присутствуют следующие варианты: ${NC}"
echo " 1 - Обновление базы данных пакетов плюс обновление самих пакетов (pacman -Syyu) "
echo -e "${RED}==> Важно! ${NC}Если при обновлении системы прилетели обновления ядра и установились, то Вам нужно желательно остановить исполнения сценария (скрипта), и выполнить команду по обновлению загрузчика 'grub' - sudo grub-mkconfig -o /boot/grub/grub.cfg , затем перезагрузить систему."
echo -e "${YELLOW}=> Примечание: ${BOLD}Загружаем базу данных пакетов независимо от того, есть ли какие-либо изменения в версиях или нет. ${NC}"
# Loading the package database regardless of whether there are any changes in the versions or not.
echo " 2 - Просто обновить базы данных пакетов пакмэна (pacman -Syy) "
echo -e "${YELLOW}==> Примечание: ${BOLD}Возможно Вас попросят ввести пароль пользователя (user). ${NC}"
echo " Будьте внимательны! Процесс установки, был прописан полностью автоматическим. "
# Be careful! The installation process was fully automatic.
echo " Если Вы сомневаетесь в своих действиях, ещё раз обдумайте... "
# If you doubt your actions, think again...
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - Обновить и установить (pacman -Syyu),     2 - Обновить базы данных пакетов (pacman -Syy)

    0 - НЕТ - Пропустить обновление и установку: " upd_sys  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$upd_sys" =~ [^120] ]]
do
    :
done
if [[ $upd_sys == 0 ]]; then
  echo ""
  echo " Установка обновлений пропущена "
elif [[ $upd_sys == 1 ]]; then
  echo ""
  echo " Установка обновлений (базы данных пакетов) "
  sudo pacman -Syyu --noconfirm  # Обновление баз плюс обновление пакетов (--noconfirm - не спрашивать каких-либо подтверждений)
# sudo pacman -Syyu  # Обновим вашу систему (базу данных пакетов)
  echo ""
  echo " Обновление и установка выполнено "
elif [[ $upd_sys == 2 ]]; then
  echo ""
  echo " Обновим базы данных пакетов... "
# sudo pacman -Sy --noconfirm  # обновить списки пакетов из репозиториев
  sudo pacman -Syy  # обновление баз пакмэна (pacman)
  echo ""
  echo " Обновление базы данных выполнено "
fi
sleep 1

clear
echo ""
echo -e "${GREEN}=> ${NC}Загрузить архив (мастер ветку MarcMilany/archmy_2020) 🌿 ?"
# Upload the archive (master branch MarcMilany/arch_2020)
echo -e "${CYAN}==> Примечание! ${BOLD} *Эти действия необходимы (на всякий пожарный)! Если Вы при установке основной системы пропустили какой-либо пункт меню сценария (скрипта), и хотите выполнить эти действия сейчас, а также в мастер ветке находятся различные конфигурации софта, скрипты установки утилит, справки с настройками утилит (пакетов) и другие плюшки. 😃 ${NC}"
echo -e "${MAGENTA}:: ${NC}Папка мастер ветки 'archmy_2020' после скачивания будет находить в домашней (home) - директории пользователя, Вы можете переместить её в удобное для Вас место (папку; директорию) и пользоваться скриптами как шпаргалкой. "
echo -e "${MAGENTA}:: ${BOLD}Этот проект Лицензируется под GNU General Public License GPL-3.0, 29 June 2007. ${NC}"
echo " Будьте внимательны! Процесс загрузки, был прописан полностью автоматическим. "
# Be careful! The installation process was fully automatic.
echo " Если Вы сомневаетесь в своих действиях, ещё раз обдумайте... "
# If you doubt your actions, think again...
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да загрузить,     0 - НЕТ - Пропустить действие: " i_master  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$i_master" =~ [^10] ]]
do
    :
done
if [[ $i_master == 0 ]]; then
  echo ""
  echo " Загрузка master ветки пропущена "
elif [[ $i_master == 1 ]]; then
  echo ""
  echo " Загрузка master ветки "
# wget https://github.com/MarcMilany/arch_2020.git/archive/master.zip
# wget github.com/MarcMilany/arch_2020.git/archive/arch_2020-master.zip
# sudo mv -f ~/Downloads/master.zip
# sudo mv -f ~/Downloads/arch_2020-master.zip
# sudo tar -xzf master.zip -C ~/
# sudo tar -xzf arch_2020-master.zip -C ~/
# git clone https://github.com/MarcMilany/arch_2020.git
  git clone https://github.com/MarcMilany/archmy_2020.git
  echo ""
  echo " Загрузка master ветки выполнена "
  echo " У меня в гараже идеальный порядок … я всегда знаю, где и что у меня валяется! "
fi
sleep 03

clear
echo -e "${MAGENTA}
  <<< Синхронизации времени в Arch Linux 🕓👉👈🕓 >>> ${NC}"
# Time synchronization in Arch Linux
echo -e "${YELLOW}==> Примечание! ${BOLD} *Время от времени часы на компьютере могут сбиваться по различным причинам (или допустим, что у вас параллельно установлена Windows...). Надеюсь, что во врема установки Arch'a вы воспользовались пунктом 'Запустить Systemd-Timesyncd и сделать (systemd-timesyncd.service) активным', чтобы Синхронизировать время в системе. Для ИСПРАВЛЕНИЯ (синхронизации времени) предложу вам несколько вариантов: протокол NTP (Network Time Protocol) и OpenNTPD (также известен как OpenBSD NTP Daemon). ${NC}"
echo -e "${BLUE}:: ${BOLD} Для начала посмотрим дату, время, и часовой пояс ... 😃 ${NC}"
timedatectl | grep "Time zone"  # Команда использует функцию конвейера Linux: вывод одной команды становится входом для другой. В данном случае из вывода timedatectl ищут ключевое слово «Time Zone» и вывод ограничивается только нужной информацией.
date  # узнать текущий часовой пояс
date +'%d/%m/%Y  %H:%M:%S [%:z  %Z]'     # одновременно отображает дату и часовой пояс
sleep 03
#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить NTP (Network Time Protocol)(ntp) — Синхронизации времени в Archlinux?"
echo -e "${YELLOW}=> Предисловие! ${BOLD} *В Arch Linux для синхронизации времени используются разные инструменты: протокол NTP (Network Time Protocol), клиент Systemd-Timesyncd (systemd-timesyncd) и, в некоторых случаях, Chrony (chrony). Эти инструменты позволяют синхронизировать системное время с удалёнными серверами, что важно для корректной работы приложений, логов и запланированных задач. ${NC}"
echo -e "${CYAN}=> ${BOLD}NTP (Network Time Protocol) — стандартизированный протокол, который позволяет компьютерам синхронизировать часы через интернет. В Arch Linux доступен пакет (ntp - Эталонная реализация сетевого протокола времени), который включает необходимые файлы и сервисы для синхронизации времени, который работает поверх UDP и используется для синхронизации локальных часов с часами на сервере точного времени (на различных операционных системах). Настройка: После установки пакета нужно отредактировать файл конфигурации /etc/ntp.conf. Можно настроить серверы NTP, например, использовать серверы, предоставляемые проектом NTP pool, или стандартные серверы Arch. Чтобы применить изменения, нужно перезапустить сервис NTP с помощью systemctl: 'sudo systemctl restart ntpd'. Список общедоступных NTP серверов доступен на сайте http://ntp.org. NTP Servers (серверы точного времени) - https://www.ntp-servers.net/. Этот проект Лицензируется под Custom License (допускает использование продукта в соответствии с указаниями разработчика). ${NC}"
echo " Домашняя страница: https://www.ntp.org/ ; (https://archlinux.org/packages/extra/x86_64/ntp/). "
echo -e "${BLUE}:: ${NC}Настройка: После установки NTP можно настроить его, отредактировав файл конфигурации — /etc/ntp.conf. В файле можно настроить, например: Список серверов — добавить или изменить список NTP-серверов, с которыми будет синхронизироваться система. Для добавления сервера используется директива server, за которой следует имя сервера или IP-адрес. Arch Linux использует свой собственный стандартный пул NTP-серверов, который предоставляет the NTP Pool Project (https://www.pool.ntp.org/). Ограничение доступа к серверу — можно использовать директиву restrict, за которой следует имя сервера, IP-адрес или адрес сети. Например, строки restrict default kod nomodify notrap nopeer noquery ограничивают доступ к серверу, позволяя только запросы синхронизации времени. "
echo -e "${CYAN}:: ${NC}NTP работает, периодически проверяя и настраивая часы компьютера, чтобы они соответствовали времени, предоставляемому удалёнными серверами. Это важно для различных задач, например: Безопасность — многие протоколы безопасности (например, Kerberos) зависят от синхронизированных часов для предотвращения атак Replay. Системные журналы — файлы журналов имеют время, и точное время обеспечивает их правильный порядок и возможность корреляции на разных системах. Запланированные задачи в cron — запланированные задачи в cron зависят от правильного системного времени, чтобы запускаться в нужный момент. Мониторинг: Проверить статус сервиса NTP можно с помощью команды: 'sudo systemctl status ntpd'. Если сервис не запущен или не работает, можно проверить логи с помощью команды: journalctl -u ntpd на сообщения об ошибках. Используйте ntpq для просмотра списка настроенных пиров и статуса синхронизации: ntpq -p "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да  — установить NTP (Network Time Protocol),     0 - НЕТ - Пропустить установку: " i_localtime  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$i_localtime" =~ [^10] ]]
do
    :
done
if [[ $i_localtime == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $i_localtime == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) NTP (Network Time Protocol) (ntp) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
sudo pacman -S --noconfirm --needed ntp  # Эталонная реализация сетевого протокола времени ; https://archlinux.org/packages/extra/x86_64/ntp/ ; https://www.ntp.org/ ; Обратные конфликты: с openntpd ; 2025-05-05 12:22 UTC
  echo ""
  echo " Установка времени по серверу NTP (Network Time Protocol)(ru.pool.ntp.org) "
### Важно понимать, что слой сервера не может рассматриваться как показатель его точности или надёжности. Обычно для синхронизации пользовательских машин используются stratum 2 серверы. Если вы ещё не знаете, к каким серверам вы собираетесь подключиться, вам следует выбрать пул серверов, расположенный недалеко от вашего местоположения, из списка серверов на pool.ntp.org (https://www.pool.ntp.org/) (альтернативная ссылка - https://support.ntp.org/bin/view/Servers/NTPPoolServers). Arch Linux использует свой собственный стандартный пул NTP-серверов, который предоставляет the NTP Pool Project (https://www.pool.ntp.org/)(смотрите FS#41700 - https://bugs.archlinux.org/task/41700)
  sudo ntpdate 0.ru.pool.ntp.org  # будем использовать NTP сервера из пула ru.pool.ntp.org
# sudo ntpdate 1.ru.pool.ntp.org  # Список общедоступных NTP серверов доступен на сайте http://ntp.org
# sudo ntpdate 2.ru.pool.ntp.org  # Отредактируйте /etc/ntp.conf для добавления/удаления серверов (server)
# sudo ntpdate 3.ru.pool.ntp.org  # После изменений конфигурационного файла вам надо перезапустить ntpd (sudo service ntp restart) - Просмотр статуса: (sudo ntpq -p)
### Измените его под свои нужды, например если вы хотите использовать сервера своей страны: /etc/ntp.conf
# server 0.ru.pool.ntp.org iburst
# server 1.ru.pool.ntp.org iburst
# server 2.ru.pool.ntp.org iburst
# server 3.ru.pool.ntp.org iburst
# Опция 'iburst' рекомендуется, с ее помощью посылается шквал пакетов, если не удается установить соединение с сервером с первого раза. Напротив, опцию 'burst' не используйте никогда без особого разрешения, так как Вы можете попасть в "черный список".
  echo " Синхронизации с часами BIOS (синхронизируем аппаратное время с системным) "  # Синхронизируем аппаратное время с системным
  echo " Устанавливаются аппаратные часы из системных часов. "
sudo hwclock --systohc  # устанавливает время аппаратных часов ; Эта команда предполагает, что аппаратные часы настроены в формате UTC.
# sudo hwclock  # считывает время из аппаратных часов
# sudo hwclock -w  # переведёт аппаратные часы
# sudo hwclock --adjust  # Порой значение аппаратного времени может сбиваться - выровняем!
# sudo hwclock --systohc --utc  #  # устанавливает время аппаратных часов равным UTC на основании системного времени
# sudo hwclock --set --date "22 Mar 2002 13:17"  # устанавливает время аппаратных часов равным указанной строке
  echo ""
  echo " Добавим в автозагрузку NTPD (ntpd.service) "
sudo systemctl enable ntpd.service  # Запуск ntpd при загрузке системы
sudo systemctl start ntpd.service  # Включите службу ntpd.service
# sudo systemctl restart ntpd.service  # Чтобы применить изменения конфигурации, нужно перезапустить сервис NTP с помощью systemctl
#sudo systemctl status ntpd.service  # Проверить статус сервиса NTP
# sudo systemctl daemon-reload  # Команда systemctl daemon-reload информирует systemd о необходимости перезагрузить все файлы служб и обновить его внутреннюю конфигурацию. Это необходимо, когда создаются, изменяются или удаляются файлы служб. Без этой команды systemd не распознаёт изменения.
# *Примечание: systemd-team timedatectl управляет только службой systemd-timesyncd. Выполнение timedatectl set-ntp 1 как root, может случайно остановить работающий ntpd.service (https://lists.freedesktop.org/archives/systemd-devel/2015-April/030277.html)
### Смотрим журнал, информация минимальная:
# journalctl -u ntpd.service
  echo ""
  echo " Установка утилит (пакетов) выполнена "
  echo ""
  echo " Посмотрите информацию о версии (ntp) "
# ntpq -c readvar version  # В Linux для проверки версии NTP используется команда ntpq из стандартного пакета NTP. Она выполняет локальные запросы к активному процессу ntpd и выводит полную строку версии. Это позволит выполнить ntpdпрямой запрос и вывести полную строку версии.
sudo pacman -Q ntp  #  Показать версию приложения ; Альтернативный метод — проверить версию установленного пакета NTP через менеджер пакетов системы.
# sudo pacman -Qs имя_пакета  # Используйте команду pacman с -Qsопцией поиска только среди установленных пакетов в системе. Она ищет указанный текст только в названиях и описаниях установленных пакетов.
# sudo pacman -Qi имя_пакета  # Эта -Qiопция отображает подробную информацию об указанном пакете. Она также показывает метаданные пакета, такие как зависимости, конфликты, дата установки, дата сборки, размер и т. д.
# sudo pacman -Si имя_пакета  # Эта -Si опция позволяет просматривать подробную информацию о любых пакетах Arch Linux. Необходимо указать точное название пакета.
sleep 03
  echo ""
echo -e "${GREEN}:: ${BOLD}Время точное как на Спасской башне Московского Кремля! ${NC}"
# echo " Время точное как на Спасской башне Московского Кремля! "
  date +'%d/%m/%Y  %H:%M:%S [%:z  %Z]'   # одновременно отображает дату и часовой пояс
sleep 03
fi
############# Справка ##############
# ArchWiki : https://wiki.archlinux.org/title/Network_Time_Protocol_daemon_(%D0%A0%D1%83%D1%81%D1%81%D0%BA%D0%B8%D0%B9)
# NTP — сетевой протокол для синхронизации внутренних часов компьютера с использованием сетей с переменной латентностью, для своей работы использует протокол UDP и порт 123.
# Настройка синхронизации времени в домене с помощью групповых политик состоит из двух шагов:
# 1) Создание GPO для контроллера домена с ролью PDC
# 2) Создание GPO для клиентов (опционально)
# https://zen.yandex.ru/media/winitpro.ru/ntp-sinhronizaciia-vremeni-v-domene-s-pomosciu-gruppovyh-politik-5b5042923e546700a8ccf633?utm_source=serp
# (https://www.8host.com/blog/ustanovka-i-nastrojka-openntpd-v-freebsd-10-2/)
# *Примечание: systemd-team timedatectl управляет только службой systemd-timesyncd. Выполнение timedatectl set-ntp 1 как root, может случайно остановить работающий ntpd.service (https://lists.freedesktop.org/archives/systemd-devel/2015-April/030277.html)
# Задержка, смещение и джиттер должны быть отличны от нуля. Серверы, с которыми синхронизируется ntpd, отмечены звёздочкой. Может потребоваться несколько минут, прежде чем ntpd выберет сервер для синхронизации; попробуйте проверить через 17 минут (1024 секунды).
# Синхронизация один раз при загрузке:
# В качестве альтернативы включите службу ntpdate.service для однократной синхронизации (опция -q) в non-forking режиме (опция -n) при загрузке системы вместо запуска постоянно работающего демона в фоне. Этот метод не рекомендуется на серверах и в целом на машинах, которые работают без перезагрузки более нескольких дней.
# Если синхронизированное время нужно записать в аппаратные часы компьютера, создайте drop-in файл для этой службы:
# /etc/systemd/system/ntpdate.service.d/hwclock.conf
# [Service]
# ExecStart=/usr/bin/hwclock -w
# Советы и рекомендации:
# Запуск ntpd при подключении сети:
# ntpd может быть запущен вашим менеджером сети, чтобы демон запускался только при появлении интернета.
# Netctl:
# Добавьте следующие строки в ваш профиль netctl:
# ExecUpPost="systemctl start ntpd.service"
# ExecDownPre="systemctl stop ntpd.service"
#######################

clear
echo ""
echo -e "${BLUE}:: ${NC}Установить OpenNTPD (OpenBSD NTP Daemon)(openntpd) — Синхронизации времени в Archlinux?"
echo -e "${YELLOW}=> Важно: ${BOLD} *OpenNTPD не работает с NTPD — нужно удалить NTPD (ntp), если он установлен. В мире, где синхронизация по протоколу NTP становится все более распространенной, важно иметь бесплатную реализацию, которая обеспечивает хорошую синхронизацию времени, сохраняя при этом высокий уровень безопасности и простоту настройки. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}OpenNTPD (также известен как OpenBSD NTP Daemon) — демон, реализующий протокол Network Time Protocol (NTP) для синхронизации локального времени системы с удалёнными серверами NTP, первоначально разработанная в рамках проекта OpenBSD. OpenNTPD — это БЕСПЛАТНАЯ и простая в использовании реализация сетевого протокола времени. Она обеспечивает синхронизацию локальных часов с удалёнными NTP-серверами и может сама выступать в роли NTP-сервера, перераспределяя локальные часы. OpenNTPD изначально разрабатывался Хеннингом Брауэром в рамках проекта OpenBSD и выпускается в качестве базового компонента OpenBSD каждые шесть месяцев. Портативная версия, поддерживаемая Брентом Куком, доступна в виде периодически выпускаемых tar-архивов. Приветствуются любые дополнения как к ядру OpenNTPD, так и к фреймворку портативной сборки. Программное обеспечение может свободно использоваться и повторно использоваться любым лицом в соответствии с лицензией BSD. По умолчанию OpenNTPd использует серверы pool.ntp.org (это огромный кластер серверов точного времени) и работает только как клиент. Этот проект Лицензируется под Этот проект Лицензируется под BSD (Berkeley Software Distribution). ${NC}"
echo " Домашняя страница: https://www.openntpd.org/ ; (https://www.ntppool.org/ru/ ; https://archlinux.org/packages/extra/x86_64/openntpd/). "
echo -e "${BLUE}:: ${NC}Конфигурация: Настройка OpenNTPD осуществляется в файле /etc/ntpd.conf. Некоторые возможности: Синхронизация с одним сервером — нужно отредактировать директиву server. Например: /etc/ntpd.conf server time.cloudflare.com. Синхронизация с несколькими серверами — используется директива servers. Если DNS-имя resolves на несколько IP-адресов, синхронизируются все из них. По умолчанию — 2.arch.pool.ntp.org. Если компьютер, на котором запущен OpenNTPD, также будет сервером времени, нужно uncomment и отредактировать директиву listen. Например: /etc/ntpd.conf listen on * — будет слушать на всех интерфейсах, /etc/ntpd.conf listen on 127.0.0.1 listen on ::1 — только на интерфейсе loopback. Как пользоваться пулом NTP? Driftfile /var/lib/ntp/ntp.drift — это строка в конфигурационном файле NTP, которая указывает на файл для хранения информации о частоте смещения времени. "
echo -e "${CYAN}:: ${NC}Ошибки: Некоторые ошибки, которые могут возникать при работе OpenNTPD на Arch Linux, и способы их решения: Ошибка «no reply received in time, skipping initial time setting» — может возникать, если на сервере запускается и используется собственный DNS-сервис, а в /etc/ntpd.conf используются DNS-имена (например, pool.ntp.org). Решение — использовать сценарий /usr/bin/openntpd-wait-resolver-alive, который вызывается из openntpd.service перед ntpd через ExecStartPre. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да  — установить OpenNTPD (OpenBSD NTP Daemon),     0 - НЕТ - Пропустить установку: " in_openntpd  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_openntpd" =~ [^10] ]]
do
    :
done
if [[ $in_openntpd == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_openntpd == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) OpenNTPD (OpenBSD NTP Daemon)(openntpd) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
