# sudo pacman -R --noconfirm --needed ntp  #  Удалить пакет, не удаляя его зависимости
# sudo pacman -Rs ntp  # Удалить пакет, его зависимости, а также все пакеты, для которых он сам является зависимостью
# sudo pacman -Rs ntp --noconfirm
#sudo pacman -R ntpdate  # Удалите стандартный сервис
sudo pacman -S --noconfirm --needed openntpd  # Бесплатная и простая в использовании реализация сетевого протокола времени ; https://archlinux.org/packages/extra/x86_64/openntpd/ ; https://www.openntpd.org/ ; Конфликты: с ntp ; 2025-03-21 22:31 UTC
# sudo pacman -Rs openntpd  # В случае возникновения ошибок при установке пакета
