### Важно понимать, что слой сервера не может рассматриваться как показатель его точности или надёжности. Обычно для синхронизации пользовательских машин используются stratum 2 серверы. Если вы ещё не знаете, к каким серверам вы собираетесь подключиться, вам следует выбрать пул серверов, расположенный недалеко от вашего местоположения, из списка серверов на pool.ntp.org (https://www.pool.ntp.org/) (альтернативная ссылка - https://support.ntp.org/bin/view/Servers/NTPPoolServers). Arch Linux использует свой собственный стандартный пул NTP-серверов, который предоставляет the NTP Pool Project (https://www.pool.ntp.org/)(смотрите FS#41700 - https://bugs.archlinux.org/task/41700)
