# sudo ntpdate 1.ru.pool.ntp.org  # Список общедоступных NTP серверов доступен на сайте http://ntp.org
# sudo ntpdate 2.ru.pool.ntp.org  # Отредактируйте /etc/ntp.conf для добавления/удаления серверов (server)
# sudo ntpdate 3.ru.pool.ntp.org  # После изменений конфигурационного файла вам надо перезапустить ntpd (sudo service ntp restart) - Просмотр статуса: (sudo ntpq -p)
### Измените его под свои нужды, например если вы хотите использовать сервера своей страны: /etc/ntp.conf
# server 0.ru.pool.ntp.org iburst
# server 1.ru.pool.ntp.org iburst
# server 2.ru.pool.ntp.org iburst
# server 3.ru.pool.ntp.org iburst
# Опция 'iburst' рекомендуется, с ее помощью посылается шквал пакетов, если не удается установить соединение с сервером с первого раза. Напротив, опцию 'burst' не используйте никогда без особого разрешения, так как Вы можете попасть в "черный список".
  echo ""
  echo " Добавим в автозагрузку OpenNTPD (openntpd.service) "
sudo systemctl enable openntpd.service  # Запуск ntpd при загрузке системы
sudo systemctl start openntpd.service  # Включите службу ntpd.service
