  <<< Установка утилит (пакетов) — Брандмауэр (для контроля входящего и исходящего сетевого трафика) в Archlinux 🔥™ >>> ${NC}"
# Installing Firewall utilities (packages) (for monitoring incoming and outgoing network traffic) in Archlinux
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Брандмауэр — одно из наиболее часто используемых слов в терминах сетевой безопасности, используемых для защиты вашей сети. Брандмауэр — программа, предназначенная для контроля входящего и исходящего сетевого трафика. Брандмауэр работает по принципу фильтрации пакетов. Когда данные поступают в систему или отправляются из нее, они проходят через брандмауэр, который применяет к ним заранее настроенные правила. Эти правила могут блокировать, разрешать или перенаправлять трафик. Брандмауэр помогает защищать систему от несанкционированного доступа, атак и других сетевых угроз, а также распределять трафик в сети. Межсетевые экраны — важнейший компонент любой безопасной системы, поскольку они защищают от несанкционированного доступа, утечек данных и различных видов кибератак. ${NC}"
sleep 15
clear
echo ""
echo -e "${BLUE}:: ${NC}Установить UFW (Uncomplicated Firewall) (ufw gufw) — Межсетевой экран?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Для Arch Linux доступно несколько брандмауэров, но два самых популярных — это UFW (Uncomplicated Firewall) и FirewallD (firewalld). Оба брандмауэра просты в установке и настройке, предлагая хороший баланс между безопасностью и простотой использования. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}UFW (Простой брандмауэр) — это программа для управления брандмауэром (межсетевым экраном) Netfilter (netfilter), которое основано на IPTables (выступает в качестве интерфейса для легендарных iptables). Она предоставляет интерфейс командной строки и стремится быть простой и удобной в использовании. Он предоставляет удобный способ настройки брандмауэра по умолчанию для Linux. Команды в UFW идентичны английским, что облегчает их запоминание. UFW поддерживает как IPv4, так и IPv6 (сетевые протоколы). Следует отметить, что UFW может использовать как iptables, так и nftables в качестве внутреннего брандмауэра. Пользователям, привыкшим обращаться к UFW для управления правилами, не нужно предпринимать никаких действий для изучения базовых вызовов iptables или nftables благодаря поддержке nft синтаксиса iptables, например, в /etc/ufw/before.rules . Этот проект Лицензируется под GPL3. ${NC}"
echo " Домашняя страница: https://launchpad.net/ufw ; (https://costales.github.io/projects/gufw/ ; https://archlinux.org/packages/extra/any/ufw/ ; https://archlinux.org/packages/extra/any/gufw/ ; https://wiki.archlinux.org/title/Uncomplicated_Firewall). "
echo -e "${BLUE}:: ${NC}Gufw — является графическим интерфейсом (GUI) для межсетевого экрана (утилиты) ufw (Uncomplicated Firewall) для управления политиками безопасности межсетевого экрана. Gufw — очень простой и функциональный файрвол. Позволяет пропускать или блокировать сетевые пакеты в соответствии с заданными правилами. Можно настроить работу с сетью для определенного приложения или протокола, или ввести произвольные параметры обработки пакетов. Интерфейс программы выполнен просто и понятно. В главном окне отображается список правил обработки сетевых пакетов. Настройка новых правил в Gufw выполняется в графическом режиме. Вы просто последовательно выбираете из готовых списков действия, которые необходимо выполнить, вводите необходимые параметры (ip-адреса, порты), нажимаете кнопку Добавить, и новое правило тут же начинает работать. Также есть предустановленные правила для некоторых программ, работающих с сетью. Можно, например, запретить выход в интернет для определенного приложения или, например, запретить FTP протокол. Gufw создан с целью сделать интуитивно понятное и простое в использовании приложение! "
echo -e "${CYAN}:: ${NC}Если Вы "Дока", то настройте под свои нужды утилиту 'Iptables'(firewall). UFW — это мощный инструмент, который при правильной настройке может значительно повысить безопасность вашего сетевого трафика. Для получения более подробной информации о каждом параметре команды и доступных модификаторах вы можете воспользоваться утилитой man, чтобы проверить руководство UFW: man ufw "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
