sudo pacman -S --noconfirm --needed nftables  # Таблицы Netfilter, инструменты пользовательского пространства ; https://archlinux.org/packages/extra/x86_64/nftables/ ; https://netfilter.org/projects/nftables/ ; 2025-04-23 18:47 UTC
sudo pacman -S iptables-nft  # Инструмент управления пакетами ядра Linux (использующий интерфейс NFT) ; https://archlinux.org/packages/core/x86_64/iptables-nft/ ; https://www.netfilter.org/projects/iptables/index.html ; Обеспечивает: arptables, ebtables, iptables , libip4tc.so=2-64, libip6tc.so=2-64,..., Конфликты: c arptables, ebtables, iptables ; Базовый пакет: iptables ; 2025-03-31 16:30 UTC
#sudo pacman -S --noconfirm --needed iptables-nft  # Инструмент управления пакетами ядра Linux (использующий интерфейс NFT) ; https://archlinux.org/packages/core/x86_64/iptables-nft/ ; https://www.netfilter.org/projects/iptables/index.html ; Обеспечивает: arptables, ebtables, iptables , libip4tc.so=2-64, libip6tc.so=2-64,..., Конфликты: c arptables, ebtables, iptables ; Базовый пакет: iptables ; 2025-03-31 16:30 UTC
############ ufw gufw ##############
sudo pacman -S --noconfirm --needed ufw  # Простой и удобный в использовании инструмент командной строки для управления брандмауэром Netfilter ; https://archlinux.org/packages/extra/any/ufw/ ; https://launchpad.net/ufw ; 2024-12-22 13:53 UTC
sudo pacman -S --noconfirm --needed gufw  # Простой способ управления брандмауэром Linux ; https://archlinux.org/packages/extra/any/gufw/ ; https://costales.github.io/projects/gufw/ ; 2025-06-14 21:24 UTC
sudo pacman -S --noconfirm --needed ufw-extras  # Дополнительные файлы конфигурации для UFW ; https://archlinux.org/packages/extra/any/ufw-extras/ ; https://github.com/xyproto/ufw-extras ; 2024-04-10 09:36 UTC
  echo ""
