echo -e "${CYAN}
  <<< Запуск и добавление в автозапуск — Брандмауэра UFW (Uncomplicated Firewall) (*если таковой был вами установлен), включение сервисов и служб, а также зададим политики для UFW, запустим логгирование (журналы работы брандмауэра), добавим разрешающее правило для служб и портов >>> ${NC}"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Настройка брандмауэра на Arch Linux — это важный шаг для защиты вашей системы от несанкционированного доступа и киберугроз. Поэтому в сценарии (скрипта) решил разделить пункты настройки брандмауэра, чтобы пользователь мог сделать свой выбор, если вам не нужны какие либо действия (настройки), вы сможете пропустить это действие сценария. ${NC}"
