echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс выполнения был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
#echo " Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter") "
