fi
############ Справка ##############
# UFW и вообще все инструменты брандмауэра используют «правила» для включения или выключения приема/прибытия пакетов на любой компьютер. Поэтому по умолчанию вы должны разрешить передачу любого исходящего трафика и отклонить любой входящий трафик.
### Настройка политики UFW по умолчанию:
# Конфигурация UFW по умолчанию разрешает все исходящие соединения и запрещает все входящие. Эти два правила типичны для персональных компьютеров, которые ожидают любых входящих запросов.
# Чтобы запретить входящие соединения:
# sudo ufw default deny incoming
# Разрешить исходящие соединения с:
# sudo ufw default allow outgoing
####################################

clear
echo ""
echo -e "${BLUE}:: ${NC}Запустить Логгирование (журналы работы брандмауэра) для UFW (Uncomplicated Firewall)?"
echo -e "${YELLOW}=> Примечание! ${BOLD} *В Ufw есть опция сохранения логов — журнал событий. Для запуска, используйте команду: 'sudo ufw logging on'. Ufw поддерживает нескоько уровней логгирования: off — отключен; low — регистрирует все заблокированные пакеты, не соответствующие заданной политике (с ограничением скорости), а также пакеты, соответствующие зарегистрированным правилам. Чтобы отлаживать работу UFW, могут понадобится журналы работы брандмауэра. Для включения журналирования используется команда: 'logging'. Лог сохраняется в директории (папке): /var/log/ufw ${NC}"
echo -e "${CYAN}:: ${BOLD}По умолчанию журналы UFW хранятся в /var/log/ufw.log . Вы можете контролировать и просматривать файл журнала с помощью команды: 'tail'. Пример: 'sudo tail -f /var/log/ufw.log' ${NC}"
echo -e "${MAGENTA}=> ВАЖНО: ${NC}Командой 'logging' можно изменить уровень логгирования: low (используется по умолчанию) - минимальный, только заблокированные пакеты; medium — все то, что при значении low. Плюс все разрешенные пакеты, не соответствующие заданной политике, все недопустимые пакеты, и все новые соединения. Все записи ведутся с ограничением скорости; high — работает также как и medium. Плюс все пакеты с ограничением скорости; full — также как и high, но без ограниения скорости. По умолчанию заложил в сценарий (скрипта) medium - средний, заблокированные и разрешённые пакеты. Пример: 'sudo ufw logging medium' . Для просмотра файлов относящихся с логам ufw используйте команду: 'ls /var/log/ufw*' "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс выполнения был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
#echo " Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter") "
#read -p " 1 - Да установить, 0 - НЕТ - Пропустить установку: " prog_set  # To confirm the input actions, click 'Enter' ; # Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter")
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да - Настроить Логгирование (журналы работы брандмауэра),   0 - НЕТ - Пропустить установку: " i_journal  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$i_journal" =~ [^10] ]]
do
    :
done
if [[ $i_journal == 0 ]]; then
echo ""
echo " Создание Логгирования (журналов работы брандмауэра) UFW пропущено "
elif [[ $i_journal == 1 ]]; then
  echo ""
  echo " Запуск Логгирование (журналы работы брандмауэра) для UFW "
  sudo ufw logging on   # Запуск Логгирование UFW
  echo " Запуск Логгирование UFW (medium - средний, заблокированные и разрешённые пакеты) "
  sudo ufw logging medium   # Логгирование UFW (medium - средний, заблокированные и разрешённые пакеты)
# sudo ufw logging high  #  Логгирование UFW (high - работает также как и medium)
# sudo journalctl -u firewalld.service -f   # Мониторинг журналов - доступ к системному журналу
echo ""
echo " Запуск Логгирование (журналы работы брандмауэра) для UFW выполнен "
fi
######## Справка ##########
# Логи:
# В Ufw есть опция сохранения логов — журнал событий. Для запуска, используйте команду:
# sudo ufw logging on
# Ufw поддерживает нескоько уровней логгирования:
# off — отключен.
# low — регистрирует все заблокированные пакеты, не соответствующие заданной политике (с ограничением скорости), а также пакеты, соответствующие зарегистрированным правилам.
# medium — все то, что при значении low. Плюс все разрешенные пакеты, не соответствующие заданной политике, все недопустимые пакеты, и все новые соединения. Все записи ведутся с ограничением скорости.
# high — работает также как и medium. Плюс все пакеты с ограничением скорости.
# full — также как и high, но без ограниения скорости.
# Чтобы задать уровень, укажите его как параметр:
# sudo ufw logging high
# По умолчанию используется уровень low.
# Для просмотра файлов относящихся с логам ufw используйте команду:
# ls /var/log/ufw*
###########################

clear
echo ""
echo -e "${BLUE}:: ${NC}Добавить разрешающее правило для службы SSH и портов 22; 80; HTTP в UFW (Uncomplicated Firewall)?"
echo -e "${YELLOW}=> Примечание! ${BOLD} *После активации брандмауэра вы можете начать добавлять пользовательские правила для управления входящим и исходящим трафиком. Обычно при предоставлении удаленного доступа к Linux серверам вам предоставляется именно SSH (Secure Shell) доступ. SSH — это Первоклассный инструмент подключения для удаленного входа по протоколу SSH. Это великий инструмент управления серверов, с помощью него можно всё что угодно реализовать, веб-платформу, фтп-сервер, VPN или любые другие сервера на базе данной ОС. ${NC}"
echo -e "${CYAN}:: ${BOLD}SSH-демон по молчанию прослушивает порт 22. UFW знает об именах распространённых служб (ssh, sftp, http, https), поэтому вы можете использовать их вместо номера порта. Если ваш SSH-демон использует другой порт, вам необходимо указать его в явном виде, например: 'sudo ufw allow 2222'. ${NC}"
echo -e "${MAGENTA}=> ВАЖНО: ${NC}Добавление политики для определенных IP-адресов, подсетей и портов уже прописано в данном скрипте установки, но Закомментировано # . Список портов - (ssh; ssh/tcp; 22; 22/tcp; 2222/tcp; ftp; http; 80; 80/tcp; https; 443/tcp; 25; 25/tcp; 143; 143/tcp; 993; 993/tcp; 110; 995; 587/tcp; 465/tcp; 5433; 873). Раскомментировано - Список портов (ssh; 22; 22/tcp; 80/tcp). Также Вы сможете просмотреть текущие правила и разрешения для брандмауэра UFW. "
echo -e "${MAGENTA}=> ${NC}Добавление правил: В скрипте прописано - профиль OpenSSH, который разрешит все входящие SSH-соединения на стандартном порту SSH (22). Она разрешает любой доступ к порту tcp 22. Поддерживаются оба протокола TCP и UDP. Также прописано разрешение порта (80) для HTTP (веб-сервер). Если вы используете пользовательский SSH-порт (например, порт 2222), вам необходимо открыть этот порт на брандмауэре UFW (правило прописано в скрипте, но закомментировано # ). Блокировка и лимит (Ограничение SSH-соединения) по использованию всех подключения SSH (правило прописано в скрипте, но закомментировано # ). Иногда это может помочь в предотвращении атак DOS. "
echo -e "${CYAN}:: ${BOLD}Используя UFW, вы можете создавать правила брандмауэра (или политики) для разрешения или запрета определенной службы. С помощью этих политик вы указываете UFW, какие порты, службы, IP-адреса и интерфейсы должны быть разрешены или запрещены. ${NC}"
echo -e "${MAGENTA}=> ВАЖНО: ${NC}Если вы настраиваете ufw на удаленном сервере, убедитесь, что вы разрешили порт или службу ssh перед включением брандмауэра ufw. Политика входящих соединений по умолчанию будет запрещать все входящие соединения. Поэтому если вы не настроили правила для разрешения SSH, вы будете заблокированы в удаленной системе и не сможете войти в нее. В качестве альтернативы можно использовать команду 'ufw allow', чтобы установить политики по умолчанию для входящих и исходящих команд. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс выполнения был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да - Разрешить службу SSH и портов 22; 80 для HTTP,     0 - НЕТ - Пропустить установку: " i_ssh_ufw  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$i_ssh_ufw" =~ [^10] ]]
do
    :
done
if [[ $i_ssh_ufw == 0 ]]; then
echo ""
echo " Добавление разрешающего правила службы SSH и портов 22; 80 для HTTP в UFW пропущена "
elif [[ $i_ssh_ufw == 1 ]]; then
  echo ""
  echo " Добавление разрешающего правила службы SSH и портов 22; 80 для HTTP в UFW (сетевой экран) "
  echo " Разрешить службу SSH (по умолчанию) "
  sudo ufw allow ssh   # Разрешить входящий трафик (SSH)
# sudo ufw limit ssh  # ограничить соединения ssh до 6 в течение 30 секунд
# sudo ufw allow ssh/tcp
# sudo ufw deny ssh/tcp  # Заблокировать все подключения SSH
  echo " Разрешить определенный порт, например 22; 80 для HTTP (по умолчанию) "
  sudo ufw allow 22  # SSH (Secure Shell): Порт 22
  sudo ufw allow 22/tcp  # (OpenSSH)
  sudo ufw allow 9050
# sudo ufw allow 2222/tcp  # пользовательский SSH-порт (например, порт 2222)
# sudo ufw allow ftp
# sudo ufw allow http  # разрешить все входящие соединения HTTP (порт 80)
  sudo ufw allow 53/tcp
  sudo ufw allow 43/tcp
# sudo ufw allow 80
sudo ufw allow 80/tcp  # Разрешить порт 80 для HTTP (веб-сервер)
# sudo ufw allow 64738/tcp  # (Mumble)
# sudo ufw allow 64738/udp  # пользовательский Mumble-порт (например, порт 64738)
# sudo ufw delete allow 80  # не хотите разрешать HTTP-трафик
# sudo ufw allow https  # разрешить все входящие подключения HTTPS (порт 443)
sudo ufw allow 443/tcp  # HTTPS (защищенный веб-сервер): порт 443 - 80,443/tcp (Apache Full)
# sudo ufw allow proto tcp from any to any port 80,443  # разрешить входящие соединения HTTP и HTTPS
# sudo ufw allow 25  # разрешить серверу отвечать на все входящие SMTP-соединения ; SMTP (почтовый сервер)
# sudo ufw allow 25/tcp  # разрешить трафик SMTP для отправки электронной почты
# sudo ufw limit 25/tcp  # Ограничение скорости : чтобы снизить вероятность атак методом подбора, особенно на портах SMTP
# sudo ufw deny out 25  # заблокировать исходящую почту SMTP
# sudo ufw allow 143  # разрешить входящие IMAP-соединения ; IMAP (получение почты)
# sudo ufw allow 143/tcp
# sudo ufw allow 993  # разрешить входящие IMAPS
# sudo ufw allow 993/tcp
# sudo ufw allow 110  # разрешить входящие POP3-соединения ; POP3 (получение почты)
# sudo ufw allow 995  # разрешить входящие POP3S-соединения
# sudo ufw allow 587/tcp  # рекомендуется для отправки по TLS
# sudo ufw limit 587/tcp  # Ограничение скорости : чтобы снизить вероятность атак методом подбора, особенно на портах SMTP
# sudo ufw allow 465/tcp  # для SMTPS (SMTP через SSL)
# sudo ufw allow 5433  # подключиться к PostgreSQL, работающему на порту 5433
# sudo ufw deny 5433  # для отклонения входящих соединений (трафика) на порту 5433
# sudo ufw allow 873  # Программа Rsync, которая работает на порту 873, может использоваться для передачи файлов с одного компьютера на другой. Следующая команда разрешит только соединения Rsync, поступающие с IP-адреса 91.198.174.33
# sudo ufw deny 873  # для отклонения входящих соединений (трафика) на порту
# sudo ufw allow
# sudo ufw deny   # для отклонения входящих соединений (трафика) на порту
  echo " Просмотреть текущие правила для брандмауэра UFW (сетевой экран) "
  sudo ufw status verbose
  echo " Проверка разрешений приложения через брандмауэр UFW (сетевой экран) "
  sudo ufw status numbered
  sudo ufw app list
  sudo ufw reload
echo ""
echo " Установка правил по умолчанию для UFW (сетевой экран) выполнена "
fi
sleep 03
########## Справка ##############
# Настройка служб и портов в Linux: При настройке брандмауэра важно учитывать, какие службы и порты вам необходимо разрешить. Вот некоторые распространенные службы и соответствующие им порты:
# SSH (Secure Shell): Порт 22
# HTTP (веб-сервер): порт 80
# HTTPS (защищенный веб-сервер): порт 443
# FTP (протокол передачи файлов): порты 20 и 21
# SMTP (почтовый сервер): порт 25
# IMAP (получение почты): порт 143
# POP3 (получение почты): порт 110
# SMTP (порт 25/587/465) : разрешить трафик SMTP для отправки электронной почты
# Более полный список служб и портов можно найти в Реестре имен служб и номеров портов транспортных протоколов IANA (https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml)
# Настройте UFW для поддержки IPv6:
# Если система использует IPv4 и IPv6 , измените файл конфигурации UFW для поддержки обоих протоколов:
# 1. Откройте файл конфигурации UFW по умолчанию с помощью nano или любого другого текстового редактора :
# sudo nano /etc/default/ufw
# Файл конфигурации /etc/default/ufw ipv6
# 2. Проверьте IPV6значение. Если значение равно no, измените его на , yesчтобы включить использование IPv6.
# 3. Сохраните и закройте файл.
################################

clear
echo ""
echo -e "${BLUE}:: ${NC}Установить FirewallD (firewalld) — Межсетевой экран?"
echo -e "${YELLOW}==> Предисловие! ${BOLD} *На некоторых дистрибутивах Linux firewalld устанавливается автоматически, включая многие образы. Однако также может потребоваться установить firewalld вручную. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}FirewallD — демон брандмауэра с интерфейсом D-Bus, обеспечивающий динамический брандмауэр разработанный Red Hat. Он по умолчанию использует nftables . Он является межсетевым экраном по умолчанию для нескольких основных дистрибутивов Linux, включая Fedora и RHEL, и известен своей гибкостью и простотой использования. firewalld предоставляет динамически управляемый межсетевой экран с поддержкой сетей и зон межсетевого экрана для определения уровня доверия сетевых подключений или интерфейсов. Он поддерживает настройки межсетевого экрана IPv4 и IPv6, а также Ethernet-мосты (наборы IP-адресов), а также разделяет параметры конфигурации среды выполнения и постоянной конфигурации. Он также предоставляет интерфейс для служб и приложений для непосредственного добавления правил ip*tables и ebtables. Преимущества использования firewalld: Изменения можно вносить немедленно в среду выполнения. Перезапуск службы или демона не требуется. Интерфейс D-Bus Firewalld позволяет службам, приложениям и пользователям легко настраивать параметры брандмауэра. Интерфейс является полным и используется для инструментов настройки брандмауэра firewall-cmd, firewall-config и firewall-applet. Этот проект Лицензируется под GPL-2.0 или более поздняя. ${NC}"
echo " Домашняя страница: https://firewalld.org/ ; (https://wiki.archlinux.org/title/Firewalld ; https://archlinux.org/packages/extra/any/firewalld/). "
echo -e "${BLUE}:: ${NC}Функции: Полный API D-Bus. Поддержка IPv4, IPv6, мостов и ipset. Поддержка IPv4 и IPv6 NAT. Зоны брандмауэра. Предопределенный список зон, сервисов и типов ICMP. Простой сервис, порт, протокол, исходный порт, маскировка, переадресация портов, фильтр ICMP, расширенные правила, интерфейс и обработка исходных адресов в зонах. Простое определение сервиса с портами, протоколами, исходными портами, модулями (помощниками netfilter) и обработкой адресов назначения. Богатый язык для более гибких и сложных правил в зонах. Временные правила брандмауэра в зонах. Простой журнал отклоненных пакетов. Прямой интерфейс. Блокировка: белый список приложений, которые могут изменять брандмауэр. Автоматическая загрузка модулей ядра Linux. Интеграция с Puppet. Клиенты командной строки для онлайн- и офлайн-настройки. Графический инструмент настройки с использованием gtk3. Апплет, использующий Qt5. "
echo -e "${CYAN}:: ${NC}Разделение конфигурации среды выполнения и постоянной конфигурации позволяет проводить оценку и тестирование в среде выполнения. Конфигурация среды выполнения действительна только до следующей перезагрузки и перезапуска службы или до перезагрузки системы. После этого постоянная конфигурация будет загружена снова. С помощью среды выполнения можно использовать среду выполнения для настроек, которые должны быть активны только в течение ограниченного времени. Если конфигурация среды выполнения использовалась для оценки, является полной и работоспособной, то её можно сохранить в постоянной среде. Простое определение сервиса с портами, протоколами, исходными портами, модулями (помощниками netfilter) и обработкой адресов назначения. Богатый язык для более гибких и сложных правил в зонах. Правила брандмауэра с ограничением по времени в зонах. Простой журнал отклоненных пакетов. Прямой интерфейс. Для firewalld ведение журнала включено по умолчанию. Журналы Firewalld хранятся в системном журнале, доступ к которому можно получить с помощью команды: journalctl . Пример: sudo journalctl -u firewalld.service -f . Блокировка: белый список приложений, которые могут изменять брандмауэр. Автоматическая загрузка модулей ядра Linux. Интеграция с Puppet. Клиенты командной строки для онлайн и офлайн настройки. Графический инструмент настройки с использованием gtk3. Апплет с использованием Qt6. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_firewalld  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_firewalld" =~ [^10] ]]
do
    :
done
if [[ $in_firewalld == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_firewalld == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) FirewallD (firewalld) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) "
############ Зависимости ##############
sudo pacman -S --noconfirm --needed glibc  # Библиотека GNU C ; https://archlinux.org/packages/core/x86_64/glibc/ ; https://www.gnu.org/software/libc ; 2025-08-01 21:44 UTC
sudo pacman -S --noconfirm --needed glib2  # Базовая библиотека низкого уровня ; https://archlinux.org/packages/gnome-unstable/x86_64/glib2/ ; https://gitlab.gnome.org/GNOME/glib ; Обеспечивает:  libgio-2.0.so=0-64, libgirepository-2.0.so=0-64, libglib-2.0.so=0-64, libgmodule-2.0.so=0-64, libgobject-2.0.so=0-64, libgthread-2.0.so=0-64 ; 2025-07-24 14:23 UTC
sudo pacman -S --noconfirm --needed hicolor-icon-theme  # Freedesktop.org Тема иконок Hicolor ; https://archlinux.org/packages/extra/any/hicolor-icon-theme/ ; https://gitlab.freedesktop.org/xdg/default-icon-theme ; 2024-05-24 01:53 UTC
sudo pacman -S --noconfirm --needed nftables  # Таблицы Netfilter, инструменты пользовательского пространства ; https://archlinux.org/packages/extra/x86_64/nftables/ ; https://netfilter.org/projects/nftables/ ; 2025-04-23 18:47 UTC
sudo pacman -S --noconfirm --needed python-capng  # Библиотека для Linux, упрощающая использование возможностей posix (привязки Python) ; https://archlinux.org/packages/core/x86_64/python-capng/ ; https://people.redhat.com/sgrubb/libcap-ng/ ; Обеспечивает: python-libcap-ng ; 2024-12-22 12:39 UTC
sudo pacman -S --noconfirm --needed python-dbus  # Привязки Python для D-Bus ; https://archlinux.org/packages/extra/x86_64/python-dbus/ ; https://www.freedesktop.org/wiki/Software/dbus/ ; Обеспечивает: dbus-python=1.4.0, python-dbus-common=1.4.0 ; Заменяет: dbus-python, python-dbus-common ; Конфликты: с dbus-python, python-dbus-common ; 24.03.2025 15:32 UTC
sudo pacman -S --noconfirm --needed python-gobject  # Привязки Python для GLib/GObject/GIO/GTK ; https://archlinux.org/packages/extra/x86_64/python-gobject/ ; https://pygobject.gnome.org/ ; Обеспечивает: pygobject-devel=3.52.3 ; Заменяет: pygobject-devel<=3.36.1-1 ; Конфликты: с pygobject-devel ; 2025-03-24 03:58 UTC
