sudo pacman -S --noconfirm --needed gtk3   # (необязательно) - firewall-config ; Мультиплатформенный набор графических инструментов на основе GObject ; https://archlinux.org/packages/extra/x86_64/gtk3/ ; https://www.gtk.org/ ; Обеспечивает: gtk3-print-backends, libgailutil-3.so=0-64, libgdk-3.so=0-64, libgtk-3.so=0-64 ; Заменяет: gtk3-print-backends<=3.22.26-1 ; Конфликты: с gtk3-print-backends ; 2025-05-14 00:11 UTC
sudo pacman -S --noconfirm --needed libnotify  # (необязательно) - брандмауэр-апплет ; Библиотека для отправки уведомлений на рабочий стол ; https://archlinux.org/packages/extra/x86_64/libnotify/ ; https://gitlab.gnome.org/GNOME/libnotify ; Обеспечивает: libnotify.so=4-64 ; 2025-03-29 00:39 UTC
sudo pacman -S --noconfirm --needed networkmanager  # (опционально) — поддержка NetworkManager ; Менеджер сетевых подключений и пользовательские приложения ; https://archlinux.org/packages/extra/x86_64/networkmanager/ ; https://networkmanager.dev/ ; 2025-08-03 04:17 UTC
