sudo pacman -S --noconfirm --needed git-zsh-completion  # Быстро распределенная система контроля версий ; https://archlinux.org/packages/extra/x86_64/git-zsh-completion/ ; https://git-scm.com/ ; 2025-07-14 10:22 UTC
sudo pacman -S --noconfirm --needed intltool  # Коллекция инструментов интернационализации ; https://archlinux.org/packages/extra/any/intltool/ ; https://launchpad.net/intltool ; 2020-06-21 15:27 UTC
sudo pacman -S --noconfirm --needed podman  # Инструмент и библиотека для запуска контейнеров на основе OCI в модулях ; https://archlinux.org/packages/extra/x86_64/podman/ ; https://github.com/containers/podman ; 2025-06-27 08:21 UTC
