sudo pacman -S --noconfirm --needed firewalld # Демон брандмауэра с интерфейсом D-Bus ; https://firewalld.org/ ; https://archlinux.org/packages/extra/any/firewalld/ ; https://github.com/firewalld/firewalld/issues ; 2025-06-12 08:10 UTC
  echo ""
  echo " Включить FirewallD (firewalld) и запустить службу (firewalld.service) "
sudo systemctl enable firewalld.service
sudo systemctl start firewalld.service
echo " Установить зону по умолчанию как «публичную» и включить брандмауэр "
sudo firewall-cmd --set-default-zone=public
sudo firewall-cmd --get-default-zone  # Чтобы узнать, какая зона в данный момент установлена по умолчанию
sudo firewall-cmd --get-active-zones  # Чтобы узнать, какая зона в данный момент будет активной
sudo firewall-cmd --get-zones  # можно узнать информацию о других доступных зонах
echo " Открыть порты, через которые разрешены соединения для демона OpenSSH "
echo " Чтобы открыть службу или порт в firewalld, используйте параметры --add-serviceили --add-port "
echo " Разрешить определенный порт, например порт 80 для HTTP "
sudo firewall-cmd --zone=public --add-service=ssh --permanent  # чтобы разрешить SSH
### Как правило, в поле «ports» указаны порты, через которые разрешены соединения
sudo firewall-cmd --permanent --add-port=22/tcp
# sudo firewall-cmd --remove-port=22/tcp  # Для удаления порта из правил используется параметр --remove-port
sudo firewall-cmd --zone=public --add-port=80/tcp --permanent  # чтобы разрешить определенный порт, например порт 80 для HTTP
# sudo firewall-cmd --permanent --remove-port=80/tcp  # Удалим правило для открытия 80-о порта
sudo firewall-cmd --list-services  # Запросите текущие сервисы в firewalld и их характеристики
sudo firewall-cmd --reload  # Чтобы правила применялись (перезагрузить брандмауэр после внесения изменений)
### Чтобы убедиться, что firewalld успешно запустился, выполните следующую команду:
#sudo firewall-cmd --state
### Чтобы окончательно отключить брандмауэр в системе, выполните следующие действия:
# sudo systemctl stop firewalld  # временно остановить Службу FirewallD
# sudo systemctl stop firewalld  # Сначала остановите службу FirewallD
# sudo systemctl disable firewalld  # Отключите автоматический запуск службы FirewallD при загрузке системы
### Замаскируйте службу FirewallD, чтобы запретить другим службам запускать брандмауэр:
# sudo systemctl mask --now firewalld
echo " Проверить состояние firewalld и просмотреть текущие правила "
# sudo firewall-cmd --state  # Для просмотра текущего состояния службы FirewallD
# sudo systemctl status firewalld  # команда для проверки состояния брандмауэра firewalld в операционных системах Linux
sudo firewall-cmd --list-all  # Чтобы узнать, какие правила установлены для зоны public (проверить состояние firewalld и просмотреть текущие правила)
# sudo firewall-cmd --list-ports
  echo ""
  echo " Посмотрите информацию о версии (firewalld) "
sudo pacman -Q firewalld  #  Показать версию приложения ; Альтернативный метод — проверить версию установленного пакета NTP через менеджер пакетов системы.
# sudo pacman -Qs имя_пакета  # Используйте команду pacman с -Qsопцией поиска только среди установленных пакетов в системе. Она ищет указанный текст только в названиях и описаниях установленных пакетов.
# sudo pacman -Qi имя_пакета  # Эта -Qiопция отображает подробную информацию об указанном пакете. Она также показывает метаданные пакета, такие как зависимости, конфликты, дата установки, дата сборки, размер и т. д.
# sudo pacman -Si имя_пакета  # Эта -Si опция позволяет просматривать подробную информацию о любых пакетах Arch Linux. Необходимо указать точное название пакета.
sleep 03
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
