clear
echo ""
echo -e "${BLUE}:: ${NC}Установить OpenSnitch (opensnitch) — Обязательный брандмауэр приложений для GNU/Linux?"
echo -e "${YELLOW}=> Примечание! ${BOLD} *Когда дело доходит до защиты вашей системы Linux от нежелательных сетевых подключений, необходим хороший брандмауэр. Хотя большинство пользователей Linux полагаются на традиционные брандмауэры, такие как iptables, firewalls или ufw, они обычно работают на сетевом уровне и не обеспечивают детальный контроль над тем, какие приложения могут подключаться к интернету. Здесь на помощь приходит OpenSnitch — брандмауэр приложений GNU/Linux, который позволяет контролировать исходящие соединения для каждого приложения по отдельности. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}OpenSnitch — это брандмауэр приложений с открытым исходным кодом для Linux, созданный по образцу популярного Little Snitch для macOS. Он отслеживает исходящие сетевые подключения и предупреждает вас всякий раз, когда программа пытается подключиться к интернету. Затем вы можете решить, разрешить или заблокировать подключение. Независимо от того, являетесь ли вы сторонником конфиденциальности или просто хотите обеспечить безопасность своей системы, OpenSnitch предоставляет вам необходимую прозрачность и контроль. Этот проект Лицензируется под GPL-3.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://netfilter.org/projects/nftables/ ; (https://archlinux.org/packages/extra/x86_64/nftables/). "
echo -e "${CYAN}:: ${NC}Ключевые особенности: Интерактивная фильтрация исходящих соединений. Блокируйте рекламу, трекеры и вредоносные домены (https://github.com/evilsocket/opensnitch/wiki/block-lists) по всей системе. Возможность настройки системного брандмауэра (https://github.com/evilsocket/opensnitch/wiki/System-rules) из графического интерфейса (nftables). Настройте политику ввода, разрешите входящие услуги и т. д. Управляйте несколькими узлами (https://github.com/evilsocket/opensnitch/wiki/Nodes) с помощью централизованного графического интерфейса. Интеграция SIEM (https://github.com/evilsocket/opensnitch/wiki/SIEM-integration). "
echo -e "${MAGENTA}:: ${BOLD}Зачем использовать OpenSnitch? Управляйте исходящими сетевыми запросами для каждого отдельного приложения. Посмотрите, какие приложения подключаются к каким серверам, IP-адресам и доменам. Полностью бесплатный, с кодом, доступным на GitHub. Поставляется с графическим интерфейсом для удобного управления правилами. Блокирует отправку данных подозрительными приложениями без вашего ведома. В отличие от традиционных брандмауэров, которые ориентированы на входящий трафик или общие правила, OpenSnitch ориентирован на исходящие соединения и приложения, которые их генерируют, что делает его идеальным решением для пользователей, которым нужен более строгий контроль над тем, что покидает их систему. OpenSnitch официально доступен в виде пакета для многих дистрибутивов Linux, таких как Ubuntu, Debian, Fedora, Arch Linux и других. ${NC}"
echo -e "${BLUE}:: ${NC}Как работает OpenSnitch: После установки и запуска OpenSnitch отслеживает каждое исходящее соединение, создаваемое вашими приложениями. При первой попытке нового приложения подключиться к интернету OpenSnitch выдаст всплывающее окно с вопросом, что делать. Вы увидите: Имя приложения и путь к нему. IP-адрес или домен, к которому он пытается подключиться. Используемый порт. Тогда вы можете выбрать: Разрешить один раз; Заблокируйте один раз; Всегда позволяйте; Всегда блокируйте. "
echo -e "${CYAN}:: ${NC}Управление правилами: Правила создаются каждый раз, когда вы подтверждаете или отклоняете подключение. Вы можете легко управлять ими в графическом интерфейсе: Просмотрите существующие правила. Отредактируйте или удалите их. Упорядочить по приложениям или доменам. Временно отключите правила или брандмауэр полностью. OpenSnitch сохраняет эти правила в обычных текстовых файлах, поэтому при необходимости вы даже можете редактировать их вручную (обычно они находятся в /etc/opensnitch/rules/). "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
