clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Vuurmuur (vuurmuur) — Управление работой межсетевого экрана?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Vuurmuur  (брандмауэр на голландском) - мощный межсетевой экран / Firewall-менеджер, представляющий собой надстройку к консольной утилите Iptables. Iptables — консольная утилита являющаяся стандартным интерфейсом для управления работой межсетевого экрана (брандмауэра). Иногда под словом iptables имеется в виду и сам межсетевой экран netfilter. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Vuurmuur — мощный менеджер межсетевых экранов, построенный на базе iptables для Linux. Он имеет простую и понятную конфигурацию, позволяющую создавать как простые, так и сложные конфигурации. Конфигурацию можно полностью настроить через графический интерфейс Ncurses, обеспечивающий безопасное удалённое администрирование через SSH или консоль. Vuurmuur поддерживает шейпинг трафика и обладает мощными функциями мониторинга, позволяющими администратору просматривать журналы, соединения и использование полосы пропускания в режиме реального времени. При помощи графического интерфейса, на базе ncurses (библиотека, предназначенная для управления вводом/выводом на терминал) Vuurmuur позволяет удобно создавать простые и сложные конфигурации.  Для использования Vuurmuur, как и утилиты iptables, требуются привилегии суперпользователя (root). А с Ncurses GUI отпадает необходимость в X Window (оконная система/графическая среда). Vuurmuur поддерживает формирование трафика, обладает мощными и удобными функциями мониторинга (просмотр логов и соединений, фильтрация при просмотре логов, поиск по старым логам), позволяющими администратору следить за логами, соединениями и трафиком в режиме реального времени (логи находятся /var/log/vuurmuur/*.log). Имеет безопасную политику "по умолчанию", записывает все изменения, о всех новых соединениях и подозрительных пакетах, ведёт подсчёт трафика. Имеет скрипты для интеграции с другими инструментами.В Vuurmuur реализовано лёгкое перенаправление портов, лёгкая настройка NAT (Network Address Translation / преобразование сетевых адресов), имеет средство противодействия IP-спуфингу (вид хакерской атаки заключающийся в использовании чужого IP-адреса с целью обмана системы безопасности) и возможность обрыва нежелательных соединений. Vuurmuur — программное обеспечение с открытым исходным кодом, распространяемое на условиях GNU GPL. ${NC}"
echo " Домашняя страница: http://www.vuurmuur.org/ ; (http://iptrafficvolume.sourceforge.net/ ; https://aur.archlinux.org/packages/vuurmuur) "
echo -e "${BLUE}:: ${NC}Функции: Администрация: знание iptables не требуется; синтаксис правил, понятных человеку; IPv6; формирование трафика. Графический интерфейс Ncurses, X не требуется. Переадресация портов стала очень простой; легко настроить с помощью NAT; безопасная политика по умолчанию. Полностью управляется через ssh и из консоли (в том числе из Windows с помощью PuTTY). Возможность создания сценариев для интеграции с другими инструментами; может создать скрипт брандмауэра bash. Функции защиты от спуфинга; уничтожение нежелательных связей. Поддерживает работу с Suricata IPS (https://suricata.io/) с использованием NFQUEUE или NFLOG. *Мониторинг: Просмотр журнала в реальном времени; просмотр соединения в реальном времени; фильтрация при просмотре журналов и просмотре подключений; базовый учет объема трафика; поиск в старых файлах журналов. Ведение журнала аудита: все изменения регистрируются; ведение журнала новых подключений и плохих пакетов; учет объема трафика. "
echo -e "${CYAN}:: ${NC}Vuurmuur полностью управляем через ssh (сетевой протокол сеансового уровня) или консоли (в том числе через PuTTY для Windows). Есть возможность сборки bash-скрипта для установки правил для iptables без использования vuurmuur. Работает с Snort (система обнаружения и предотвращения вторжений) при помощи QUEUE или NFQUEUE (технологии в сетевых маршрутизаторах). Vuurmuur подробно документирована (в том числе и на русском), документация доступна по man vuurmuur или в каталоге: /usr/share/vuurmuur и перед работой с приложением её рекомендуется изучить. "
echo -e "${CYAN}:: ${NC}Установка Vuurmuur (vuurmuur) и (iptrafvol), проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/vuurmuur.git), (https://aur.archlinux.org/iptrafvol.git) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
