echo -e "${BLUE}:: ${NC}Установить ClamAV ® (Clam Antivirus) (clamav, clamtk) — Антивирус для Linux?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *ClamAV — ветеран в мире Linux. Этот антивирус бесплатен и обладает открытым исходным кодом. В основном он применяется на серверах, но и для домашнего использования хорошо подойдёт. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}ClamAV ® — это антивирусный движок с открытым исходным кодом для обнаружения троянов, вирусов, вредоносных программ и других вредоносных угроз. ClamAV ® — это стандарт для программного обеспечения для сканирования почтовых шлюзов. Одно из популярных применений ClamAV это сканирование на лету электронной почты на почтовых шлюзах (проверка файлов вложений). Для этого используется интеграция с другими службами. ClamAV включает в себя многопоточный демон сканера, утилиты командной строки для сканирования файлов по требованию и автоматического обновления сигнатур. ClamAV поддерживает множество форматов файлов и языков подписей, а также распаковку файлов и архивов. Есть обновление вирусных баз и карантин. В базе находятся, в основном, Windows вирусы. Антивирусные базы ClamAV постоянно обновляются. Программа поддерживает поиск вирусов в архивах (в сжатых файлах). Обычно управление ClamAV осуществляется из командной строки, что удобно для продвинутых пользователей. Новички же могут установить ClamTk — графический интерфейс, упрощающий работу с антивирусом (переведен на русский язык). Этот проект Лицензируется под BSD-3-Clause, GPL-1, GPL-2.0. ${NC}"
echo -e "${CYAN}:: ${NC}Clamtk в Arch Linux — это графический интерфейс для антивируса Clam AntiVirus. ClamTK — это усовершенствованная версия ClamAV, обладающая простым графическим интерфейсом и предназначенная для широкого круга пользователей. Благодаря наличию графического интерфейса, пользоваться этим антивирусом очень легко, у него есть подсистема для сканирования по требованию. В качестве аргумента программа принимает файл или каталог, по которому можно провести сканирование. Проект написан на Perl, Python с использованием библиотеки GTK+. Справку по утилите можно получить, выполнив: man freshclam "
echo " Домашняя страница: https://www.clamav.net/ ; (https://docs.clamav.net/ ; https://gitlab.com/dave_m/clamtk/-/wikis/home ; https://github.com/Cisco-Talos/clamav-documentation/blob/main/src/manual/Installing/Installing-from-source-Unix.md ; https://github.com/Cisco-Talos/clamav-documentation/blob/main/src/manual/Usage/Configuration.md). "
echo -e "${BLUE}:: ${NC}Основные возможности программы: Интерфейс командной строки. Сканирование файлов и почты на лету. Поддержка работы с почтовыми серверами (включая Sendmail). Наличие графических оболочек, реализующих графический интерфейс для управления антивирусом. Периодическое обновление антивирусных баз. Поддержка всех стандартных форматов почтовых файлов. Поддержка большого количества файлов (архивов и контейнеров). Поддерживаются форматы: Zip, RAR, Dmg, Tar, Gzip, Bzip2, OLE2, Cabinet, CHM, BinHex, SIS и другие. Поддержка исполняемых файлов в формате ELF. Поддержка популярных файлов документов: MS Office, HTML, Flash, RTF, PDF и другие. Программный код: Open Source. ClamAV может работать в Linux, Windows (ClamWin), MacOS X и Unit-подобных системах. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
