echo -e "${GREEN}==> Важно! ${BOLD} *ClamAV - С 2022 года проект ограничил подключения из России к своим серверам для обновления антивирусных баз ClamAV. Рассказываем как обновить ClamAV из России. После того, как ClamAV закрыл доступ, при попытке соединения с https://database.clamav.net поступает HTTP-ошибка 403 – доступ запрещён! С российских IP запрещён доступ не только к обновлениям, но ко всему домену clamav.net . 💪 Кто весел — тот смеётся, Кто хочет — тот добьётся, Кто ищет — тот всегда найдет! На днях нашёл аж 3(три) зеркала для обновления антивирусных баз ClamAV в России. ${NC}"
