echo -e "${BLUE}:: ${NC}Тогда как обновить базы ClamAV в этом случае? Вариант 1 - Остановите сервис ClamAV и Скачайте антивирусные базы через Tor или VPN файлы, потом Поместить их в директорию /var/lib/clamav/ и Перезапустить сервис ClamAV (хотя не обязательно). Вариант 2 - Обновление баз ClamAV, российское зеркало TENDENCE . К сожалению, известное российское зеркало ClamAV теперь требует купить подписку на обновления. После оплаты Вы получите ссылки на обновления. Тогда можно будет проделать следующие шаги. Либо скачать последние обновления антивирусных баз можно с российского зеркала (ClamAV mirror) и положить их в /var/lib/clamav/ . Вариант 3 - Рабочее зеркало обновления на UNLIX.ru через bash скрипт. И Добавим задание в cron для еженедельного обновления антивирусных баз ClamAV . "
echo -e "${CYAN}:: ${NC}Мы воспользуемся Вариантом №3. И Ваш ClamAV будет обновляться даже с российских IP совершенно бесплатно. *Убедительная просьба не устанавливать частоту обновления чаще, чем раз в неделю! (если воспользуетесь скриптом: clamav_update_auto) *Примечание: ЭТО Рабочее (проверено) зеркала обновления антивирусных баз, но с задержкой обновления (баз) на 7-9 дней (The virus database is older than 7 days!) 😲 не переживайте, и здесь нашелся вариант для автоматического обновления баз через 'PrivateMirror https://clamav-mirror.ru/' - Подробнее об этом способе обновить базы будет прописано в Справке сценария скрипта, а также в папке ClamAV (мастер ветке MarcMilany/archmy_2020) будет дополнительно находится пару скриптов .sh (update_clamav и clamav_update_auto), скрипты запускаются в терминале (консоли) от имени суперпользователя (пример: sudo sh update_clamav или sudo sh clamav_update_auto). "
echo -e "${GREEN}==> Важно! ${BOLD} *Расскажу какие последовательные действия по установке антивирусных баз выполняю сам. Сначала использую метод обновления, который прописан именно в этом сценарии (скрипта), потом перехожу к действиям прописанным в Справке (но # закомментированы) и обновляю базы с помощью 'PrivateMirror https://clamav-mirror.ru/', прописывая зеркала в конфигурационный файл /etc/clamav/freshclam.conf , затем запускаю обновление баз вручную командой: 'sudo freshclam -vvv', проверяю актуальность антивирусных баз и провожу тестирование (повторюсь действия будут прописаны в Справке). 🎰 ${NC}"
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
