clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Rootkit Hunter (RKHunter)(rkhunter) — Обнаружение руткитов/бэкдоров?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Если вы хотите не просто антивирус, а инструмент для глубокой проверки системы на наличие руткитов и других вредоносных программ, то вам стоит присмотреться к Rootkit Hunter. Rootkit Hunter не является инструментом реагирования: он лишь перечисляет обнаруженные угрозы. Вы сами решаете, читать ли файл журнала и расследовать подозрительную активность. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Rootkit Hunter — это замечательный легкий инструмент с открытым исходным кодом для мониторинга и анализа безопасности систем, совместимых с POSIX, который предназначен для обнаружения и идентификации руткитов, бэкдоров и другого потенциально вредоносного программного обеспечения в системах на базе Linux и Unix. Программа работает из терминала, умеет распознавать руткиты, бэкдоры и другие локальные эксплойты, умеет искать вредоносный код в обычных текстах, а также выполнять проверки системы на предмет наличия характерных признаков вредоносного ПО, подозрительных файлов и различных аномалий конфигурации системы, которые могут указывать на компрометацию. Для работы Rootkit Hunter требуется BASH, он поддерживает обширный набор дистрибутивов Linux. Этот проект Лицензируется под GNU General Public License (GPL). ${NC}"
echo " Домашняя страница: http://rkhunter.sourceforge.net/ ; (https://archlinux.org/packages/extra/any/rkhunter/). "
echo -e "${BLUE}:: ${NC}Особенности Rootkit Hunter: Обнаружение руткитов. Поддержка интерфейса командной строки. Лёгок в использовании и быстро работает. Поддерживает сканирование текстовых файлов. Не требует установки. Этот скрипт умеет находить сотни различных руткитов, а также проверять изменения в системных файлах и сетевых интерфейсах. Установка RKHunter занимает пару минут, а использовать его можно как в ручном режиме, так и в автоматическом. Плюс ко всему, он постоянно обновляется, так что ты будешь защищен от новых угроз. RKHunter был написан максимально универсальным и должен работать на большинстве систем Linux и UNIX. Он поставляется с несколькими вспомогательными скриптами на случай отсутствия определённых команд в системе, некоторые из которых являются скриптами Perl. "
echo -e "${CYAN}:: ${NC}Для запуска этого инструмента сканирования вручную требуются права root, а для создания cron-задания — права root. Поэтому для просмотра журнала, который находится в /var/log/, вам потребуются права root. Файл конфигурации RKH имеет ряд параметров. Наиболее важные из них описаны в вики (https://sourceforge.net/p/rkhunter/wiki/index/). Вы также можете запустить 'man rkhunter' или 'rkhunter --help'. Руткит может иметь пагубные последствия для вашего компьютера/сервера, особенно если система используется в коммерческих целях. Если вы подозреваете наличие руткита в своей системе, крайне важно установить антивирусную программу, чтобы обнаружить и удалить вредоносное ПО. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_rkhunter  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_rkhunter" =~ [^10] ]]
do
    :
done
if [[ $in_rkhunter == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_rkhunter == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Rootkit Hunter (rkhunter) "
