  echo ""
  echo " Установка дополнительных утилит (пакетов) для мониторинга (unhide) "
############ Зависимости ##############
sudo pacman -S --noconfirm --needed bash  # Оболочка GNU Bourne Again ; https://archlinux.org/packages/core/x86_64/bash/ ; https://www.gnu.org/software/bash/bash.html ; Обеспечивает: sh ; 2025-08-02 12:29 UTC
sudo pacman -S --noconfirm --needed bash-completion  # (необязательно) — для автодополнения по клавише Tab ; Программируемое дополнение для оболочки bash ; https://archlinux.org/packages/extra/any/bash-completion/ ; https://github.com/scop/bash-completion ; 2025-01-16 07:53 UTC
sudo pacman -S --noconfirm --needed unhide  # (необязательно) Криминалистический инструмент для поиска процессов, скрытых руткитами, LKM или другими методами ; https://archlinux.org/packages/extra/x86_64/unhide/ ; https://github.com/YJesus/Unhide/ ; 2025-08-06 18:30 UTC
######### rkhunter ##########
sudo pacman -S --noconfirm --needed rkhunter  # Проверяет машины на наличие руткитов и других нежелательных инструментов ; https://archlinux.org/packages/extra/any/rkhunter/ ; http://rkhunter.sourceforge.net/ ; 2025-07-17 13:13 UTC
  echo ""
  echo " Обновим базу данных свойств файла (/etc/rkhunter.conf) "
  echo " Эта команда сообщает сканеру текущее состояние конкретных файлов "
  echo " Это помогает избежать ложных срабатываний при сканировании "
### Команда --update обновляет файлы только для текущей версии, но не для обновления до более новой.
sudo mkdir -p /var/lib/rkhunter
sudo mkdir -p /var/lib/rkhunter/tmp
sudo ls /var/lib/rkhunter
sudo chmod -R 0775 /var/lib/rkhunter/tmp
#sudo rkhunter --update  # Эта опция команды заставляет rkhunter проверять наличие более поздних версий каких-либо из его текстовых файлов данных. Для использования этой опции в системе должен быть установлен веб-браузер командной строки, например wget или lynx. Рекомендуется регулярно запускать эту команду, чтобы гарантировать актуальность файлов данных. Если эта опция используется через cron, то рекомендуется также использовать опцию --nocolors .
### Код выхода, равный нулю, для этой опции команды означает, что обновления отсутствуют. Код выхода, равный единице, означает, что произошла ошибка загрузки, а код выхода, равный двум, означает, что ошибки не произошло, но обновления были доступны и установлены.
  echo ""
  echo " Обновим базу данных свойств файла нужные для rkhunter "
  echo " Эта команда сообщает сканеру текущее состояние конкретных файлов "
  echo " Это помогает избежать ложных срабатываний при сканировании "
  echo " Некоторые могут захотеть вручную скопировать файлы /etc/passwd и /etc/group в /var/lib/rkhunter,
  однако при первом сканировании это будет сделано автоматически. "
### После установки обновите базу данных свойств файла, выполнив следующую команду.
sudo rkhunter --propupd  # Эта команда сообщает сканеру текущее состояние конкретных файлов. Это помогает избежать ложных срабатываний при сканировании.
# --propupd [{filename | directory | package name},...]
# --propupd [{имя файла | каталог | имя пакета},...]
### Одна из проверок, выполняемых rkhunter , — сравнение текущих свойств файла различных команд с ранее сохранёнными. Этот параметр команды заставляет rkhunter обновить файл данных с сохранёнными значениями, указав текущие значения.
# Для автоматического запуска rkhunter --propupd после обновлений программного обеспечения добавьте строку APT_AUTOGEN="yes" в /etc/default/rkhunter (ее считывает /etc/apt/apt.conf.d/90rkhunter ).
# Дождитесь завершения сбора новых значений, а затем выйдите. Это должно устранить все предупреждения, за исключением скрытых файлов, связанных с папкой /dev. Они появляются время от времени и исчезают при следующей перезагрузке системы.
  echo ""
  echo " Посмотреть информацию о версии (rkhunter) "
#sudo rkhunter --version  # Показать версию приложения ; -V, --version ; Эта опция команды заставляет rkhunter отобразить номер своей версии, а затем завершить работу
sudo pacman -Q rkhunter   # Показать версию приложения
sleep 03
  echo ""
  echo " Посмотреть список всех руткитов, которые может найти программа "
sudo rkhunter --list rootkits  # чтобы посмотреть все руткиты, которые может найти программа
sleep 05
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
