# Этот сканер проверяет системные команды, сетевые настройки, настройки локального хоста и файлы на наличие руткитов, вредоносных программ и уязвимостей. Результаты сканирования записываются в файл журнала. Текущие языки: cn de en ja tr tr.utf8 zh zh.utf8
# После обновления свойств файла выполните следующую команду для сканирования на предмет наличия уязвимостей или руткитов:
# Выполнить различные проверки локальной системы
# sudo rkhunter --checkall  # Выполнить различные проверки локальной системы ; При обнаружении чего-либо подозрительного будет выведено предупреждение. Журнал тестов и результатов будет создан автоматически. Рекомендуется регулярно запускать эту команду, чтобы убедиться в отсутствии взлома системы.
# sudo echo | sudo rkhunter --checkall  # работает отлично
# sudo echo | sudo rkhunter --cronjob --update --check
# Я думаю , для повторных проверок можно использовать команду: yes $'\n' | sudo rkhunter --checkall
# Да ладно, echo | sudo rkhunter --checkall  # работает отлично
# Для того чтобы проверить Linux на вирусы всю систему выполните от суперпользователя:
# sudo rkhunter --check
# Программа кроме вывода информации на экран, создаст лог проверки. На информацию выводимую во время проверки не обращайте большого внимания, она немного урезана все станет более понятнее при просмотре лога. Более детальный лог располагается здесь: /var/log/rkhunter.log
# sudo cat /var/log/rkhunter.log
# ФАЙЛЫ (Для установки по умолчанию): /etc/rkhunter.conf ; /var/log/rkhunter.log
# Открываем два файла - /etc/rkhunter.conf и /var/log/rkhunter.log командами:
# sudo nano /etc/rkhunter.conf
# sudo nano /var/log/rkhunter.log
# Для удобства просмотра лога вы можете не смотреть его полностью, а выбрать только предупреждения:
#  sudo cat /var/log/rkhunter.log | grep -A5 "\[ Warning \]"
# Параметр A5 означает показывать еще пять строк после строки с обнаруженным вхождением, так мы точно ничего не пропустим.
### *Добавить задание cron для автоматического сканирования:
# Для каждодневного поиска обновлений и каждодневной проверки системы на безопасность. Или же вы можете внести в свой crontab следующую строку:
# sudo nano crontab -e
# 0   22   *   *   7   /usr/local/bin/rkhunter --update; /usr/local/bin/rkhunter -c --createlogfile --cronjob
# — по которой в 10 часов вечера каждое воскресенье rkhunter обновится, сделает проверку вашей системы, занесет результаты проверки в лог-файл и не будет спрашивать у вас никаких подтверждений на выполнение.
# Также необходимо создать первоначальную базу данных свойств различных системных команд, для того чтобы rkhunter мог сравнивать с ней текущее состояние команд в системе. Делается это так:
# rkhunter --propupd
# У установленного скрипта есть конфигурационный файл, расположенный по пути: /usr/local/etc/rkhunter.conf.
