echo ""
echo -e "${BLUE}:: ${NC}Установить Lynis (Cuando) (lynis) — Сканер уязвимостей?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Мы считаем, что программное обеспечение должно быть простым , регулярно обновляемым и открытым . Вы должны доверять ему, понимать его и иметь возможность вносить изменения. Многие с нами согласны, поскольку тысячи людей ежедневно используют его для защиты своих систем. С помощью этой утилиты Вы в любой момент сможете обнаружить уязвимости в операционной системе и немедленно устранить их. По сути, те же яйца Фаберже с высоты птичье-го полета, но базы у них различные. Возможно, с их помощью удастся выявить то, что пропустил rkhunter. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Lynis — это инструмент аудита и усиления безопасности с открытым исходным кодом для систем  на базе UNIX-подобных систем (Linux, macOS, BSD) и других, а также предоставляет рекомендации по повышению безопасности системы и тестированию на соответствие требованиям. Он выполняет глубокое сканирование безопасности и запускается непосредственно в системе. Его основная цель — протестировать средства защиты и предоставить рекомендации по дальнейшему укреплению системы. Lynis также сканирует общую информацию о системе, выявляет уязвимые программные пакеты и возможные проблемы конфигурации. Кроме того, важно выделить Lynisчто благодаря твоему великому снабор инструментов включен, это предпочтительный инструмент для многих Пентестеры (Системные тестеры на проникновение) и другие специалисты по информационной безопасности по всему миру. Lynis широко использовался системными администраторами и аудиторами для оценки уровня защиты своих систем. Основные цели Lynis включают в себя: Автоматизированный аудит безопасности. Тестирование на соответствие (например, ISO27001, PCI-DSS, HIPAA). Обнаружение уязвимостей. Программное обеспечение (также) помогает: Управление конфигурацией и активами. Управление исправлениями программного обеспечения. Укрепление системы. Тестирование на проникновение (повышение привилегий). Обнаружение вторжений. Этот проект Лицензируется под Только GPL-3.0 . ${NC}"
echo " Домашняя страница: https://cisofy.com/lynis/ ; (https://github.com/CISOfy/lynis ; https://github.com/CISOfy/lynis/releases ; https://archlinux.org/packages/extra/any/lynis/). "
echo -e "${BLUE}:: ${NC}После его выполнения он предлагает информацию по следующим техническим моментам: Значения инициализации инструмента Lynis, используемая операционная система, установленные или нет инструменты и плагины, а также обнаруженные на нем конфигурации загрузки и службы. Процессы ядра, памяти и ОС. Пользователи и группы, а также аутентификация ОС. Оболочка и файловые системы ОС. Аудиторская информация о: USB-накопители и устройства хранения, присутствующие в ОС. NFS, DNS, порты и пакеты ОС. Сетевое подключение, принтеры и буферы, а также программное обеспечение для электронной почты и обмена сообщениями. Брандмауэры и веб-серверы, установленные в ОС. Служба SSH, настроенная в ОС. Поддержка SNMP, базы данных, служба LDAP и система PHP, настроенная в ОС. Поддержка Squid, Логирование и его файлы, незащищенные Сервисы и Баннеры и механизмы идентификации, настроенные в ОС. Запланированные задачи, Учет, Время и синхронизация. Криптография, виртуализация, контейнерные системы, системы безопасности и программное обеспечение, связанное с целостностью файлов и системными инструментами. Программное обеспечение типа вредоносного ПО, права доступа к файлам, домашние каталоги, усиление защиты ядра и общее укрепление, а также пользовательское тестирование. Обобщает найденные результаты, разделен на: *Предупреждения и предложения (срочные проблемы и важные предложения). "
echo -e "${CYAN}:: ${NC}Ознакомьтесь с документацией Lynis (https://cisofy.com/documentation/lynis/), чтобы узнать больше о настройке и использовании Lynis. Если вам интересно узнать больше о безопасности Linux, загляните в блог Linux Audit (https://linux-audit.com/), посвящённый безопасности Linux. Lynis также рекомендует ознакомиться с некоторыми рекомендациями и узнать больше о конкретных результатах. Если вы хотите запустить программу от имени пользователя root(или с помощью sudo), рекомендуем изменить владельца файлов. Используйте chown -R 0:0, чтобы рекурсивно изменить владельца и группу и установить его на ID пользователя 0( root). В противном случае Lynis предупредит вас о правах доступа к файлам. В конце концов, вы запускаете файлы, принадлежащие непривилегированному пользователю. *Важно: процесс выполнения аудита безопасности может занять некоторое время. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
