echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_lynis  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_lynis" =~ [^10] ]]
do
    :
done
if [[ $in_lynis == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_lynis == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Lynis (lynis) "
