### Советы Lynis:
# Если Lynis не установлен как пакет (с включенной страницей руководства), используйте --man или nroff -man ./lynis.8
# Для систем со светлым фоном оболочки используйте --nocolors или --reverse-colors.
# Используйте параметры показа Lynis, чтобы увидеть все доступные параметры Lynis.
# sudo lynis audit system -c -Q
# sudo lynis update info  # Проверка версии утилиты
# lynis --help
# sudo lynis -c
# sudo lynis --version
# lynis -h
# lynis show commands
### Просмотр лог-файла аудита операционной системы:
# Одним из больших плюсов Lynis является то, что он сохраняет результаты проверки ОС в файл журнала (по умолчанию в /var/log/lynis.log). В этом документе хранятся результаты всех тестов, которые инструмент провел в ходе последнего аудита. Вы можете открыть и просмотреть этот файл с помощью любого текстового редактора. Например:
# sudo nano /var/log/lynis.log
# Вы можете проверить, были ли на самом деле созданы все необходимые файлы:
# ls -l /var/log/lynis.log
# ls -l /var/log/lynis-report.dat
### Просмотр лог-файла аудита операционной системы:
# Одним из больших плюсов Lynis является то, что он сохраняет результаты проверки ОС в файл журнала (по умолчанию в /var/log/lynis.log). В этом документе хранятся результаты всех тестов, которые инструмент провел в ходе последнего аудита. Вы можете открыть и просмотреть этот файл с помощью любого текстового редактора. Например:
# sudo nano /var/log/lynis.log
# Примечание: Чтобы увидеть позже предупреждения и предложения, мы можем выполнить следующие команды
# sudo grep -E Warning /var/log/lynis.log
# sudo grep -E Suggestion /var/log/lynis.log
### Файлы (файлы с сгенерированным аудитом):
# – Информация о тестировании и отладке: /home/myuser/lynis.log
# – Данные отчета: /home/myusername/lynis-report.dat
# И, наконец, Lynis предлагает возможность получить дополнительную информацию о каждом сгенерированном предложении с помощью команды показать детали за которым следует номер TEST_ID, как показано ниже:
# lynis show details KRNL-5830
# lynis show details FILE-7524
### *Добавить задание cron для автоматического сканирования:
# Затем в любое пустое поле этого документа впишите задание cron. Допустим, нам нужно проводить аудит безопасности в 00:00 каждую субботу. В таком случае в файл следует добавить строку:
# sudo nano crontab -e
# 0 0 * * Sat root /usr/bin/lynis -c -Q --auditor "automated" --cronjob
# или так, если портативным способом:
### 0 0 * * Sat root /home/user/Downloads/lynis/lynis -c -Q --auditor "automated" --cronjob
# В этой команде:
# - /usr/bin/lynis — место где находиться файл запуска;
# -c — опция, которая указывает альтернативный файл настроек;
# -Q — опция, которая запускает Lynis в фоновом режиме;
# --auditor "automated" — параметр, который устанавливает имя аудитора, как automated;
# --cronjob — опция, которая указывает на то, что аудит выполняется как часть задания cron.
# Команды сообщают программе, что делать. Опция сообщает программе , как это сделать. Если используется аргумент, он указывает, к чему он применяется. Аргументы обычно следуют за опцией, например, за именем файла или целью.
# $ ./lynis audit system --quick --auditor "The Auditor"
# В этом примере мы заставляем Lynis выполнить аудит (команда) с целевой системой (аргумент). Используя --quick (опция), мы сообщаем ему, что ждать не нужно. Мы использовали --auditor (опция) и определили его как «Аудитор» (аргумент).
