clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Firejail (Fire Prison) (firejail) — Песочница безопасности?"
echo -e "${MAGENTA}:: ${BOLD}Firejail (Fire Prison) — это легкий инструмент безопасности с открытым исходным кодом для систем Linux, который обеспечивает дополнительный уровень безопасности, изолируя приложения или процессы от остальной части системы, снижая потенциальное влияние уязвимостей безопасности или вредоносных действий путем создания ограниченной среды для запуска (потенциально ненадежных) приложений. Написанное на языке C и практически не имеющее зависимостей, программное обеспечение работает на любом компьютере Linux с ядром версии 3.x или новее. Оно может изолировать любые процессы: серверы, графические приложения и даже сеансы входа пользователей. В программу включены профили изоляции для ряда распространённых программ Linux, таких как Mozilla Firefox, Chromium, VLC, Transmission и т. д. Песочница лёгкая, накладные расходы минимальны. Не нужно редактировать сложные файлы конфигурации, не нужно открывать сокетные соединения, не нужно запускать демоны в фоновом режиме. Все функции безопасности реализованы непосредственно в ядре Linux и доступны на любом компьютере с Linux. Этот проект Лицензируется Только GPL-2.0 . ${NC}"
echo " Домашняя страница: https://github.com/netblue30/firejail ; (https://firejail.wordpress.com/ ; https://archlinux.org/packages/extra/x86_64/firejail/ ; https://archlinux.org/packages/extra/x86_64/firetools/). "
echo -e "${BLUE}:: ${NC}В частности, это программа-песочница SUID, которая снижает риск нарушений безопасности, ограничивая среду выполнения ненадежных приложений, используя пространства имен Linux, seccomp-bpf и возможности Linux. Она позволяет процессу и всем его потомкам иметь собственное представление о глобально общих ресурсах ядра, таких как сетевой стек, таблица процессов и таблица монтирования. Firejail может работать в среде SELinux или AppArmor и интегрирована с группами управления Linux. Firejail достигает этой изоляции, используя пространства имён Linux и контрольные группы (cgroups) для создания облегчённых песочниц для приложений. Когда приложение выполняется в песочнице Firejail, оно работает в ограниченной среде с ограниченным доступом к системным ресурсам и файлам. Интеграция распространяется на все программы, поддерживаемые Firejail по умолчанию. В текущей версии Firejail более 900 стандартных приложений, и их число растёт с каждым новым релизом. Примеры использования: Изоляция веб-браузера — Firejail позволяет запустить Firefox в изолированной среде, ограничивая доступ к файловой системе и сетевым ресурсам. Изоляция мессенджеров — изоляция Telegram, Signal и других программ помогает предотвратить утечки данных и защитить конфиденциальные сообщения. Обработка конфиденциальных документов — Firejail позволяет изолировать текстовые редакторы и другие программы для работы с чувствительными данными. Важно! Запуск недоверенного кода никогда не будет безопасным, песочница не может это изменить. Если в Firejail нет профиля для конкретного приложения - он использует ограничительный общесистемный профиль по умолчанию. Это может привести к тому, что приложение не будет работать так, как нужно, без предварительного создания пользовательского профиля с ограничениями. Что может эта утилита? Запускать приложения из chroot окружения без необходимости sudo или su (с ограничениями); изолировать сеть; изолировать звук; изолировать графику; изолировать аппаратное ускорение графики; ограничивать доступ к файловой системе по заданным правилам; ограничивать доступ к исполняемым файлам по заданным правилам; создавать приватный самоуничтожающийся домашний каталог для работы приложения; использовать приватный домашний каталог для постоянной в нём работы приложения; запрещать приложению делать системные вызовы на ваш выбор; запрещать приложениям использовать повышение привилегий; принуждать приложения работать в пространстве пользователя; ограничивать процессорное время и доступ к ядрам CPU; запрещать использовать системную шину D-BUS и многое, многое другое. "
echo -e "${CYAN}:: ${NC}Firetools — это графический пользовательский интерфейс безопасной песочницы Firejail. Он предоставляет панель запуска песочницы, интегрированную с системным треем, а также инструменты редактирования, управления и статистики. Приложение создано с использованием библиотеки Qt5. Оно выпущено в рамках проекта Firejail под лицензией GPLv2. Firetools — это проект сообщества. Мы не аффилированы ни с одной компанией и не преследуем коммерческих целей. Мы специализируемся на Linux для настольных компьютеров. Наша целевая аудитория — домашние пользователи и новички в Linux. FDNS — это прокси-сервер DNS через HTTPS (DoH). FDNS защищает ваш компьютер от некоторых наиболее распространённых киберугроз. Мы используем только DoH-сервисы от провайдеров, не ведущих журналирование. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
