    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_firejail  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_firejail" =~ [^10] ]]
do
    :
done
if [[ $in_firejail == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_firejail == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Firejail (Fire Prison) (firejail) "
