sudo pacman -S --noconfirm --needed firetools  # Графический пользовательский интерфейс Firejail ; https://archlinux.org/packages/extra/x86_64/firetools/ ; https://firejail.wordpress.com/ ; 2024-04-04 22:09 UTC
