### Запуск песочницы:
# Чтобы запустить песочницу, добавьте к команде префикс firejail:
# firejail firefox            # starting Mozilla Firefox
# firejail transmission-gtk   # starting Transmission BitTorrent
# firejail vlc                # starting VideoLAN Client
# sudo firejail /etc/init.d/nginx start
# Запустите firejail --list в терминале, чтобы получить список всех активных песочниц. Пример:
# $ sudo firejail --list
# 1617:netblue:/usr/bin/firejail /usr/bin/firefox-esr
# 7719:netblue:/usr/bin/firejail /usr/bin/transmission-qt
# 7779:netblue:/usr/bin/firejail /usr/bin/galculator
# 7874:netblue:/usr/bin/firejail /usr/bin/vlc --started-from-file file:///home/netblue/firejail-whitelist.mp4
# 7916:netblue:firejail --list
### Интеграция с рабочим столом:
# Интегрируйте свою песочницу в рабочий стол, выполнив следующие две команды:
# firecfg --fix-sound
# sudo firecfg
# Первая команда исправляет некоторые ошибки общей памяти/пространства имён PID в PulseAudio до версии 9. Вторая команда интегрирует Firejail в ваш рабочий стол. Чтобы применить изменения PulseAudio, вам потребуется выйти из системы и войти снова. Запускайте программы привычным для вас способом: меню менеджера рабочего стола, файловый менеджер, средства запуска рабочего стола.
