echo -e "${CYAN}=> Предисловие! ${BOLD}Основной целью ArchWiki является предоставление сообществу пользователей Arch Linux наиболее полной и доступной документации в вебе. Это всемирный проект со множеством участников со всех уголков земного шара. Wiki охватывает все принципы Arch Linux, в частности, простоту. ArchWiki постоянно развивается и процветает благодаря сотрудничеству; всегда есть возможности для совершенствования. ArchWiki поддерживается официальной командой поддержки и тысячами участников. Пользователи редактируют и систематизируют статьи, чтобы предоставить читателям наилучшую документацию Arch Linux. Содержание создаётся сообществом и для сообщества: большинство статей написано не одним человеком, а представляет собой совокупный труд многих людей, которые исправляют неверную информацию, обновляют устаревшие статьи и другими способами улучшают содержание ArchWiki. ${NC}"
