echo -e "${MAGENTA}:: ${BOLD}Arch Wiki — Это проект, делает Arch Wiki доступным и портативным. Существующий пакет arch-wiki-docs предоставляет пользователям возможность загрузить копию содержимого ArchWiki себе на компьютер и представляет собой простой набор неорганизованных HTML-файлов, но при этом arch-wiki-lite идёт дальше: чрезвычайно быстрая поисковая система (с поддержкой регулярных выражений и ранжированием), просмотрщик консоли (с подсветкой ссылок и совпадений регулярных выражений), фильтрация по языку (со сводкой языков по количеству страниц), 1/9 размера. arch-wiki-lite создан для того, чтобы предложить максимально удобную работу тем, кто не имеет доступа к Интернету или возможности запустить графический веб-браузер. Лицензия(и): GFDL-1.3 или более поздняя версия, GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://github.com/lahwaacz/arch-wiki-docs ; (https://gitlab.archlinux.org/grawlinson/arch-wiki-lite). "
