#echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Периодическое выполнение пользовательских или системных программ — очевидная необходимость во всех операционных системах. Поэтому потребность в сервисах, позволяющих централизованно планировать и выполнять задачи, программисты осознали очень давно. Установка утилит (пакетов) Мультимедиа, Офисных, Веб-браузеров и других будут предложено в следующих скриптах (по названию позиций например: multimedia_prog.sh). ${NC}"
