#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Установить Fcron (fcron) — Планировщик заданий?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Fcron - взял лучшее из cron и anacron. Он не требует, чтобы ваш компьютер работал 24 × 7, и он может работать с задачами на почасовой или минутной основе. Он задаст вам несколько вопросов во время установки, и вы можете смело ответить “y” (да) на все из них. Чтобы начать создание задания fcron, просто введите fcron -e в терминале. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Fcron — это планировщик. Он ориентирован на то, чтобы заменить собой vixie-cron и anacron, поэтому реализует большинство его функций. Но, в отличие от Vixie Cron, fcron не требует круглосуточной работы системы 7 дней в неделю : он также хорошо работает с системами, которые работают лишь изредка (в отличие от anacrontab). Другими словами, fcron выполняет обе функции: Vixie Cron и anacron, но делает даже больше и лучше. Для этого fcron позволяет использовать стандартный режим, в котором вы указываете ему выполнять одну команду в определённый день и час (например, каждый день в 6 утра) или запускать команду в зависимости от времени работы системы . Например: Запускать задачу «сохранить каталог /home/» каждые 3 ч 15 мин работы системы. Конечно, чтобы сделать его действительно полезным, время, оставшееся до следующего выполнения, сохраняется каждый раз при остановке системы. Вы также можете сказать: выполнить эту команду один раз между 2 и 5 часами утра, что будет выполнено, если система будет запущена в любое время в течение этого интервала. Этот проект Лицензируется под GPL, GPL-2.0 . ${NC}"
echo " Домашняя страница: http://fcron.free.fr/ ; (https://github.com/yo8192/fcron ; https://archlinux.org/packages/extra/x86_64/fcron/). "
echo -e "${BLUE}:: ${NC}Функции: Fcron также включает полезную систему опций, которые можно применять как к каждой строке после объявления, так и к одной строке. Некоторые из поддерживаемых опций позволяют: запускать задания одно за другим (не параллельно), установить максимальное среднее значение нагрузки на систему, при котором должно выполняться задание, установить хорошую цену за работу, запускать задания при запуске fcron, если их нужно было запустить во время простоя системы, пользователю почты, чтобы сообщить ему, что задание не было выполнено и почему, лучшее управление рассылкой результатов, и многое другое! И последнее, но не менее важное: fcron очень хорошо подходит для запуска скриптами : вы можете запустить несколько экземпляров fcron одновременно, завершить работу fcron после того, как он завершит выполнение отложенных заданий, ... "
echo -e "${CYAN}:: ${NC}Он разработан для работы на системах, которые не работают непрерывно и включает в себя дополнительные особенности. Он имеет ограничения на запуск заданий, управление сериализацией работ, возможность назначить работам приятные в обращении значения и возможность запланировать запуск работ при загрузке системы. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
