############# Справка ##############
# ArchWiki https://wiki.archlinux.org/title/Cron
# https://www.linuxboost.com/how-to-set-up-a-cron-job-on-arch-linux/
# Теперь осталось добавить само правило.
# Вбиваем в терминале:
# sudo EDITOR=nano crontab -e   # Редактируем параметр
# И добавляем (прописываем):
# 10 10 * * sun /sbin/rm /var/cache/pacman/pkg/*
# Таким образом наша система будет сама себя чистить раз в неделю, в воскресенье в 10:10 ))
# Или
# 15 10 * * sun /sbin/rm /var/cache/pacman/pkg/*
# Таким образом наша система будет сама себя чистить раз в неделю, в воскресенье в 15:10
# Автоматическая Оптимизация памяти:
# Чтобы автоматизировать процесс и регулярно очищать память, вы можете настроить задание cron для запуска команд через определённые промежутки времени.
# Откройте конфигурацию crontab.
# crontab -e
# Добавьте следующие строки, чтобы ежедневно в полночь очищать кэш, буфер и пространство подкачки:
# 0 0 * * * sudo sync; echo 3 > / proc/sys/vm/drop_caches
# 0 0 * * * sudo echo 1 > / proc/sys/vm/drop_caches
# 0 0 * * * sudo sync; echo 2 > /proc/sys/vm/drop_caches
# 0 0 * * * sudo swapoff -a && sudo swapon -a
# Примечание: sudo может не работать в crontab, если не используется crontab пользователя root или для этих команд не настроено sudo без пароля. Рассмотрите возможность размещения команд в скрипте и планирования его выполнения.
# Опции cronie
# Использование:
# crontab [опции] файл
# crontab [опции]
# crontab -n [имя хоста]
# Опции:
# -u <пользователь>  определить пользователя
# -e         отредактировать пользовательский crontab
# -l         показать список пользовательского crontab
# -r         удалить пользовательский crontab
# -i         запрос перед удалением
# -n <хост>  установить хост в кластере для запуска пользовательских crontab
# -c         получить хост в кластере для запуска пользовательских crontab
# -x <mask>  включить отладку
# Т.е. для редактирования списка задач текущего пользователя:
# crontab -e
# Для отображения списка задач текущего пользователя:
# crontab -l
# Изменение текстового редактора по умолчанию для crontab на vim
# Команда crontab -e проверит переменные окружения $EDITOR и $VISUAL, поэтому для перезаписи текстового редактора по умолчанию:
# export VISUAL=vim
# или
# export EDITOR=vim
# Для того, чтобы изменения стали постоянными, добавьте в ваш ~/.bashrc:
# export EDITOR=vim
# Правила составления файла cron
# Файл cron может содержать переменные окружения и строки, определяющие время запуска и команду, необходимую запустить.
# crontab -r # удалить таблицу задач
# crontab path/to/file.crontab # загрузить таблицу задач из файла
#####################################

clear
echo ""
echo -e "${BLUE}:: ${NC}Установить KCron (kcron) — Планировщик заданий KDE?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Это приложение все еще находится в стадии разработки и еще не выпущено сообществом KDE. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}KCron (ранее — «Планировщик заданий KDE») — это графический интерфейс (GUI) для управления системным планировщиком cron в Linux. Ранее KCron был самостоятельным приложением, но теперь является частью стандартных инструментов (kdeadmin), поставляемых с средой рабочего стола KDE. При запуске этого модуля вы увидите сводную информацию о существующих запланированных задачах и связанных с ними переменных среды. Если вы работаете как пользователь root, вы увидите эти данные для всех пользователей компьютера, а также системные запланированные задачи. KCron написан на языке C++. Это бесплатное программное обеспечение с открытым исходным кодом. С его помощью команды (или «задачи») можно запускать в определённое время, в определённый день или дату, или через определённые интервалы (время между выполнениями). kde-config-cron — это модуль конфигурации KDE для планирования запуска программ с определёнными интервалами с помощью cron, службы планирования UNIX. Этот пакет является частью модуля администрирования KDE. Этот проект Лицензируется под GNU General Public License version 2.0 (GPLv2). ${NC}"
echo " Домашняя страница: https://www.kde.org ; (https://apps.kde.org/kcron/ ; https://docs.kde.org/stable/ru/kdeadmin/kcron/index.html ; https://invent.kde.org/system/kcron ; https://github.com/fermitools/kcron/blob/main/README.md ; https://archlinux.org/packages/extra/x86_64/kcron/). "
echo -e "${BLUE}:: ${NC}Функции: Планировать запуск приложений и скриптов в заданное время или через определённые промежутки времени. Можно указать дату и время, периодически или однократно выполнять задание. Задавать уведомительное задание (например, каждые полчаса показывать всплывающее уведомление). Запланировать завершение работы приложения или компьютера в заданное время. Настроить переменные окружения для задач (например, указать путь к выполняемому файлу программы). "
echo -e "${CYAN}:: ${NC}Установка: В некоторых дистрибутивах KCron выделяют в отдельный пакет. В KDE 4.4 KCron — модуль, который находится в «Настройки системы» → «Продвинутые» → «Система» → «Планировщик задач». В KDE 4.5 и более поздних версиях KCron находится в «Настройки системы» → «Раздел Системное администрирование» → «Планировщик задач». Отзывы: Пользователи отмечают удобство KCron — графический интерфейс позволяет редактировать конфигурационные файлы cron, что удобно для автоматизации процессов. Однако есть и проблемы — например, некоторые пользователи жалуются на то, что KCron не выполняет задания по расписанию. В этом случае может быть связано с невозможностью инициировать графический режим из-за того, что пути не прописаны. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - Да установить,     0 - НЕТ - Пропустить установку: " in_kcron  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_kcron" =~ [^10] ]]
do
    :
done
if [[ $in_kcron == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_kcron == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) KCron (kcron) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) "
