clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Jobber (jobber-bin) — Планировщик заданий?"
echo -e "${YELLOW}==> Предупреждение! ${BOLD} *Повышение привилегий возможно, если ОС, в которой работает Jobber, позволяет пользователям без прав root менять владельца файла на другого пользователя. К счастью, в Linux это невозможно и не распространено в других версиях Unix. Обратите внимание, что Jobber не был тщательно и профессионально проверен на предмет безопасности. (Конечно, как и большая часть программного обеспечения...) Выполнение его требований безопасности действительно является целью, но, как ясно указано в лицензии , авторы не гарантируют, что в Jobber нет уязвимостей. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Jobber (или "jobber" в оригинале) — это планировщик заданий в Linux, который позволяет автоматизировать выполнение задач по расписанию, написан на языке GO. Чтобы установить Jobber, вы должны удостовериться в том, что в вашей системе установлен язык GO. Он является альтернативой более известному планировщику cron, но, в отличие от cron, Jobber может быть настроен для работы с более сложными сценариями и имеет более гибкий синтаксис.  Он имеет историю выполнения заданий со статусом, контролируя, выполняется ли задание снова после сбоя, и получать уведомления о каждом неудачном запуске или только о заданиях, которые были отключены из-за повторных сбоев. Этот проект Лицензируется под MIT. ${NC}"
echo " Домашняя страница: https://dshearer.github.io/jobber/ ; (https://dshearer.github.io/jobber/doc/v1.4/ ; https://aur.archlinux.org/packages/jobber-bin ; https://aur.archlinux.org/jobber-bin.git). "
echo -e "${BLUE}:: ${NC}Помимо функциональности cron, Jobber также обеспечивает: История выполнения заданий : вы можете увидеть, какие задания были недавно запущены, а также были ли они выполнены успешно или нет. Сложная обработка ошибок : вы можете контролировать, будет ли и когда повторно запущено задание после сбоя. Например, после первоначального сбоя задания Jobber может планировать будущие запуски, используя алгоритм экспоненциального отсрочки. Расширенные отчеты об ошибках : вы можете контролировать, будет ли Jobber уведомлять вас о каждом неудачном запуске или только о заданиях, которые были отключены из-за повторяющихся сбоев. "
echo -e "${CYAN}:: ${NC}Основные особенности Jobber: Jobber позволяет определять расписание выполнения задач с использованием более сложного синтаксиса, чем cron, что делает его подходящим для более сложных сценариев автоматизации. Jobber является более современным планировщиком, чем cron, и может быть предпочтительным выбором для новых проектов.  Jobber может использоваться в качестве альтернативы cron для выполнения периодических задач, особенно если требуется более гибкий подход к расписанию. В отличие от cron, Jobber может запускать задачи не только по расписанию, но и при наступлении определенных событий. Cron использует более простой синтаксис для задания расписания, в то время как Jobber предоставляет более гибкий и мощный синтаксис. Cron запускает задачи строго по расписанию, в то время как Jobber может запускать задачи по наступлению определенных событий. Jobber имеет более современный интерфейс управления задачами, чем cron. "
echo -e "${CYAN}:: ${NC}Установка Jobber (jobber-bin) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/jobber-bin.git), (https://aur.archlinux.org/packages/jobber-bin) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
