# Примеры использования
# Для создания заданий Jobber создаёт файл с именем .jobber в домашнем каталоге пользователя. Задания определяются в формате, аналогичном синтаксису командной оболочки (например, bash).
# Некоторые команды для работы с заданиями:
# jobber reload — перезагрузка нового списка заданий.
# jobber list — список заданий для конкретного пользователя, показывает статус каждого задания (запланировано как обычно, применяется алгоритм экспоненциальной отсрочки или задание неудачное).
# jobber log — список последних запусков любых заданий для конкретного пользователя.
# После обновления списка заданий используйте jobber reload, чтобы заставить Jobber перезагрузить новый список.
# В любое время вы можете использовать jobber log, чтобы увидеть список последних запусков любых заданий.
################################

