echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *У каждого есть свои секреты. Это может быть дневник, который вы хотите спрятать от братьев и сестёр, или государственная тайна, которая может быть раскрыта, если вы забудете ноутбук в общественном транспорте. Шифрование файлов и электронных писем необходимо, если вы не хотите, чтобы ваши секреты и личная информация стали достоянием посторонних. Файлы, которые вы хотите зашифровать, могут быть не такими уж и важными. Большинство людей хранят на своих компьютерах отсканированные копии важных документов: водительских удостоверений, свидетельств о рождении, паспортов и страховых полисов. Эти документы могут понадобиться вам в спешке, но они также привлекают внимание преступников и могут стать причиной кражи личных данных. Вы также можете использовать свой компьютер для создания счетов для клиентов или хранения других конфиденциальных данных, требующих юридической защиты от атак. Вам также может потребоваться безопасно отправлять и получать файлы по электронной почте или публиковать их в зашифрованном виде в открытом доступе в Интернете. В таких случаях вам понадобится решение для шифрования, которое будет быстрым, простым в использовании и которое будет трудно взломать. ${NC}"
sleep 15
clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Seahorse (seahorse) — Управления вашими паролями и ключами шифрования?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Seahorse — это графический интерфейс интерфейс для GnuPG (программы GNU Privacy Guard), который использует PGP для шифрования данных. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Seahorse — приложение для управления ключами шифрования и паролями в Linux, разработанное для рабочего окружения GNOME. Однако оно доступно в большинстве дистрибутивов Linux. Это инструмент для безопасной передачи данных и хранения данных. Шифрование данных и создание цифровых подписей легко выполняются через графический интерфейс, а операции управления ключами — через интуитивно понятный интерфейс. Программа основана на GnuPG и распространяется как свободное программное обеспечение под лицензией GNU GPL. Особенности: Создание и управление PGP/SSH ключами. Публикация, а также получение ключей с соответствующих серверов. Кеширование ключевых фраз. Резервное копирование ключей. Шифрование и дешифрование файлов и текста. В настоящее время он поддерживает ключи PGP (используя GPG/GPGME) и ключи SSH. Его цель — предоставить простой в использовании инструмент управления ключами, а также простой в использовании интерфейс
для операций шифрования. Кроме того, Seahorse включает плагин Gedit, может обрабатывать файлы с помощью Nautilus, апплет для управления данными, помещенными в буфер обмена, и агент для хранения приватных парольных фраз, а также менеджер ключей GnuPG и OpenSSH. Поддерживает интеграцию в Caja, Nautilus, gedit и Evolution для шифрования/расшифровки и некоторых других криптографических операций. Также имеется поддержка к серверам ключей HKP и LDAP. Этот проект Лицензируется под GPL-2.0 или более поздняя версия И LGPL-2.1 или более поздняя версия И CC-BY-SA-3.0 . ${NC}"
echo " Домашняя страница: https://wiki.gnome.org/Apps/Seahorse ; (https://github.com/notional-labs/seahorse ; https://archlinux.org/packages/extra/x86_64/seahorse/ ; https://help.ubuntu.ru/wiki/%D1%88%D0%B8%D1%84%D1%80%D0%BE%D0%B2%D0%B0%D0%BD%D0%B8%D0%B5_%D1%81_seahorse). "
echo -e "${BLUE}:: ${NC}Основные функции: Шифровать/расшифровывать/подписывать файлы и текст. Управляйте своими ключами и связкой ключей. Синхронизируйте свои ключи и связку ключей с серверами ключей. Подпишите ключи и опубликуйте. Сохраните свою парольную фразу в кэше, чтобы вам не пришлось вводить ее каждый раз. Сделайте резервную копию ключей и брелока. Добавьте изображение в любом поддерживаемом GDK формате в качестве идентификатора фотографии OpenGPG. Создайте SSH-ключи, настройте их, кэшируйте. Поддержка интернационализации – есть переводы на чешский, французский, немецкий, греческий, венгерский, польский, португальский (бразильский), русский, испанский и шведский языки. "
echo -e "${CYAN}:: ${NC}Как работает PGP? PGP (Pretty Good Privacy) — один из самых распространённых типов шифрования. Он работает путём генерации набора из двух ключей. Любой, у кого есть доступ к опубликованному открытому ключу и подходящей программе шифрования, может зашифровать сообщения, но расшифровать их может только тот, у кого есть закрытый ключ. GnuPG — полная и свободная реализация стандарта OpenPGP, определённого в RFC4880 (также известного как PGP). GnuPG позволяет вам шифровать и подписывать данные и сообщения. Он оснащён универсальной системой управления ключами, а также модулями доступа для всех типов открытых ключей. GnuPG, также известный как GPG, это инструмент командной строки с возможностью лёгкой интеграции с другими приложениями. Доступен богатый выбор пользовательских приложений и библиотек. GnuPG также поддерживает S/MIME и Secure Shell (ssh). "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
