sudo pacman -S --noconfirm --needed libsecret-docs  # Библиотека для хранения и восстановления паролей и других секретов (документация) ; https://archlinux.org/packages/core/x86_64/libsecret-docs/ ; https://gnome.pages.gitlab.gnome.org/libsecret/ ; 2025-03-22 14:54 UTC
