clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Kleopatra (kleopatra) — Менеджер сертификатов и графический интерфейс для GnuPG?"
echo -e "${YELLOW}==> Предисловие! ${BOLD} *С появлением библиотеки GCrypt-1.7.0 с поддержкой российской криптографии (ГОСТ 28147-89, ГОСТ Р 34.11-94/2012 и ГОСТ Р 34.10-2001/2012), стало возможным говорить о поддержке российского PKI в таких проектах как Kleopatra и KMail. Шифрование GPG превосходно, однако оно привязано к командной строке. Если вы хотите использовать GPG для шифрования файлов, Kleopatra — более простой способ. GPG / GnuPG (GNU Privacy Guard) - консольная утилита для шифрования информации и создания электронных цифровых подписей с помощью различных алгоритмов (RSA, DSA, AES и др...). Утилита создана как свободная альтернатива проприетарному PGP (Pretty Good Privacy) и полностью совместима с стандартом IETF OpenPGP (может взаимодействовать с PGP и другими OpenPGP-совместимыми системами). ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Kleopatra — это многофункциональное C++ / QT / KDE (kcmutils / kmime) графическое приложение позволяющее подписывать и шифровать файлы, а также обеспечивает создание, хранение и управление сертификатами и ключами шифрования.
Kleopatra разрабатывается как часть рабочего окружения KDE (KDE Applications / KDE Utilities), поддерживает управление сертификатами X.509 и OpenPGP в ключах шифрования GnuPG (GPG), основные возможности приложения реализованы на криптографической библиотеке libkleo (KDE PIM cryptographic library), использующей функционал GnuPG Made Easy (GPGME). Kleopatra не имеет синтаксиса, это графическое приложение с открытым исходным кодом, которое работает с криптографическими службами семейства GPG (GNU Privacy Guard). Программа предназначена в основном для работы с сертификатами OpenPGP и S/MIME (X.509). Этот проект Лицензируется под GPL-2.0 или более поздняя версия, LGPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://apps.kde.org/kleopatra/ ; (https://github.com/OpenPGP/openpgp.org/blob/master/_software/01-10-kleopatra.md ; https://archlinux.org/packages/extra/x86_64/kleopatra/). "
echo -e "${BLUE}:: ${NC}Функции: Создавать пару ключей (открытый и закрытый). Можно указать имя и адрес электронной почты, выбрать алгоритм шифрования (RSA, DSA, ECDSA/EdDSA) и другие параметры. Шифровать файлы или папки. Можно выбрать открытый ключ получателя или ввести его адрес электронной почты. Расшифровывать файлы. Нужно выбрать зашифрованные файлы, предоставить закрытый ключ, связанный с зашифрованными данными, и, если во время шифрования был установлен пароль, ввести его. Чтобы зашифровать данные с помощью Kleopatra, нужно: Открыть Kleopatra и перейти в раздел «Шифрование файлов». Выбрать файлы или папки, которые нужно зашифровать. Выбрать открытый ключ получателя или ввести его адрес электронной почты, чтобы зашифровать данные для него. (По желанию) настроить дополнительные параметры шифрования, например формат файла, сжатие и пароль. Начать процесс шифрования и сохранить зашифрованные файлы в надёжном месте. "
echo -e "${CYAN}:: ${NC}Интерфейс Kleopatra включает доступ к управлению ключами, сертификатами, шифрованию и расшифровке файлов. Для управления большинством функций используется мышь, частично можно использовать клавиатурные сочетания (настраивается). Некоторые настройки программы Kleopatra: Создание сертификата отзыва — его можно использовать, чтобы сделать пару ключей недействительной в случае потери или компрометации. Импорт существующих файлов сертификатов или ключей (при необходимости). Настройка параметров Kleopatra по предпочтениям, включая алгоритмы шифрования, место хранения ключей и интеграцию с клиентами электронной почты. Этот пакет содержит отладочные символы, связанные с kdepim. Они будут автоматически использоваться gdb для отладки проблем, связанных с kdepim. "
echo -e "${YELLOW}:: Примечание! ${NC}Для полноценной работы Kleopatra необходимо наличие хотя бы одной пары ключей, при первом запуске приложением автоматически сканируются каталоги в которых "по умолчанию" находятся ключи GPG (~/.gnupg и пр). Поддерживается импорт сертификатов из файлов множества наиболее распространённых форматов (*.acs, *.cer, *.crt, *.pem, *.pfx и др). "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_kleopatra  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_kleopatra" =~ [^10] ]]
do
    :
done
if [[ $in_kleopatra == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_kleopatra == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Kleopatra (kleopatra) "
