sudo pacman -S --noconfirm --needed qgpgme  # Привязки Qt для GPGME ; https://archlinux.org/packages/extra/x86_64/qgpgme/ ; https://gnupg.org/software/gpgme/index.html ; Обеспечивает: qgpgme-qt6 ; Заменяет: qgpgme-qt6 ; Конфликты: с qgpgme-qt6 ; 2025-07-13 06:55 UTC
