clear
echo ""
echo -e "${BLUE}:: ${NC}Установить GPG-Crypter (gpg-crypter) — Менеджер сертификатов и графический интерфейс для GnuPG?"
echo -e "${MAGENTA}:: ${BOLD}GPG-Crypter — небольшой C (си) / GTK графический интерфейс (GUI) дающий доступ к некоторым возможностям консольной утилиты GPG (GnuPG). GPG / GnuPG (GNU Privacy Guard) — консольная утилита для шифрования информации и создания электронных цифровых подписей с помощью различных алгоритмов (RSA, DSA, AES и др...). Утилита создана как свободная альтернатива проприетарному PGP (Pretty Good Privacy) и полностью совместима с стандартом IETF OpenPGP (может взаимодействовать с PGP и другими OpenPGP-совместимыми системами). GPG может использоваться для симметричного и ассиметричного шифрования информации. При ассиметричном шифровании используются два ключа, публичный и приватный. Публичный ключ используется для шифрования, а приватный для расшифровки, благодаря такой схеме расшифровать сообщение может только владелец приватного ключа. GPG-Crypter разработан для обеспечения простого доступа к некоторым возможностям консольной утилиты GPG (libgpgme) из простого и удобного пользовательского интерфейса. При использовании GnuPG как средства защиты можно не беспокоиться о том данные станут доступны посторонним, так как подход к шифрованию позволяет решать любые задачи связанные с передачей особо важных данных. Этот проект Лицензируется под GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://gpg-crypter.sourceforge.net/ ; (https://aur.archlinux.org/gpg-crypter.git ; https://zenway.ru/page/gpg-crypter). "
echo -e "${BLUE}:: ${NC}Основным назначением GPG-Crypter является шифрование и расшифровка текста, для этого используются поля первой вкладки основного окна. Текст можно добавлять и копировать в буфер обмена, или использовать текстовые файлы. После зашифровки текст (в окне или текстовом файле) будет выглядеть как бессмысленный набор символов или ASCII строк. В второй вкладке GPG-Crypter осуществляется шифрование и расшифровка файлов (без сжатия). Вне зависимости от типа файла и его размера после шифрования для хранения или пересылки пользователь получает бинарный или текстовой ASCII файл (*.gpg), который после расшифровки приходит в своё оригинальное состояние. "
echo -e "${CYAN}:: ${NC}При шифровании текста или файлов GPG-Crypter не требует ввести пароль, пароль для используемого ключа необходимо ввести только при расшифровке. Управление приложением ориентировано на использование мыши. "
echo -e "${CYAN}:: ${NC}Установка GPG-Crypter (gpg-crypter) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/gpg-crypter.git, (https://aur.archlinux.org/packages/gpg-crypter) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - Да установить,     0 - НЕТ - Пропустить установку: " in_gpgcrypter  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_gpgcrypter" =~ [^10] ]]
do
    :
done
if [[ $in_gpgcrypter == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_gpgcrypter == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) GPG-Crypter (gpg-crypter) "
