sudo pacman -S --noconfirm --needed gpgme  # Библиотека-оболочка C для GnuPG ; https://archlinux.org/packages/core/x86_64/gpgme/ ; https://www.gnupg.org/related_software/gpgme/ ; Обеспечивает:  libgpgme.so=45-64 ; 2025-06-06 14:06 UTC
############ gpg-crypter ##########
yay -S gpg-crypter --noconfirm  # Графический интерфейс для GnuPG (GPG) с использованием инструментария GTK3 и libgpgme ; https://aur.archlinux.org/packages/gpg-crypter ; https://aur.archlinux.org/gpg-crypter.git (только для чтения, нажмите, чтобы скопировать) ; https://gpg-crypter.sourceforge.net/ ; https://downloads.sourceforge.net/sourceforge/gpg-crypter/gpg-crypter-0.4.1.tar.gz ; 2024-09-21 20:16 (UTC)
############ gpg-crypter ##########
