  <<< Установка утилит (пакетов) для поддержки протоколов беспроводной связи Bluetooth в Archlinux ᛒᚼᛒ>ᛒ🎧📱📻💻🎮🔊🎵🎶 >>> ${NC}"
# Installing utilities (packages) to support Bluetooth wireless communication protocols in Archlinux
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Чтобы упростить взаимодействие множества электронных устройств, создана синяя технология Bluetooth. Bluetooth — один из самых популярных стандартов передачи данных между устройствами. С его помощью можно слушать музыку в беспроводных наушниках, управлять роботом-пылесосом или включить чайник на кухне из другой комнаты. ${NC}"
sleep 07
clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Bluetooth (bluez) — Утилит поддержки протоколов Bluetooth?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Некоторые Bluetooth-адаптеры поставляются с Wi-Fi-картой (например, старые карты Intel Centrino). Для этого необходимо сначала включить Wi-Fi-карту (обычно сочетанием клавиш на ноутбуке), чтобы Bluetooth-адаптер стал видимым для ядра. Некоторые карты Bluetooth (например, Broadcom) конфликтуют с сетевым адаптером. Поэтому необходимо убедиться, что ваше устройство Bluetooth подключено до загрузки сетевой службы. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Bluetooth — это стандарт беспроводной связи малого радиуса действия для сотовых телефонов, компьютеров и других электронных устройств, обеспечивающий обмен данными между устройствами на основе ультракоротких радиоволн. От других стандартов беспроводной связи он отличается используемыми частотами, правилами передачи и способом шифрования данных. В Linux канонической реализацией стека протоколов Bluetooth является BlueZ . Как и Wi-Fi, Bluetooth работает на частотах, близких к 2,4 ГГц. Но у стандарта есть свои особенности: частота передачи данных постоянно меняется, а устройства объединяются в пикосети. Остановимся на этом подробнее. При передаче данных по Bluetooth используется метод расширения спектра со скачкообразной перестройкой частоты (FHSS, frequency hopping spread spectrum). Название сложное, но на деле технология работает просто. Диапазон передачи разбивается на 79 частот. Устройство 1600 раз в секунду псевдослучайным образом выбирает одну из них и передаёт пакеты данных. Передающее и принимающее устройства знают, как будут меняться частоты, поэтому поддерживают соединение друг с другом. При этом другие гаджеты воспринимают сигнал как электромагнитный шум, так как не могут отслеживать изменение частот. Устройства, передающие данные одинаковым образом, то есть «понимающие» друг друга, объединяются в пикосеть. В таких сетях есть два вида устройств: главное, или ведущее, и периферийные, они же ведомые. Этот проект Лицензируется Только GPL-2.0 . ${NC}"
echo " Домашняя страница: http://www.bluez.org/ ; (https://wiki.archlinux.org/title/Bluetooth ; https://github.com/MarcoRab01/BluetoothArchLinux ; https://archlinux.org/packages/extra/x86_64/bluez/). "
echo -e "${BLUE}:: ${NC}Протокол Bluetooth поддерживает режим работы standby. Он позволяет сопряжённым устройствам запоминать друг друга и автоматически подключаться заново после выключения или перезагрузки. Если у вас есть беспроводные наушники, то вы наверняка замечали, что они быстро находят смартфон после извлечения из зарядного кейса. Безопасность в Bluetooth-системах реализована с помощью механизмов шифрования и аутентификации, что обеспечивает защиту передаваемой информации от несанкционированного доступа. Эта надежная схема гарантирует, что ваши подключенные устройства работают в безопасной среде. "
echo -e "${CYAN}:: ${NC}Преимущества Bluetooth: Одним из главных достоинств Bluetooth является его повсеместная доступность. Большинство современных устройств поддерживают эту технологию, что делает ее универсальным решением для коммутации. Упрощенное подключение позволяет пользователям быстро настраивать соединения для передачи файлов, подключения аудиоустройств или использования беспроводной периферии. Низкое энергопотребление помогает экономить заряд батареи, особенно при длительном использовании. Еще одно преимущество – невысокая стоимость реализации. Встроенные модули BT в большинстве современных гаджетов и их повсеместное распространение делает эту разработку экономически выгодным решением для производителей, что, в конечном итоге, сказывается и на цене устройств для пользователей. *Недостатки Bluetooth: Несмотря на многочисленные плюсы, у технологии есть и слабые стороны. Прежде всего, ограниченная дальность действия. Обычно радиус действия ограничен несколькими десятками метров и может сокращаться из-за препятствий или других помех в окружающей среде. Помимо этого, скорость передачи данных ограничена, что делает его менее подходящим для передачи больших объемов информации по сравнению с другими методами передачи данных, такими как Wi-Fi. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
