    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_bluetooth  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_bluetooth" =~ [^10] ]]
do
    :
done
if [[ $in_bluetooth == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
