############ Зависимости ##############
sudo pacman -S --noconfirm --needed alsa-lib  # Альтернативная реализация поддержки звука в Linux ; https://archlinux.org/packages/extra/x86_64/alsa-lib/ ; https://www.alsa-project.org/ ; 2025-04-14 20:27 UTC
############# bluez ############
sudo pacman -S --noconfirm --needed bluez bluez-libs bluez-cups bluez-utils  # Демоны для стека протоколов Bluetooth; Устаревшие библиотеки для стека протоколов Bluetooth; Серверная часть CUPS для принтеров Bluetooth; Утилиты разработки и отладки для стека протоколов bluetooth.
#sudo pacman -S --noconfirm --needed bluez  # Демоны для стека протоколов Bluetooth ; https://archlinux.org/packages/extra/x86_64/bluez/ ; http://www.bluez.org/ ; 2025-06-02 18:45 UTC
#sudo pacman -S --noconfirm --needed bluez-libs  # Устаревшие библиотеки для стека протоколов Bluetooth ; https://archlinux.org/packages/extra/x86_64/bluez-libs/ ; http://www.bluez.org/ ; 2025-06-02 18:45 UTC
#sudo pacman -S --noconfirm --needed bluez-cups  # Бэкэнд принтера CUPS для принтеров Bluetooth ; https://archlinux.org/packages/extra/x86_64/bluez-cups/ ; http://www.bluez.org/ ; 2025-06-02 18:45 UTC
#sudo pacman -S --noconfirm --needed bluez-utils  # содержащий утилиту bluetoothctl ; Утилиты разработки и отладки для стека протоколов Bluetooth ; https://archlinux.org/packages/extra/x86_64/bluez-utils/ ; http://www.bluez.org/ ; Обеспечивает: bluez-plugins ; Заменяет: bluez-plugins ; 2025-06-02 18:45 UTC
  echo ""
