sudo pacman -S --noconfirm --needed bluez-deprecated-tools  # Устаревшие инструменты, которые больше не поддерживаются ; https://archlinux.org/packages/extra/x86_64/bluez-deprecated-tools/ ; http://www.bluez.org/ ; 2025-06-02 18:45 UTC ; чтобы использовать устаревшие инструменты BlueZ (https://wiki.archlinux.org/title/Bluetooth#Deprecated_BlueZ_tools).
