########### Blueberry Инструмент конфигурации Bluetooth ##############
### Blueberry — Инструмент конфигурации Bluetooth для операционных систем на базе Linux.
### Некоторые особенности программы: Работает с любыми средами рабочего стола, включая MATE, Cinnamon, GNOME, XFCE и Unity. Отображает значок на панели и не мешает пользователю, если в системе нет адаптера Bluetooth. Поддерживает интеграцию с различными дистрибутивами, при условии установки gnome-bluetooth. Имеет лицензию открытого источника (GPL-3.0) и является бесплатным продуктом. Написано на языке Python. Официальный сайт: github.com/linuxmint/blueberry.
