sudo rfkill list  # Убедитесь, что Bluetooth не блокируется
sleep 03
### Если вы видите, что Bluetooth заблокирован, разблокируйте его с помощью:
# sudo rfkill unblock bluetooth
### После этого обязательно включаю адаптер вот таким запросом:
# sudo hciconfig hci0 up
### И как только данная процедура будет завершена, можно приступать к сканированию. Перед этим проверю, включен ли Bluetooth модуль на другом устройстве и не находится ли он в скрытом режиме.
# sudo hcitool scan
### После завершения сканирования отобразится имя устройства и его MAC адрес. А чтобы узнать более подробную информацию о нем, использую утилиту sdptool:
# sdptool browse [тутдолженбытьMACадрес]
### А вот с помощью утилиты ping можно проверить доступность удаленного устройства. Выглядеть команда при этом будет примерно вот так:
# sudo l2ping [тутдолженбытьMACадрес]
### Если действовать через настройки, тут все будет намного проще. Нужно просто запустить поиск, и в результате отобразится список доступных устройств.
  echo ""
  echo " Посмотрите информацию о версии (bluez) "
sudo pacman -Q bluez  #  Показать версию приложения ; Альтернативный метод — проверить версию установленного пакета NTP через менеджер пакетов системы.
# sudo pacman -Qs имя_пакета  # Используйте команду pacman с -Qs опцией поиска только среди установленных пакетов в системе. Она ищет указанный текст только в названиях и описаниях установленных пакетов.
# sudo pacman -Qi имя_пакета  # Эта -Qi опция отображает подробную информацию об указанном пакете. Она также показывает метаданные пакета, такие как зависимости, конфликты, дата установки, дата сборки, размер и т. д.
# sudo pacman -Si имя_пакета  # Эта -Si опция позволяет просматривать подробную информацию о любых пакетах Arch Linux. Необходимо указать точное название пакета.
sleep 03
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
fi
