clear
echo -e "${MAGENTA}
  <<< Установка утилит (пакетов) Поддержки работы воспроизведения звука - Клиенты ALSA или PipeWire для Archlinux 🔊 >>> ${NC}"
# Installing utilities (packages) Audio playback support - ALSA or PipeWire clients for Archlinux
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Если вы следите за всеми тенденциями в Linux-сообществе, вы наверняка сталкивались с дебатами о том, что лучше: PipeWire или PulseAudio? Некоторые пользователи предпочитают вернуться к PulseAudio, в то время как другие находят решение своих десятилетних проблем с аудио в PipeWire. Конечно, PipeWire – относительно новая технология, у нее должна быть цель, и именно поэтому она заменяет PulseAudio во многих дистрибутивах Linux. Но это не значит, что PulseAudio плох. Он очень хорошо выполняет возложенные на него задачи, но, безусловно, имеет свои плюсы и минусы. Итак, в этом сценарии (скрипта) было принято решение: установку утилит (пакетов) клиентов 'ALSA' (Advanced Linux Sound Architecture) и 'PipeWire' (Pinos) прописать последовательно друг за другом, так,что если вы захотите установить PipeWire вместо ALSA (просто пропустите установку ALSA и перейдите к установке PipeWire). Но вам всё равно придется потрудиться ручками и прописать некоторые настройки (параметры) самим об этом подробно будет написано в Справке (но она закомментирована #), под каждым из установленных (емых) клиентов. *Остальные настройки уже будут прописаны в сценарии (скрипта)! 👉👈 ${NC}"
sleep 15
clear
echo ""
echo -e "${BLUE}:: ${NC}Установить ALSA (Advanced Linux Sound Architecture) — Расширенная звуковая архитектура?"
echo -e "${YELLOW}==> Предисловие! ${BOLD} *Если у вас нет потребности в микшировании каналов, записи аудио через микрофон и вы не слушаете музыку через Bluetooth, то ALSA может вам подойти. Мощь ALSA заключается в её чётко определённой архитектуре, состоящей из нескольких ключевых компонентов, которые совместно управляют звуковыми устройствами и обработкой звука. Понимание этих компонентов крайне важно для понимания принципов работы ALSA. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}ALSA (Advanced Linux Sound Architecture) — предоставляет драйверы звуковой карты, управляемые ядром. Она заменяет оригинальную Open Sound System (OSS). Помимо драйверов звуковых устройств, ALSA также включает в себя библиотеку пользовательского пространства для разработчиков приложений. Затем они могут использовать эти драйверы ALSA для разработки API высокого уровня. Это обеспечивает прямое (ядро) взаимодействие со звуковыми устройствами через библиотеки ALSA. ALSA имеет следующие важные особенности: Эффективная поддержка всех типов аудиоинтерфейсов: от бытовых звуковых карт до профессиональных многоканальных аудиоинтерфейсов. Полностью модульные звуковые драйверы. SMP и потокобезопасная конструкция. Библиотека пользовательского пространства (alsa-lib) для упрощения программирования приложений и обеспечения более высокого уровня функциональности. Поддержка старого API Open Sound System (OSS), обеспечивающая двоичную совместимость для большинства программ OSS. Этот проект Лицензируется под GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://www.alsa-project.org/ ; (https://www.alsa-project.org/wiki/Documentation ; https://archlinux.org/packages/extra/x86_64/alsa-utils/). "
echo -e "${BLUE}:: ${NC}Некоторые функции ALSA (Advanced Linux Sound Architecture): Поддержка многоканального звука. ALSA позволяет использовать объёмный звук и другие сложные аудиоконфигурации. Это важно для современных игр, систем домашнего кинотеатра и профессиональной аудиопродукции. Поддержка MIDI. ALSA позволяет музыкантам и композиторам подключать MIDI-клавиатуры, синтезаторы и другие инструменты к своим системам Linux. Обработка звука с низкой задержкой. ALSA минимизирует задержку между входом и выходом звука. Это важно для аудиоприложений, работающих в реальном времени, таких как запись и живые выступления. Поддержка плагинов. ALSA позволяет разработчикам расширять свои возможности с помощью собственных модулей. Это даёт пользователям возможность настраивать ALSA под свои потребности и конфигурации оборудования. Расширенные возможности микширования. ALSA позволяет пользователям контролировать уровень громкости и маршрутизацию различных аудиопотоков. Это особенно полезно для управления несколькими источниками звука и создания собственных звуковых эффектов. Поддержка нескольких звуковых карт. ALSA может управлять несколькими звуковыми картами в системе одновременно. Можно указать, какую карту использовать для воспроизведения или записи. "
echo -e "${CYAN}:: ${NC}Компоненты ALSA (Advanced Linux Sound Architecture ) в Linux: Драйверы ядра: Драйверы ALSA встроены в ядро Linux и взаимодействуют с оборудованием. Пример: /proc/asound/cards список обнаруженных звуковых карт. Библиотека пользовательского пространства ( libasound): Пакет alsa-lib предоставляет API для взаимодействия со звуковыми устройствами. Приложения используют эту библиотеку для взаимодействия с ALSA. Утилиты и инструменты: aplay/arecord – Воспроизведение и запись звука. alsamixer– Отрегулируйте громкость и другие параметры. amixer– Инструмент командной строки для управления настройками звука. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
#echo " Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter") "
#read -p " 1 - Да установить, 0 - НЕТ - Пропустить установку: " prog_set  # To confirm the input actions, click 'Enter' ; # Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter")
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_alsa  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_alsa" =~ [^10] ]]
do
    :
done
if [[ $in_alsa == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
