clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Cadence (cadence) — Набор инструментов JACK для аудиопроизводства?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Cadence входит в состав KXStudio и позволяет автоматически запускать JACK в фоновом режиме при входе в систему. JACK Audio Connection Kit (или JACK; рекурсивная аббревиатура) — это профессиональный демон звукового сервера, который обеспечивает соединения в реальном времени с малой задержкой для аудио- и MIDI-данных между приложениями, реализующими его API. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Cadence — удобный Python / QT графический интерфейс для комплекта инструментов "Cadence tools", автор Филипе Коэльо (Filipe Coelho / falkTX), разрабатывается для проекта KXStudio. KXStudio — хорошо продуманный набор приложений и плагинов для профессиональных музыкантов. Приложения проекта доступны по отдельности, в исходном коде и как Debian и Ubuntu хранилища пакетов (KXStudio : Repositories). Доступна готовая к использованию мультимедийная студия на основе Ubuntu с средой рабочего стола KDE, работающая в Live-режиме с возможностью установки (live install). Все инструменты Cadence используют один и тот же базовый исходный код, поэтому графические интерфейсы большинства из них выглядят похоже (это сделано преднамеренно). При необходимости в комплект инструментов могут добавляться пользовательские виджеты (например pixmapdial, pixmapkeyboard, patchcanvas и systray). Cadence можно запустить как 'cadence'. Запуск с опцией '--minimized' запустит программу в свёрнутом виде в системном трее. Этот проект Лицензируется под GNU General Public License version 2 (GNU GPL v2). ${NC}"
echo " Домашняя страница: https://github.com/falkTX/Cadence ; (https://kx.studio/Applications:Cadence ; https://aur.archlinux.org/packages/cadence). "
echo -e "${BLUE}:: ${NC}Большинство приложений из набора инструментов "Cadence tools" являются самостоятельными и могут использоваться независимо от "основного" интерфейса. Основными приложениями набора Cadence являются Catarina, Catia и Claudia (Claudia-Launcher), имеются вспомогательные JackMeter (Cadence-JackMeter), Logs, Render и XY Controller. Cadence интегрируется в область уведомлений (системный трей), позволяет задать пути к LADSPA, LV2, VST и DSSI плагинам (плагины применяемые в аудио-софте и отвечающие за генерацию, а также преобразование звука), встроенный диалог настройки JackSettings позволяет изменить параметры JACK2 и JACK1+DBus. "
echo -e "${CYAN}:: ${NC}Краткое описание основных инструментов: Cadence — Основное приложение. Оно выполняет проверки системы, управляет JACK, вызывает другие инструменты и вносит изменения в систему. Cadence-JackMeter — Цифровой пиковый измеритель для JACK. Он автоматически подключается ко всем выходным портам JACK приложения, которые также подключены к выходу системы. Cadence-JackSettings — Простой и удобный диалог настройки для jackdbus. Он позволяет настраивать параметры драйвера и движка JACK, а также поддерживает студии LADISH. Cadence-Logs — Небольшой инструмент, отображающий журналы JACK, A2J, LASH и LADISH в окне с несколькими вкладками. Журналы отображаются в текстовом поле, что упрощает просмотр и извлечение сообщений о состоянии с помощью команд копирования и вставки. Cadence-Render — Инструмент для записи (или «рендеринга») проекта JACK с помощью jack-capture, управляемый JACK Transport. Он поддерживает огромное количество типов файлов и может выполнять рендеринг как в реальном времени, так и в режиме свободного хода. Cadence-XY Controller — Простой виджет XY, который отправляет и получает данные от Jack MIDI. Он может отправлять данные по определённым каналам и имеет MIDI-клавиатуру. Catarina — Тестовое приложение Patchbay, созданное во время разработки модуля patchcanvas. Оно позволяет пользователю экспериментировать с Patchbay без использования ALSA, JACK или LADISH. Также можно сохранять и загружать конфигурации Patchbay. Catia — JACK Patchbay с такими полезными функциями, как поддержка моста A2J и JACK Transport. Он должен быть максимально простым (для продвинутых задач есть Claudia), поэтому отлично работает как на Windows, так и на Mac. В настоящее время поддержка ALSA-MIDI находится в экспериментальной стадии (он не обновляет холст автоматически при внесении внешних изменений). Claudia — Интерфейс LADISH; похож на Catia, но ориентирован на управление сеансами через LADISH. Он предлагает немного больше возможностей, чем официальный графический интерфейс LADISH, с удобным предварительным просмотром основного холста в левом нижнем углу. Он также реализует стиль надстройки «Claudia-Launcher» для LADISH. Claudia-Launcher — Модуль запуска мультимедийных приложений с поддержкой LADISH. Он ищет установленные пакеты (не исполняемые файлы) и отображает соответствующее содержимое в виде модуля запуска. Содержимое загружается из жёстко заданной базы данных, создаваемой и/или модифицируемой в соответствии с целевым дистрибутивом. В настоящее время поддерживает дистрибутивы на базе Debian и ArchLinux. "
echo -e "${CYAN}:: ${NC}Установка Cadence (cadence), проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/cadence.git), (https://aur.archlinux.org/packages/cadence) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_cadence  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_cadence" =~ [^10] ]]
do
    :
done
if [[ $in_cadence == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_cadence == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Cadence (cadence) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
