############ Зависимости ##############
sudo pacman -S --noconfirm --needed jack_capture  # Простой инструмент командной строки для записи аудиовыхода JACK в файл ; https://archlinux.org/packages/extra/x86_64/jack_capture/ ; https://github.com/kmatheussen/jack_capture ; 2023-05-19 16:58 UTC
sudo pacman -S --noconfirm --needed liblo  # Облегченная реализация OSC (открытого управления звуком) ; https://archlinux.org/packages/extra/x86_64/liblo/ ; http://liblo.sourceforge.net/ ; Обеспечивает: liblo.so=7-64 ; 2024-02-17 17:11 UTC
sudo pacman -S --noconfirm --needed python-rdflib  # (необязательно) – поддержка LADSPA-RDF в Carla ; Библиотека Python для работы с RDF — простым, но мощным языком представления информации ; https://archlinux.org/packages/extra/any/python-rdflib/ ; https://github.com/RDFLib/rdflib ; 2025-04-14 19:06 UTC
sudo pacman -S --noconfirm --needed zita-ajbridge  # (необязательно) – мост ALSA-JACK ; Клиент Джека может использовать дополнительные устройства ALSA ; https://archlinux.org/packages/extra/x86_64/zita-ajbridge/ ; https://kokkinizita.linuxaudio.org/linuxaudio/zita-ajbridge-doc/quickguide.html ; 2024-07-14 04:39 UTC
######## cadence #########
yay -Syy
yay -S cadence --noconfirm # Набор инструментов JACK для аудиопроизводства ; https://aur.archlinux.org/packages/cadence ; https://aur.archlinux.org/cadence.git (только для чтения, нажмите, чтобы скопировать) ; https://kx.studio/Applications:Cadence ; https://linuxaudio.github.io/libremusicproduction/html/tools/cadence.html ; https://zenway.ru/page/cadence ; https://github.com/falkTX/Cadence ; https://github.com/falkTX/cadence/archive/v0.9.2/cadence-v0.9.2.tar.gz ; https://aur.archlinux.org/cgit/aur.git/tree/0001-cadence_aloop_daemon-place-lockfile-into-non-public-.patch?h=cadence ; https://aur.archlinux.org/cgit/aur.git/tree/0001-cadence_py-wine-ASIO-settings-use-safe-tempfile.patch?h=cadence ; 2024-03-19 22:41 (UTC)
