clear
echo ""
echo -e "${BLUE}:: ${NC}Установить PipeWire (pipewire) — Новый низкоуровневый мультимедийный фреймворк (и программа аудиосервера)?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Проект PipeWire позиционируется разработчиками как сервер, идущий на смену звуковому серверу PulseAudio и отличается от него добавлением средств для работы с потоками видео, возможностью обработки звука с минимальными задержками и новой моделью безопасности для управления доступом на уровне отдельных устройств и потоков. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}PipeWire (Pinos) — это проект, направленный на значительное улучшение обработки аудио и видео в Linux. Он предоставляет графическую обработку с низкой задержкой поверх аудио- и видеоустройств, которую можно использовать для поддержки вариантов использования, которые в настоящее время обрабатываются как PulseAudio, так и JACK. PipeWire был разработан с мощной моделью безопасности, которая упрощает взаимодействие с аудио- и видеоустройствами из контейнерных приложений, при этом поддержка приложений Flatpak является основной целью. Наряду с Wayland и Flatpak мы ожидаем, что PipeWire предоставит основной строительный блок для будущего разработки приложений Linux. Этот проект Лицензируется под LGPL-2.1 или более поздняя версия, MIT. ${NC}"
echo " Домашняя страница: https://www.pipewire.org/ ; (https://wiki.archlinux.org/title/PipeWire). "
echo -e "${BLUE}:: ${NC}Возможности PipeWire: Захват и воспроизведение аудио и видео с минимальной задержкой. Обработка мультимедиа в реальном времени аудио и видео. Многопроцессорная архитектура, позволяющая приложениям обмениваться мультимедийным контентом. Полная поддержка приложений PulseAudio, JACK, ALSA и GStreamer. Поддержка изолированных приложений. PipeWire выигрывает по набору функций: Унифицированное решение, призванное заменить PulseAudio и JACK и обеспечить решение как для простых, так и для профессиональных пользователей. Лучшая поддержка низкой задержки. Совместимость с API PulseAudio и JACK. Виртуальная поддержка всех кодеков Bluetooth по умолчанию. Эффективное объединение устройств и ресэмплинг. Он может динамически переключаться между различными размерами буфера, чтобы адаптироваться к различным требованиям к задержке различных аудиоприложений. Поддержка приложений Flatpak. Поддержка рабочего стола Wayland. "
echo -e "${CYAN}:: ${NC}*Начну с того, что «Если ничего не сломалось, не стоит лезть чините». Еще не все дистрибутивы Linux перешли на PipeWire, и некоторые пользователи наслаждаются аудио, как раньше, с PulseAudio, поскольку он отлично работает. Для пользователей с современными Bluetooth-наушниками или если у вас плохой звук с PulseAudio, вы можете перейти на PipeWire. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
#echo " Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter") "
#read -p " 1 - Да установить, 0 - НЕТ - Пропустить установку: " prog_set  # To confirm the input actions, click 'Enter' ; # Чтобы подтвердить действия ввода, нажмите кнопку 'Ввод' ("Enter")
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_pipewire  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_pipewire" =~ [^10] ]]
do
    :
done
if [[ $in_pipewire == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_pipewire == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) PipeWire (pipewire) "
  echo " Установка утилит (пакетов) поддержки Sound support PipeWire (pipewire-alsa, pipewire-jack...) "
