clear
echo -e "${MAGENTA}
  <<< Установка утилит (пакетов) — Кодеков и плагинов для Мультимедиа в Archlinux ♬ 🎬 📷 🎨 📀 >>> ${NC}"
# Installing utilities (packages) Codecs and plug-ins for Multimedia in Archlinux
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Конечно, вы будете использовать свою персональную систему для развлечений, таких как просмотр видео и прослушивание любимой музыки. Но перед этим вам нужно будет установить кодеки для этих аудио- и видеофайлов. ${NC}"
sleep 01
#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Кодеки и плагины — для Мультимедийных приложений?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *По умолчанию для запуска некоторых мультимедийных приложений, таких как музыка, песни, видео, необходимо сначала установить кодеки и плагины. Кодек — это устройство или компьютерная программа, способные кодировать и/или декодировать цифровой поток данных или сигнал». Как правило, кодеки используются мультимедийными приложениями для кодирования и декодирования аудио- и видеопотоков. Для воспроизведения закодированных потоков пользователям необходимо установить соответствующий кодек.  ${NC}"
echo -e "${MAGENTA}:: ${BOLD}*В сценарии (скрипта) предоставлены самые распространённые кодеки и плагины, которые рекомендуется установить! Здесь также будут предоставлены: Кодеки и плагины для аудио (аудиопотоков)(аудиодекодеров) и видеофайлов (видеопотоков)(видеодекодоров). GStreamer (мощный фреймворк), GStreamer (библиотеки), а также кодеки и плагины для него. Grilo (фреймворк) для медиа, а также плагины. Библиотеки и инструменты для чтения, создания CD/DVD/BluRay дисков. Кодеки изображений для оптимизации и сжатия файлов JPEG/JFIF; JPG и PNG. Кодеки для графики DEC SIXEL и некоторые консольные программы-конвертеры. Библиотеки, утилиты (пакеты) и различные дополнения, которые по моему опыту не будут лишними и пригодятся вам для дальнейшего безоблачного взаимодействия с вашими настолько любимыми музыкальными проигрывателями, видеоплеерами и различными программами-конвертерами. Эти проекты Лицензируется под различными лицензиями. ${NC}"
echo " Домашняя страница: https://wiki.archlinux.org/title/Codecs_and_containers ; (https://github.com/greg-js/arch-wiki-md-repo/blob/master/wiki/_content/russian/Codecs%20and%20containers%20(russian).md). "
echo -e "${BLUE}:: ${NC}Список устанавливаемых кодеков и плагинов, библиотек обширен, подбирал в связи с запросами и разнообразием мультимедиа утилит. Вот небольшой пример списока утилит (пакетов) для установки: (a52dec, faac, faad2, flac, frei0r-plugins, jasper, lame, libid3tag, libdca, libdv, libmad, libmpeg2, libtheora, libvorbis, libxv, wavpack, x264, xvidcore, gst-plugins-base, gst-plugins-base-libs, gst-plugins-good, gst-plugins-bad, gst-plugins-ugly, libdvdcss, libdvdread, libdvdnav, dvd+rw-tools, dvdauthor, dvgrab, gst-libav, gpac и т.д.). GStreamer: (gstreamer, gstreamer-docs, gstreamer-vaapi, gst-libav, gst-plugins-bad, gst-plugins-base, gst-plugins-base-libs, gst-plugins-good, gst-plugins-ugly, gstreamermm, gstreamermm-docs, libde265, xine-lib и т. д.). Кодеки для графики DEC SIXEL: ((libsixel, lsix). "
echo -e "${CYAN}:: ${NC}После установки вы сможете запустить (установить) музыкальный проигрыватель, видеоплеер и т. д. Но вам также потребуется установить медиаплеер (например, VLC Player, MPlayer, Audacious и т. д.). Мультимедиа плееры, а также различные Конвертеры будут предоставлены в сценарии (скрипта): multimedia_prog. Там постарался прописать (предоставить на выбор), как новый так и проверенный годами (а где то десятилетиями) софт. "
echo -e "${CYAN}:: ${NC}Установка утилит (пакетов) кодеков (celt), (aften) и (davs2), проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/celt.git), (https://aur.archlinux.org/aften.git), (https://aur.archlinux.org/davs2.git) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! *НЕ Переживайте! зависимостями для этих пакетов являются сами кодеки. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
