### fdkaac — интерфейс командной строки для кодировщика libfdk-aac . **fdkaac** считывает линейный PCM-аудио в форматах WAV, RAW PCM или CAF, и кодирует его в файл M4A / AAC. Если входной файл — «-», данные считываются со стандартного ввода. Аналогично, если выходной файл - "-", данные записываются в стандартный вывод, если один из потоков AAC. Транспортные форматы выбираются с помощью **-f**. При использовании ввода CAF и вывода M4A теги из файла CAF копируются в получившийся М4А.
