  echo ""
  echo " Установка Grilo (фреймворк) для медиа, а также плагины "
  echo " Grilo — фреймворк для работы с медиа на Linux, разработанный в рамках проекта GNOME "
# . Цель — упростить поиск и просмотр контента из различных источников для разработчиков приложений. Grilo предоставляет: Одно API высокого уровня для взаимодействия с различными поставщиками контента медиа. Это позволяет разработчикам приложений интегрировать контент из разных сервисов и источников. Систему плагинов для доступа к контенту от разных поставщиков медиа. Плагин — это оболочка публичных API, предоставляемых поставщиком, которая адаптирует их к кросс-сервисным API, определённым Grilo. Гибкое API для разработчиков плагинов, что позволяет писать плагины разных видов.
############## плагин Grilo для медиа ###################
