### Xine - универсальный медиа-плеер написанный как разделяемая библиотека (xine-lib), которая поддерживает многочисленные фронтенды (xine-ui). Xine также может использовать библиотеки из других проектов, включая двоичные кодеки Windows. xine — бесплатный медиаплеер. Он воспроизводит CD, DVD, Blu-Ray и VCD. Он также декодирует файлы мультимедиа, такие как AVI, MOV, WMV и MP3, с локальных дисков и воспроизводит потоковое мультимедиа через Интернет.
