### Скрипт для преобразования файлов WAV, Ogg, MP3, MPC, FLAC, APE или WMA в файлы WAV, Ogg, MP3, MPC, FLAC или APE. Благодаря простому интерфейсу можно заполнить теги для нескольких форматов и выбрать качество сжатия. Изначально скрипт был разработан для файлового браузера Nautilus и может быть легко установлен на нем, скопировав его в каталог Nautilus-Scripts. Затем достаточно щелкнуть правой кнопкой мыши по нужному аудиофайлу или файлам и выбрать пункт «Audio-Convert» в меню «Scripts». Известно, что скрипт также работает в Rox и, конечно же, в Bash, для которой он был написан.
