### espeakup — это программа, которая позволяет SpeakUp использовать программный синтезатор espeak-ng. Она считывает текст с программного синтезатора SpeakUp и передаёт его в espeak-ng, который, в свою очередь, и озвучивает его. Эту программу следует запускать после настройки SpeakUp для взаимодействия с программным синтезатором и после создания /dev/softsynth. Способ реализации зависит от дистрибутива и выходит за рамки данной документации.
########## Пример - espeak "Welcome to the system. My lord and master, it is delightful to serve you again."
