### CELT — аудиокодек с очень низкой задержкой, разработанный для высококачественной связи. Традиционные полнодиапазонные кодеки, такие как Vorbis и AAC, могут обеспечить высокую скорость передачи данных, качество, но они требуют задержек кодека в сотни миллисекунд, что делает их непригодными для интерактивных приложений в реальном времени, таких как теле-Конференц-связь. Кодеки, ориентированные на речевые функции, такие как Speex или G.722, имеют более низкую Задержки 20–40 мс, но их речевая направленность и ограниченная частота дискретизации ограничивает их качество, особенно это касается музыки. Кроме того, другие обязательные компоненты полноценной сетевой аудиосистемы — Аудиоинтерфейсы, маршрутизаторы, буферы джиттера — каждый из них добавляет свою задержку. Для более низких скорость сетей - это время, необходимое для сериализации пакета в сетевом кабеле занимает значительное время, а на больших расстояниях скорость света приводит к значительной задержке.
