### AVS2 — китайский стандарт кодирования видео (преемник AVS), более подробную информацию можно найти здесь (https://web.archive.org/web/20150118050358/http://www.avs.org.cn/english/aboutavs.asp). Запустить AVS2 с помощью ffmpeg - Проверьте, поддерживает ли ffmpeg кодирование xavs2. Пример: ffmpeg -codecs | findstr libxavs2 . Пример: Кодирование потока AVS2, размер GOP – 60 кадров, без B-кадров, битрейт – 600 Кбит/с, контейнер – avi-container :
# ffmpeg  -video_size 384x320  -pixel_format yuv420p -i
# battlefield_384x320.yuv -b:v 600k -refs 1 -bf 0 -g 60 -me_method hex -r 60 -vcodec libxavs2  -y  battlefield_384x320_avs2.avi
