clear
echo -e "${MAGENTA}
  <<< Установка утилит (пакетов) Компрессоров / архиваторов, Библиотек сжатия в Archlinux 📚 >>> ${NC}"
# Installing utilities (packages) Compressors / archivers, Compression libraries in Archlinux
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Архивирование или сжатие данных — это метод или алгоритм, который можно использовать для сжатия данных и уменьшения их размера. Сжатие данных полезно для хранения файлов на диске и их отправки через интернет. При распаковке данных используется обратный алгоритм, чтобы восстановить файлы в их первоначальном виде. Сжатие или архивирование необходимо для анализа, хранения и передачи данных. ${NC}"
sleep 01
#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Компрессоры (консольные), библиотеки сжатия (дополнения) — для архивирования и сжатия файлов (данных)?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Традиционные инструменты архивирования и сжатия Unix подразделяются в соответствии с философией Unix: Архиватор объединяет несколько файлов в один архивный файл, например, tar . Инструмент сжатия сжимает и расжимает данные, например, gzip . Эти инструменты часто используются последовательно: сначала создается архивный файл, а затем он сжимается. Конечно, существуют и универсальные инструменты, которые умеют выполнять обе задачи, а также дополнительные методы шифрования, обнаружения ошибок и восстановления. Для сохранения содержимого архива необходимо знать его формат. Если файл-архив имеет правильное название, его формат можно определить по расширению. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Список устанавливаемых компрессоров и библиотек обширен, подбирал в связи с запросами и новыми разработками (методами работы с архивами, контейнерами упаковки). Вот небольшой пример списока утилит (пакетов) для установки: (zip, unzip, unrar, unarchiver, p7zip, zlib, zziplib, lzop, lha, unace, lrzip, sharutils, uudeview, arj, cabextract, uudeview, snappy, minizip, quazip, brotli, pbzip2 и т.д.). Как выяснилось за годы работы (использования), не знаешь когда пригодится, а нужной (тютю) просто нет (и начинаем чесаться в неприличных местах). Эти проекты Лицензируется под различными лицензиями. ${NC}"
echo " Домашняя страница: https://wiki.archlinux.org/title/Archiving_and_compression ; (https://man.archlinux.org/man/tar.1#UNIX-style_usage). "
echo -e "${CYAN}:: ${NC}После установки вы сможете начать полльзоваться (запустить) архивацию нужных вам файлов (папок). Но для большего удобства использования, вам также потребуется установить Менеджер архива (графический интерфейс) (например, Xarchiver, PeaZip, Ark и т. д.). Менеджеры архивов будут предоставлены далее в сценарии (этого скрипта). Там постарался прописать (предоставить на выбор), как новый так и проверенный годами (а где то десятилетиями) утилиты (пакеты) графических менеджеров для архивирования. "
 echo -e "${CYAN}:: ${NC}Установка утилит (пакетов) кодеков (pxz-git) и (plzip), проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/pxz-git.git), (https://aur.archlinux.org/plzip.git) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
  echo -e "${YELLOW} Примечание! ${BOLD} *НЕ Переживайте! зависимостями для этих пакетов являются библиотеки сжатия. Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_zip  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_zip" =~ [^10] ]]
do
    :
done
if [[ $in_zip == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_zip == 1 ]]; then
  echo ""
  echo " Установка утилит (пакетов) Компрессионных инструментов, библиотек сжатия "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
############# Библиотеки сжатия (дополнения) #################
sudo pacman -S --noconfirm --needed zlib  # Библиотека сжатия, реализующая метод сжатия deflate, используемый в gzip и PKZIP ; https://archlinux.org/packages/core/x86_64/zlib/ ; Обеспечивает: libz.so=1-64 ; Обратные конфликты: zlib-ng-compat ; 2024-05-03 07:02 UTC
sudo pacman -S --noconfirm --needed zlib-ng  # Замена zlib с оптимизацией для систем следующего поколения ; https://archlinux.org/packages/extra/x86_64/zlib-ng/ ; https://github.com/zlib-ng/zlib-ng ; Обеспечивает: libz-ng.so=2-64 ; 2025-08-08 11:04 UTC
sudo pacman -S --noconfirm --needed bzip2  # поддержка bzip2 ; Высококачественная программа сжатия данных ; https://archlinux.org/packages/core/x86_64/bzip2/ ; https://sourceware.org/bzip2/ ; Обеспечивает: libbz2.so=1.0-64 ; 2024-03-18 07:56 UTC
sudo pacman -S --noconfirm --needed lzo  # Портативная библиотека сжатия данных без потерь ; https://archlinux.org/packages/core/x86_64/lzo/ ; https://www.oberhumer.com/opensource/lzo ; Обеспечивает: liblzo2.so=2-64, libminilzo.so=0-64 ; 2023-01-26 10:04 UTC
sudo pacman -S --noconfirm --needed lz4  # поддержка LZ4 ; Чрезвычайно быстрый алгоритм сжатия ; https://archlinux.org/packages/core/x86_64/lz4/ ; https://lz4.github.io/lz4/ ; Обеспечивает: liblz4.so=1-64 ; 2024-07-31 06:45 UTC
sudo pacman -S --noconfirm --needed xz  # Библиотека и инструменты командной строки для сжатых файлов XZ и LZMA ; https://archlinux.org/packages/core/x86_64/xz/ ; https://tukaani.org/xz/ ; Обеспечивает: liblzma.so=5-64 ; 2025-04-03 22:40 UTC
sudo pacman -S --noconfirm --needed zstd  # поддержка zstd ; Zstandard — быстрый алгоритм сжатия в реальном времени ; https://archlinux.org/packages/core/x86_64/zstd/ ; https://facebook.github.io/zstd/ ; Обеспечивает: libzstd.so=1-64 ; 2025-02-23 20:59 UTC
sudo pacman -S --noconfirm --needed lzlib  # Библиотека, предоставляющая функции сжатия и распаковки LZMA в памяти ; https://archlinux.org/packages/extra/x86_64/lzlib/ ; http://www.nongnu.org/lzip/lzlib.html ; 2025-06-18 06:44 UTC
sudo pacman -S --noconfirm --needed libzip  # Библиотека C для чтения, создания и изменения zip-архивов ; https://archlinux.org/packages/extra/x86_64/libzip/ ; https://libzip.org/ ; 2025-05-25 07:16 UTC
sudo pacman -S --noconfirm --needed snappy  # Библиотека быстрого сжатия и распаковки (на порядок быстрее других)  ; https://archlinux.org/packages/extra/x86_64/snappy/ ; https://github.com/google/snappy ; Обеспечивает: libsnappy.so=1-64 ; 2025-04-20 11:39 UTC
sudo pacman -S --noconfirm --needed libarchive  # Многоформатная библиотека архивации и сжатия ; https://archlinux.org/packages/core/x86_64/libarchive/ ; https://libarchive.org/ ; Обеспечивает: libarchive.so=13-64 ; 2025-06-02 14:16 UTC
sudo pacman -S --noconfirm --needed gettext  # Библиотека интернационализации GNU ; https://archlinux.org/packages/core/x86_64/gettext/ ; https://www.gnu.org/software/gettext/ ; 2025-07-22 16:31 UTC
sudo pacman -S --noconfirm --needed tar  # Утилита, используемая для хранения, резервного копирования и транспортировки файлов ; https://archlinux.org/packages/core/x86_64/tar/ ; https://www.gnu.org/software/tar/ ; 2023-10-08 18:26 UTC
