sudo pacman -S --noconfirm --needed zip  # Компрессор/архиватор для создания и изменения zip-файлов ; https://archlinux.org/packages/extra/x86_64/zip/ ; http://www.info-zip.org/Zip.html ; 2023-10-06 18:47 UTC
