sudo pacman -S --noconfirm --needed lzop  # поддержка LZOP ; Компрессор файлов с использованием библиотеки lzo lib ; https://archlinux.org/packages/extra/x86_64/lzop/ ; https://www.lzop.org/ ; 2024-07-12 22:27 UTC
sudo pacman -S --noconfirm --needed minizip  # Mini zip и unzip на основе zlib ; https://archlinux.org/packages/core/x86_64/minizip/ ; https://www.zlib.net/ ; 2024-05-03 07:02 UTC
