sudo pacman -S --noconfirm --needed bzip3  # Лучший и более сильный духовный преемник BZip2 ; поддержка сжатия bzip3 ; https://archlinux.org/packages/extra/x86_64/bzip3/ ; https://github.com/kspalaiologos/bzip3 ; Обеспечивает: libbzip3.so=1-64 ; 2025-08-13 16:24 UTC
sudo pacman -S --noconfirm --needed unarchiver  # unar и lsar: инструменты Objective-C для распаковки архивных файлов ; https://archlinux.org/packages/extra/x86_64/unarchiver/ ; https://github.com/MacPaw/XADMaster ; 2025-05-16 02:19 UTC
sudo pacman -S --noconfirm --needed lrzip  # поддержка lrzip ; Многопоточное сжатие с помощью rzip/lzma, lzo и zpaq ; https://archlinux.org/packages/extra/x86_64/lrzip/ ; https://github.com/ckolivas/lrzip ; 2024-06-30 21:42 UTC
