sudo pacman -S --noconfirm --needed arj  # поддержка ARJ ; Бесплатный и портативный клон архиватора ARJ ; https://archlinux.org/packages/extra/x86_64/arj/ ; http://arj.sourceforge.net/ ;  2024-09-06 19:06 UTC
