sudo pacman -S --noconfirm --needed sharutils  # Создает (Делает) так называемые архивы оболочек из множества файлов ; https://archlinux.org/packages/extra/x86_64/sharutils/ ; https://www.gnu.org/software/sharutils/ ; 2024-02-03 20:48 UTC
