# Архивирование и сжатие ArchWiki:
# https://wiki.archlinux.org/title/Archiving_and_compression
### ARJ (сокращение от Archived by Robert Jung) - формат архивированных файлов с использованием программного обеспечения,
### Формат командной строки ARJ таков:
# Основные команды:
# a - добавить в архив;
# u - добавить в архив, обновляя существующие файлы, если их время изменилось, и добавляя отсутствующие;
# f - то же самое, но отсутствующие файлы не добавляются;
# l - вывести содержимое архива;
# e - распаковать в текущий каталог;
# x - распаковать с путями.
### Руководство по GNU TAR:
# Название: tar - утилита архивирования
# GNU tar — это программа архивации, предназначенная для хранения нескольких файлов в одном файле ( архиве ) и работы с такими архивами. Архив может представлять собой как обычный файл, так и устройство (например, ленточный накопитель, отсюда и название программы, которое расшифровывается как t ape ar chiver), расположенное как на локальной, так и на удалённой машине.
# СИНОПСИС (SYNOPSIS) https://man.archlinux.org/man/tar.1
# Традиционное использование:
# tar {A|c|d|r|t|u|x}[GnSkUWOmpsMBiajJzZhPlRvwo] [ARG...]
# Использование в стиле UNIX:
# tar -A [ ПАРАМЕТРЫ ] -f АРХИВ АРХИВ ...
# tar -A [OPTIONS] -f ARCHIVE ARCHIVE...
# tar -c [-f ARCHIVE] [OPTIONS] [FILE...]
# tar -d [-f ARCHIVE] [OPTIONS] [FILE...]
# tar -r [-f ARCHIVE] [OPTIONS] [FILE...]
# tar -t [-f ARCHIVE] [OPTIONS] [MEMBER...]
# tar -u [-f ARCHIVE] [OPTIONS] [FILE...]
# tar -x [-f ARCHIVE] [OPTIONS] [MEMBER...]
# Использование в стиле GNU:
# tar { --catenate | --concatenate } [ ПАРАМЕТРЫ ] --file АРХИВ АРХИВ ...
# tar {--catenate|--concatenate} [OPTIONS] --file ARCHIVE ARCHIVE...
# tar --create [--file ARCHIVE] [OPTIONS] [FILE...]
# tar {--diff|--compare} [--file ARCHIVE] [OPTIONS] [FILE...]
# tar --delete [--file ARCHIVE] [OPTIONS] [MEMBER...]
# tar --append [--file ARCHIVE] [OPTIONS] [FILE...]
# tar --list [--file ARCHIVE] [OPTIONS] [MEMBER...]
# tar --test-label [--file ARCHIVE] [OPTIONS] [LABEL...]
# tar --update [--file ARCHIVE] [OPTIONS] [FILE...]
# tar {--extract|--get} [--file ARCHIVE] [OPTIONS] [MEMBER...]
### Zstandard: zstd - zstd, zstdmt, unzstd, zstdcat - Сжатие и распаковка файлов .zst
# СИНОПСИС (SYNOPSIS) https://man.archlinux.org/man/zstd.1.en
# zstd [ ПАРАМЕТРЫ ] [-| ВХОДНОЙ-ФАЙЛ ] [-o ВЫХОДНОЙ-ФАЙЛ ]
# zstd [OPTIONS] [-|INPUT-FILE] [-o OUTPUT-FILE]
# zstdmt is equivalent to zstd -T0
# unzstd is equivalent to zstd -d
# zstdcat is equivalent to zstd -dcf
