echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Для Linux доступны менеджеры архивов — программы, которые позволяют создавать, просматривать, изменять и распаковывать архивы. Работать с архивами в Linux можно двумя способами: через командную строку или с помощью специальных программ. Это файловые менеджеры с функциями архиватора с графическим интерфейсом. В сценарии (скрипте) прописана установка различных Менеджеров (с Графическим интерфейсом) для удобной работы с архивами. Они будут идти в порядке последовательного перечисления, выберите нужный вам менеджер или вы захотите установить сразу парочку утилит, если вам не нужна та или иная утилита (пакет), просто пропустите действие по установке и перейдите к следующим. ${NC}"
