#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить File Roller (file-roller) — Менеджер архивов?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *File Roller является графической оболочкой, предоставляющей единый графический интерфейс для консольных программ-архиваторов в Linux. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}File Roller — Легковесный менеджер архивов для среды рабочего стола GNOME, можно использовать и для других DE (XFCE, LXDE, Lxqt...). File-roller не выполняет операции архивации самостоятельно, а использует для этого стандартные инструменты. File Roller — это всего лишь графический интерфейс для программ-архиваторов, таких как tar и zip. Это означает, что вы можете создавать и изменять архивы, просматривать содержимое архива, просматривать и изменять файлы в архиве, а также извлекать файлы из архива. Поддерживает многие популярные форматы архивов, включая ZIP, TAR, GZ и BZ2. Для работы с RAR или 7z может потребоваться установить небольшое дополнение (например, unrar или p7zip). Он позволяет: Создавать и изменять архивы. Просматривать содержимое архива. Просматривать файлы в архиве. Извлекать файлы из архива. Этот проект Лицензируется под GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://wiki.gnome.org/Apps/FileRoller ; (https://github.com/GNOME/file-roller ; https://archlinux.org/packages/extra/x86_64/file-roller/). "
echo -e "${BLUE}:: ${NC}File-roller поддерживает следующие форматы (типы архивов): Сжатый файл 7-Zip (.7z); Сжатый файл WinAce (.ace); Сжатый файл ALZip (.alz); AIX Small Indexed Archive (.ar); Сжатый архив ARJ (.arj); Архивы Cabinet (.cab); Архив UNIX CPIO (.cpio); Бинарные пакеты Debian Linux (.deb) [режим только для чтения]; Образ диска Apple (.dmg) [режим только для чтения]; Образ компакт-диска ISO-9660 (.iso) [режим только для чтения]; Архив Java (.jar); Архив Java Enterprise (.ear); Веб-архив Java (.war); Архив LHA (.lzh, .lha); Сжатый архив WinRAR (.rar); Архив комиксов RAR (.cbr); Пакет RPM Linux (.rpm) [режим только для чтения]. Архивный файл ленты: несжатый (.tar). Или сжатый с помощью: gzip (.tar.gz, .tgz); brotli (.tar.br); bzip (.tar.bz, .tbz); bzip2 (.tar.bz2, .tbz2); bzip3 (.tar.bz3, .tbz3); squeeze (.tar.Z, .taz); lrzip (.tar.lrz, .tlrz); lzip (.tar.lz, .tlz); lzop (.tar.lzo, .tzo); 7zip (.tar.7z); xz (.tar.xz); Zstandard (.tar.zst, .tzst); Пакеты Snap (.snap); Образы Squashfs (.sqsh); Архивы Stuffit (.bin, .sit); ZIP-архив (.zip); ZIP-архив комиксов (.cbz); Сжатый архивный файл ZOO (.zoo); Отдельные файлы сжаты с помощью gzip (.gz), brotli (.br), bzip (.bz), bzip2 (.bz2), bzip3 (.bz3), compress (.Z), lrzip (.lrz), lzip (.lz), lzop (.lzo), rzip(.rz) и xz (.xz), Zstandard (.zst). "
echo -e "${CYAN}:: ${NC}File Roller позволяет изменять существующие архивы путем добавления, удаления или переименования файлов и папок. Чтобы открыть существующий архив для модификации, просто выберите в меню «Открыть» или дважды щелкните на архивном файле в файловом менеджере. Затем вы можете добавить новые файлы или папки, перетащив их в окно архива или нажав на кнопку «Добавить». Вы также можете удалить файлы, выделив их и нажав на кнопку «Удалить», или переименовать файлы, выделив их и нажав клавишу F2. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
