echo -e "${BLUE}:: ${NC}Установить Xarchiver (xarchiver) — Менеджер архивов?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Xarchiver — оптимальное решение для работы с архивами в Linux и FreeBSD. От автора проекта: Я хотел разработать простой графический интерфейс, совместимый с любой рабочей средой и работающий через командную строку, а не через вызовы API. Xarchiver изначально разрабатывался как быстрый и простой в использовании. Его пользовательский интерфейс понятен и интуитивно понятен, без каких-либо запутанных или бесполезных опций. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Xarchiver — Легковесный настольный независимый файловый архиватор с графическим интерфейсом с открытым исходным кодом для UNIX-подобных операционных систем, созданный с использованием инструментария GTK+ , можно использовать с любой средой рабочего стола. Xarchiver зависит только от библиотек GTK+ и использует различные программы командной строки для (де)компрессии/(рас)архивации во время выполнения. Для построения интерфейса используется библиотека GTK+2/GTK+3. Является архиватором по умолчанию для свободных сред рабочего стола, таких как: Xfce и LXDE, а также менеджера файлов X File Explorer. Подобное легковесное окружение рабочего стола, включающее Xarchiver, востребовано, в частности, при использовании Raspberry Pi. Он позволяет создавать архивы, а также добавлять, извлекать и удалять из них файлы. Поддерживаются защищённые паролем архивы в форматах arj, 7z, rar и zip. Поддерживаются и двойные архивы (например, zip, 7-zip, rar и прочие). Все распространённые форматы архивов поддерживаются, пакеты deb и RPM (наличие самой утилиты rpm не требуется). Этот проект Лицензируется под GPL. ${NC}"
echo " Домашняя страница: https://github.com/ib/xarchiver ; (https://archlinux.org/packages/extra/x86_64/xarchiver/ ; https://archlinux.org/packages/extra/x86_64/xarchiver-gtk2/). "
echo -e "${BLUE}:: ${NC}Xarchiver поддерживает архивы: 7z, a (библиотеки), apk, AppImage, arj, bzip, bzip2, bzip3, cab, cb7, cbr, cbt, cbz, chm, compress, cpio, docx, epub, exe (самораспаковывающиеся архивы Windows), fbz, gzip, iso, jar, jsonlz4, lha, lrzip, lz4, lzip, lzma, lzop, mozlz4, odt, oxt, rar, rzip, snap, squashfs, tar, xpi, xz, zip, zpaq, zstd, tar.bz, tar.bz2, tar.bz3, tar.gz, tar.lrz, tar.lz, tar.lz4, tar.lzma, Файлы tar.lzo, tar.rz, tar.xz, tar.Z, tar.zst и (без менеджеров пакетов) deb и rpm, навигацию по архивам с помощью значков mimetype, возможность комментирования архивов и вывод списка архивов в формате HTML или txt. Поддерживаются также действия «Вырезать», «Копировать», «Вставить» и «Переименовать» внутри файлов разных архивов. Определение паролей для файлов arj, zip и rar происходит автоматически. Шифрование паролей доступно для этих типов файлов, а также для 7-zip. Xarchiver также может генерировать самораспаковывающиеся двоичные файлы из архивов zip, 7-zip и rar и позволяет создавать сплошные архивы. Поддерживается перетаскивание файлов через протокол XDS и вкладки в стиле Firefox. Включена возможность многократного извлечения из архивов с индикатором выполнения. Наконец, что не менее важно, при использовании Xarchiver из командной строки или из файлового менеджера Thunar доступно окно индикатора выполнения. "
echo -e "${CYAN}:: ${NC}Возможности: Просмотр архивов как в файловом менеджере; Поддержка вкладок; Возможность устанавливать пароли для zip, rar, arj и 7z архивов; Вывод списка содержимого архивов в TXT или HTML файл. Другие функции: Через меню "Действие" можно создать комментарий к архиву, назначить пароль для архива или, например, распаковать несколько архивов одновременно. Через меню "Архив" можно посмотреть свойства архива. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
