    0 - НЕТ - Пропустить установку: " in_xarchiver  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_xarchiver" =~ [^120] ]]
do
    :
done
if [[ $in_xarchiver == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
