sudo pacman -S --noconfirm --needed exo  # Библиотека приложений для среды рабочего стола Xfce ; https://archlinux.org/packages/extra/x86_64/exo/ ; https://docs.xfce.org/xfce/exo/start ; 2024-12-25 18:23 UTC
sudo pacman -S --noconfirm --needed xdg-utils  # (необязательно) — распознает больше типов файлов для открытия ; Инструменты командной строки, которые помогают приложениям решать различные задачи интеграции с настольными компьютерами ; https://archlinux.org/packages/extra/any/xdg-utils/ ; https://www.freedesktop.org/wiki/Software/xdg-utils/ ; 2024-02-06 13:02 UTC ; Установка xdg-utils необязательна, но ее установка позволит Xarchiver для поддержки открытия большего количества типов файлов непосредственно из архива.
########### xarchiver ############
sudo pacman -S --noconfirm --needed xarchiver  # Интерфейс GTK+ для различных архиваторов командной строки ; https://archlinux.org/packages/extra/x86_64/xarchiver/ ; https://github.com/ib/xarchiver ; Обратные конфликты: с xarchiver-gtk2 ; 2025-03-25 19:16 UTC
  echo ""
  echo " Посмотрите информацию о версии (xarchiver) "
# xarchiver --version  # Показать версию приложения
sudo pacman -Q xarchiver  #  Показать версию приложения ; Альтернативный метод — проверить версию установленного пакета NTP через менеджер пакетов системы.
# sudo pacman -Qs имя_пакета  # Используйте команду pacman с -Qs опцией поиска только среди установленных пакетов в системе. Она ищет указанный текст только в названиях и описаниях установленных пакетов.
# sudo pacman -Qi имя_пакета  # Эта -Qi опция отображает подробную информацию об указанном пакете. Она также показывает метаданные пакета, такие как зависимости, конфликты, дата установки, дата сборки, размер и т. д.
# sudo pacman -Si имя_пакета  # Эта -Si опция позволяет просматривать подробную информацию о любых пакетах Arch Linux. Необходимо указать точное название пакета.
sleep 03
