sudo pacman -S --noconfirm --needed xarchiver-gtk2  # Легкий настольный независимый менеджер архивов ; GTK+-интерфейс для различных архиваторов командной строки (версия GTK+ 2) ; https://archlinux.org/packages/extra/x86_64/xarchiver-gtk2/ ; https://github.com/ib/xarchiver ; Конфликты: с xarchiver ; 2025-03-25 19:16 UTC
  echo ""
