# Xarchiver (xarchiver):
# https://github.com/ib/xarchiver
# https://man.archlinux.org/man/xarchiver.1.en
# https://ru.wikipedia.org/wiki/SourceForge.net
# https://archlinux.org/packages/extra/x86_64/xarchiver/
