# Менеджер архивов Xarchiver:
# https://docs.applite.ru/Repository/LXQT/Xarchiver
### СИНОПСИС:
# xarchiver [ ВАРИАНТ ] [ архив ]
# xarchiver [OPTION] [archive]
# ПАРАМЕТРЫ:
# -a, --add
# add to archive by asking which files and quit
# добавить в архив, спросив, какие файлы и выйти
# -c, --compress=file1 ... fileN
# add the given files by asking the name of the archive and quit
# добавьте указанные файлы, запросив имя архива, и выйдите
# -d, --ensure-directory
# extract archive to a containing directory and quit
# извлечь архив в содержащий его каталог и выйти
# -e, --extract
# extract archive by asking the extraction directory and quit
# извлечь архив, указав каталог извлечения и выйдя
# -m, --multi-extract
# extract multiple archives by asking the extraction directory and quit
# извлечь несколько архивов, указав каталог извлечения и выйдя
# -x, --extract-to=destination
# extract archive to the destination directory and quit
# извлечь архив в целевой каталог и выйти
# -i, --info
# show found command-line programs to be used and exit
# показать найденные программы командной строки для использования и выйти
# -v, --version
# show version and exit
# показать версию и выйти
# --display=DISPLAY
# X display to use
# X-дисплей для использования
# -?, -h, --help
# show help options
# показать параметры справки
# --help-gtk
# show GTK+ options
# показать параметры GTK+
# --help-all
# show all help options
# показать все варианты помощи
