clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Ark (ark) — Менеджер архивов?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Ark представляет собой фронтенд для командной строки архиваторов. Технически представляет собой графическую оболочку для консольных утилит работы с архивами. Использует другие установленные инструменты для обработки различных форматов архивов (компрессионные инструменты и библиотеки сжатия), а также плагины. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Ark (в переводе Ковчег) — Менеджер архивов для среды рабочего стола KDE (Plasma), можно использовать и для другого DE. Ark — это бесплатная, свободно распространяемая графическая утилита для сжатия/распаковки файлов с поддержкой множества форматов, а также образов CD-ROM. Ark можно использовать для просмотра, извлечения, создания и редактирования архивов. Этот пакет входит в состав модуля утилит KDE SC (kdeutils). Ark поддерживает работу со всеми основными форматами архивов: - (tar, gzip, bzip, bzip2, zip, xpi, lha, zoo, ar, rar) и некоторые другие. Поддерживаются и двойные архивы (например, tar.gz, tzr.bz2 и прочие) и образы компакт-дисков. Ark можно интегрировать в Konqueror и Dolphin благодаря технологии KParts, если установлен соответствующий плагин из пакета kdeaddons. После его установки файлы могут быть добавлены или извлечены в/из архивов с помощью контекстного меню Konqueror. Поддержка редактирования или удаления файлов в архиве с помощью внешних программ. Создание архивов с поддержкой drag and drop. Этот проект Лицензируется под GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://apps.kde.org/ark/ ; (https://github.com/KDE/ark ; https://archlinux.org/packages/extra/x86_64/ark/). "
echo -e "${BLUE}:: ${NC}Программа имеет простой интерфейс, который похож на другие программы такого типа. В основной части главного окна размещается список файлов архива. Сверху расположено меню и управляющие кнопки (Создать, Открыть, Добавить файл, Добавить папку, Удалить, Распаковать и Предпросмотр). В интерфейсе есть опции для выбора формата архива, уровня сжатия и защиты паролем. "
echo -e "${CYAN}:: ${NC}Поддержка всех вышеперечисленных форматов в Ark реализована в ряде плагинов, которые пользователь может включить/отключить. Один и тот же формат может поддерживаться несколькими плагинами. Архив, формат которого поддерживается несколькими плагинами, будет открыт с использованием включённого плагина с более высоким приоритетом. В настоящее время в ark доступны следующие плагины: Плагин Libzip: поддерживает формат Zip с помощью библиотеки libzip. Плагин 7-Zip: поддерживает формат 7-Zip с помощью 7z двоичного файла. Поддерживает как исходный двоичный файл 7-Zip, так и двоичный файл из форка p7zip, поставляемого Archlinux и др. Плагин Unarchiver: поддерживает форматы RAR, LHA и Stuffit в режиме только для чтения. Требуются исполняемые файлы lsar и unar из проекта unarchiver. Плагин RAR: поддерживает формат RAR с помощью двоичного файла unrar. Требует наличия проприетарного rar двоичного файла для поддержки режима чтения-записи при создании архивов RAR. Плагин Info-zip (устаревший): поддерживает формат Zip с использованием zip двоичного файла. Плагин ARJ: поддерживает формат ARJ с использованием arj двоичного файла. Плагин Libarchive: поддерживает все остальное, используя библиотеку libarchive и опционально двоичные файлы lrzip, lzopи zstd. Поддерживает также формат 7-Zip, но только без шифрования. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - Да установить,     0 - НЕТ - Пропустить установку: " in_ark  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_ark" =~ [^10] ]]
do
    :
done
if [[ $in_ark == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_ark == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Ark (ark) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) "
############ Зависимости ##############
sudo pacman -S --noconfirm --needed cmake  # Кроссплатформенная система сборки с открытым исходным кодом ; https://archlinux.org/packages/extra/x86_64/cmake/ ; https://www.cmake.org/ ; 2025-06-12 20:22 UTC
sudo pacman -S --noconfirm --needed extra-cmake-modules  # Дополнительные модули и скрипты для CMake ; https://archlinux.org/packages/extra/any/extra-cmake-modules/ ; https://community.kde.org/Frameworks ; 2025-08-09 02:38 UTC
########### ark #############
sudo pacman -S --noconfirm --needed ark  # архиватор для ( Plasma(kde)- так же можно использовать, и для другого de ) ; Инструмент архивации ; https://archlinux.org/packages/extra/x86_64/ark/ ; https://apps.kde.org/ark/ ; https://github.com/KDE/ark ; Группы: kde-applications, kde-utilities ; 2025-08-16 11:01
  echo ""
  echo " Посмотрите информацию о версии (ark) "
