clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Engrampa (engrampa) — Менеджер архивов?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Engrampa — это форк Archive Manager (File Roller). Engrampa — это всего лишь интерфейс (графический интерфейс) для программ архивации. Engrampa не выполняет архивные операции самостоятельно, а использует для этого стандартные инструменты (компрессионные инструменты и библиотеки сжатия). ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Engrampa — бесплатный, свободно распространяемый менеджер архивов, используемый в среде рабочего стола MATE (Разработчик: The MATE Developers) для Linux. Engrampa поддерживает наиболее распространенные операции, такие как оздание нового архива, изменение существующих архивов и извлечение файлов из архива. Вы также можете просматривать содержимое существующего архива и открывать файлы, содержащиеся в нём (архиве). Engrampa поддерживает работу со всеми основными форматами архивов: - (7-zip, arj, bzip2, gzip, rar, lha, lzma, lzop, deb, rpm, tar, zip) и некоторые другие. Поддерживаются и двойные архивы (например, zip, 7-zip, rar и прочие). Авторами Engrampa являются Паоло Баккилега ( paolo.bacch@tin.it ) и Perberos ( perberos@gmail.com ). Этот проект Лицензируется под GPL-2.0. ${NC}"
echo " Домашняя страница: https://mate-desktop.org/ ; (https://github.com/mate-desktop/engrampa ; https://archlinux.org/packages/extra/x86_64/engrampa/). "
echo -e "${BLUE}:: ${NC}Поддерживаемые типы файлов: Сжатый файл 7-Zip (.7z), Сжатый файл WinAce (.ace), Сжатый файл ALZip (.alz), AIX Small Indexed Archive (.ar), Архив ARC (.arc), Сжатый архив ARJ (.arj), Кабинетный файл (.cab), Архив UNIX CPIO (.cpio), Пакет Debian Linux (.deb) [режим только для чтения], EPUB (.epub), Образ компакт-диска ISO-9660 (.iso) [режим только для чтения], Архив Java (.jar), Архив Java Enterprise (.ear), Веб-архив Java (.war), Архив LHA (.lzh, .lha), Сжатый архив WinRAR (.rar), Архив комиксов RAR (.cbr), Пакет RPM Linux (.rpm) [режим только для чтения]. Архивный файл ленты: несжатый (.tar). Или сжатый с помощью: gzip (.tar.gz, .tgz), brotli (.tar.br), bzip (.tar.bz, .tbz), bzip2 (.tar.bz2 , .tbz2). Сжатие: (.tar.Z , .taz), lrzip (.tar.lrz , .tlrz), lzip (.tar.lz , .tlz), lzop (.tar.lzo , .tzo), 7zip (.tar.7z), xz (.tar.xz). Архивы Stuffit (.bin, .sit), ZIP-архив (.zip), ZIP-архив комиксов (.cbz), Сжатый архивный файл ZOO (.zoo). Отдельные файлы, сжатые с помощью gzip (.gz), brotli (.br), bzip (.bz), bzip2 (.bz2), compress (.Z), lrzip (.lrz), lzip (.lz), lzop (.lzo), rzip (.rz), xz (.xz), Zstandard (.zst). "
echo -e "${CYAN}:: ${NC}Создать архив: Откройте менеджер архивов Engrampa. В верхней части нажмите «Архив» , затем «Новый» . Укажите местоположение папки, имя и формат файла: по расширению. (Необязательно) В разделе «Другие параметры» укажите пароль (только 7-Zip, Zip, RAR и ARJ) и максимальный размер, прежде чем разбить архив на несколько файлов (только 7-Zip и RAR). Нажмите «Создать» . В верхней части нажмите «Изменить» , затем «Добавить файлы» или «Добавить папку» , чтобы добавить необходимые файлы. Нажмите «Архив» , затем «Свойства» , чтобы узнать размер архива и исходного содержимого, степень сжатия и количество включенных файлов. Нажмите «Архивировать» , а затем «Закрыть» после завершения. *Извлечь файлы: Откройте менеджер архивов Engrampa. В верхней части нажмите «Архив» , затем «Открыть» . Нажмите «Архивировать» , затем «Извлечь» , чтобы распаковать все файлы. Или удерживайте Ctrlи щёлкайте по нужным файлам, чтобы извлечь их. Укажите пункт назначения. Нажмите «Извлечь» . "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - Да установить,     0 - НЕТ - Пропустить установку: " in_engrampa  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_engrampa" =~ [^10] ]]
do
    :
done
if [[ $in_engrampa == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_engrampa == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Engrampa (engrampa) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) "
