sudo pacman -S --noconfirm --needed engrampa  # Архиватор файлов для MATE ; https://mate-desktop.org/ ; https://archlinux.org/packages/extra/x86_64/engrampa/ ; https://github.com/mate-desktop/engrampa ; Группы: mate-extra ; Заменяет: engrampa-gtk3 ; Конфликты: с engrampa-gtk3 ; 2024-09-11 08:04 UTC
  echo ""
