# Engrampa (engrampa):
# https://mate-desktop.org/
# https://github.com/mate-desktop/engrampa
# https://manpages.ubuntu.com/manpages/bionic/man1/engrampa.1.html
# https://archlinux.org/packages/extra/x86_64/engrampa/
###  Синтаксис:
# engrampa [ПАРАМЕТР…] - создать или изменить архив
# engrampa [OPTIONS...] [FILES...]
### ПАРАМЕТРЫ:
# Имя файла(ов)...
# filename(s)...
# Указывает файл архива, который будет открываться при запуске Engrampa. Если имя не указано, Engrampa будет
# начните с пустого окна и вы можете открыть архив из меню или с помощью ярлыка CTRL+O.
# -a, --add-to=ARCHIVE
# Добавить файлы в указанный архив и выйти из программы
# -d, --add FILE
# Добавить файлы, спросить имя архива и выйти из программы
# -e, --extract-to=FOLDER
# Извлечь архивы в указанную папку и выйти из программы.
# -f,  --extract
# Извлечь архивы, запросить папку назначения и выйти из программы
# -h,  --extract-here
# Извлеките архивы, используя имя архива в качестве папки назначения, и выйдите из программы.
# --default-dir=FOLDER
# Папка по умолчанию для команд «--add» и «--extract»
# --force
# Создать папку назначения без запроса подтверждения
# --display=ДИСПЛЕЙ
# --display=DISPLAY
# X-дисплей для использования.
# -?, --help
# Распечатать стандартные параметры командной строки.
# --help-all
# Распечатать все параметры командной строки.
# Эта программа также принимает стандартные параметры GTK.
# ПРИМЕРЫ:
# engrampa  -h  matelivecd.iso
# Извлеките matelivecd.iso в ./matelivecd в текущем рабочем каталоге.
# engrampa  ./matelivecd/*  -a  matelivecd.tar.gz
# Создайте новый сжатый gzip архив tarball с именем matelivecd.tar.gz, содержащий все файлы
# расположенный в каталоге ./matelivecd.
# engrampa  matelivecd.tar.gz
# Откройте matelivecd.tar.gz для просмотра и изменения его содержимого.
# Если  вы  обнаружите  какие-либо  ошибки,  о них  можно  сообщить  по адресу:
# http://github.com/mate-desktop/engrampa/issues
