clear
echo ""
echo -e "${BLUE}:: ${NC}Установить PeaZip (peazip) — Архиватор (менеджер архивов)?"
echo -e "${MAGENTA}:: ${BOLD}PeaZip — это бесплатная утилита для архивации файлов и извлечения rar-файлов для BSD, Linux, macOS и Windows, которая работает более чем с 200 типами и вариантами архивов (7z, ace, arc, bz2, cab, gz, iso, paq, pea, rar, tar, wim, zip, zipx...), обрабатывает составные архивы (001, r01, z01...), поддерживает несколько стандартов шифрования архивов, хеширование файлов, экспортирует задачи в виде консольных скриптов. PeaZip предлагает альтернативу фирменному программному обеспечению (WinZip, WinRar и т. д.), PeaZip имеет простой графический интерфейс и предназначена для работы с архивами. В программу встроен файловый менеджер с возможностью просмотра содержимого архивов. В верхней части окна программы расположено главное меню и панель управления. Остальная часть выполнена в виде файлового менеджера. PeaZip распространяется свободно, имеет открытый исходный код. Лицензия: LGPLv3. ${NC}"
echo " Домашняя страница: https://github.com/peazip/PeaZip/ ; (https://aur.archlinux.org/packages/peazip ; https://aur.archlinux.org/packages/peazip-gtk2-bin ; https://aur.archlinux.org/packages/peazip-qt-bin). "
echo -e "${MAGENTA}:: ${BOLD}Основные возможности и особенности программы: Простой и удобный интерфейс в стиле файлового менеджера.
Поддержка более 180 форматов файлов (см. списки ниже). Поиск файлов. Поиск дубликатов файлов. Создание закладок. Просмотр эскизов. Вычисление контрольных сумм. Добавление и редактирование файлов внутри архивов. Конвертирование файлов архивов. Встроенный менеджер паролей. ${NC}"
echo -e "${CYAN}:: ${NC}Поддерживаемые форматы: (Информация с официального сайта программы) - Полная поддержка (просмотр/распаковка/создание): 7z, FreeArc’s arc/wrc, sfx (7z and arc), Brotli br, bz2, gz, paq/lpaq/zpaq, pea, quad/balz/bcm, split, tar, upx, wim, zip, Zstandard zst. Чтение (просмотр/распаковка/test): tbz, Facebook’s Zstandard zst and tzst, gz, gzip, tgz, tpz, tar, zip, zipx, z01, smzip, arj, cab, chm, chi, chq, chw, hxs, hxi, hxr, hxq, hxw, lit, cpio, deb, lzh, lha, rar (and most recent rar 5 revision), r01, 00, rpm, z, taz, tz, iso, Java (jar, ear, war), pet, pup, pak, pk3, pk4, slp, [Content], xpi, wim, u3p, lzma86, lzma, udf, xar, Apple’s dmg, hfs, part1, split, swm, tpz, kmz, xz, txz, vhd, mslz, apm, mbr, fat, ntfs, exe, dll, sys, msi, msp, Open Office / Libre Office (ods, ots, odm, oth, oxt, odb, odf, odg, otg, odp, otp, odt, ott), gnm, Microsoft Office (doc, dot, xls, xlt, ppt, pps, pot, docx, dotx, xlsx, xltx), Flash (swf, flv), quad, balz, bcm, zpaq, paq8f, paq8jd, paq8l, paq8o, lpaq1, lpaq5, lpaq8, ace через плагин unace (закрытый исходный код), arc, wrc, 001, pea, cbz, cbr, cba, cb7, cbt и другие. "
echo -e "${BLUE}:: ${NC}Поддерживаемые форматы с шифрованием: 7Z, ZIP, ARC, PEA . Поддержка восстановления архивов: FreeArc (arc/wrc). Исходный код: Open Source (открыт) ; Языки программирования: Pascal ; Библиотеки: GTK, Qt ; Лицензия: LGPLv3 ; Приложение переведено на русский язык. Безопасность на первом месте: надежное шифрование, двухфакторная аутентификация, зашифрованный менеджер паролей и безопасное удаление. Мощное сжатие: использует технологии с открытым исходным кодом из проектов 7-Zip/p7zip, FreeArc, PAQ/ZPAQ, PEA, UPX, Brotli и Zstd. "
echo -e "${CYAN}:: ${NC}Установка PeaZip пакетов (peazip), (peazip-gtk2-bin) (peazip-qt-bin), проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/peazip.git), (https://aur.archlinux.org/peazip-gtk2-bin.git), (https://aur.archlinux.org/peazip-qt-bin.git) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! 👉👈 "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Установить PeaZip (peazip),          2 - Установить PeaZip (peazip-gtk2-bin),

    3 - *Установить PeaZip (peazip-qt-bin),   0 - Нет пропустить установку: " i_peazip  # sends right after the keypress; # отправляет сразу после нажатия клавиши
echo ''
   [[ "$i_peazip" =~ [^1230] ]]
do
    :
done
if [[ $i_peazip == 0 ]]; then
  echo ""
  echo " Установка утилит (пакетов) пропущена "
elif [[ $i_peazip == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) PeaZip (peazip) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) "
