#############################################

clear
echo -e "${MAGENTA}
  <<< Установка Рекомендованных программ — утилит (пакетов) для Archlinux 👨‍💻 >>> ${NC}"
# Installing Recommended utility programs (packages) for Archlinux
echo ""
echo -e "${YELLOW}==> Примечание! ${BOLD} *Для Arch Linux доступны рекомендованные программы (пакеты) из официальных репозиториев и пользовательского репозитория AUR (Arch User Repository). Думаю, что пользователь системы должен сам определять, что и для чего он должен устанавливать в свою систему, но все же должен (обязательно) дать несколько рекомендаций к установке определенного ПО, которые точно поможет вам при работе с Archlinux. ${NC}"
sleep 07
#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить HwDetect (hwdetect) — Инструмент для обнаружения событий изменения оборудования?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Скрипт обнаружения оборудования с загрузкой модулей и поддержкой 'mkinitcpio.conf/rc.conf'. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}HwDetect — это скрипт (консольная утилита с огромным количеством опций) обнаружения оборудования, который в основном используется для загрузки (перечисления) или вывода списка модулей ядра (для использования в mkinitcpio.conf), и заканчивая возможностью автоматического изменения rc.conf и mkinitcpio.conf . Сценарий использует информацию, экспортируемую подсистемой sysfs (https://en.wikipedia.org/wiki/Sysfs), используемой ядром Linux. Это отличается от многих других инструментов, которые запрашивают только оборудование и показывают необработанную информацию, оставляя пользователю задачу связать эту информацию с необходимыми драйверами. Таким образом, он информирует пользователя о том, какие модули ядра необходимы для управления оборудованием. Это отличает его от многих других инструментов, которые только опрашивают оборудование и отображают необработанную информацию, оставляя пользователю задачу сопоставить эту информацию с необходимыми драйверами. Этот проект Лицензируется под GPL-3.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://github.com/coolshou/HwDetect ; (https://archlinux.org/packages/extra/any/hwdetect/ ; https://gitlab.archlinux.org/archlinux/packaging/packages/hwdetect ; https://wiki.archlinux.org/title/Hwdetect). "
echo -e "${BLUE}:: ${NC}Примечание: Инструмент имеет специальный вывод для использования в /etc/mkinitcpio.conf. Если названия каких-либо модулей изменятся из-за того, что в новых ядрах установлены новые модули, или вы установите на свой компьютер новое оборудование, вам потребуется заново сгенерировать список модулей и обновить MODULES. "
echo -e "${CYAN}:: ${NC}Советы и рекомендации вы можете посмотреть на странице в ArchWiki: 'https://wiki.archlinux.org/title/Hwdetect' "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить пакет (hwdetect),    0 - Нет пропустить установку: " in_hwdetect  # sends right after the keypress; # отправляет сразу после нажатия клавиши
echo ''
   [[ "$in_hwdetect" =~ [^10] ]]
do
    :
done
if [[ $in_hwdetect == 0 ]]; then
  echo ""
  echo " Установка утилит (пакетов) пропущена "
elif [[ $in_hwdetect == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) HwDetect (hwdetect) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) для поддержки "
############ Зависимости ##############
sudo pacman -S --noconfirm --needed cryptsetup  # (необязательно) — для поддержки шифрования конфигурации mkinitcpio ;  Инструмент настройки пользовательского пространства для прозрачного шифрования блочных устройств с использованием dm-crypt ; https://archlinux.org/packages/core/x86_64/cryptsetup/ ; https://gitlab.com/cryptsetup/cryptsetup/ ; Обеспечивает: libcryptsetup.so=12-64 ; Конфликты: с mkinitcpio<38-1 ; 2025-06-26 07:15 UTC
sudo pacman -S --noconfirm --needed lvm2  # (необязательно) — для поддержки конфигурации lvm2 mkinitcpio ; Утилиты Logical Volume Manager 2 ; https://sourceware.org/lvm2/ ; https://archlinux.org/packages/core/x86_64/lvm2/ ; Конфликты: с lvm, mkinitcpio<38-1 ; 2025-07-31 20:31 UTC
sudo pacman -S --noconfirm --needed mdadm  # (необязательно) — для поддержки конфигурации raid mkinitcpio ; Инструмент для управления/мониторинга массивов md-устройств Linux, также известный как программный RAID ; https://archlinux.org/packages/core/x86_64/mdadm/ ; https://git.kernel.org/pub/scm/utils/mdadm ; Заменяет: raidtools ; Конфликты: с mkinitcpio<38-1 ; 2025-01-04 21:18 UTC
############# hwdetect ###############
sudo pacman -S --noconfirm --needed hwdetect  # Скрипт (консольная утилита) просмотр модулей ядра для устройств, обнаружения оборудования с загрузочными модулями и поддержкой mkinitcpio.conf / rc.conf ; Скрипт обнаружения оборудования с загрузкой модулей и mkinitcpio.conf ; https://archlinux.org/packages/extra/any/hwdetect/ ; https://archlinux.org/packages/extra/any/hwdetect/ ;
# pacman -S hwdetect --noconfirm  # Скрипт (консольная утилита) просмотр модулей ядра для устройств, обнаружения оборудования с загрузочными модулями и поддержкой mkinitcpio.conf / rc.conf
# sudo pacman -Rs hwdetect  # В случае возникновения ошибок при установке пакета
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
############# Справка ##############
# HwDetect (hwdetect)
# https://github.com/coolshou/HwDetect
# https://archlinux.org/packages/extra/any/hwdetect/
# https://gitlab.archlinux.org/archlinux/packaging/packages/hwdetect
# Hwdetect ArchWiki:
# https://wiki.archlinux.org/title/Hwdetect
# Запустите: hwdetect --help
# Для заполнения mkinitcpio.confMODULES можно использовать следующий метод .
# hwdetect --show-modules
