clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Audit (audit) — Утилиты системного администрирования?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Фреймворк аудита Linux предоставляет систему аудита, соответствующую стандарту CAPP ( Controlled Access Protection Profile ), которая надежно собирает информацию о любых событиях в системе, связанных (и не связанных) с безопасностью. Он может помочь вам отслеживать действия, выполняемые в системе. Профиль защиты контролируемого доступа (CAPP) — это профиль безопасности Common Criteria, разработанный Организацией безопасности информационных систем (ISSO). Он определяет набор функциональных и гарантийных требований к продуктам информационных технологий. Программное обеспечение и системы, соответствующие стандартам CAPP, обеспечивают контроль доступа , позволяющий устанавливать ограничения доступа для отдельных пользователей и объектов данных. Продукты, соответствующие стандартам CAPP, также предоставляют возможность аудита, регистрирующего события, связанные с безопасностью, происходящие в системе (https://en.wikipedia.org/wiki/Controlled_Access_Protection_Profile). ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Audit (auditd) — демон аудита Linux. Структура аудита работает, прослушивая события, сообщаемые ядром, и регистрируя их в файле журнала. auditd — это компонент пользовательского пространства системы аудита Linux. Он отвечает за запись записей аудита на диск. Просмотр журналов осуществляется с помощью утилит ausearch или aureport . Настройка системы аудита или загрузка правил выполняется с помощью утилиты auditctl . Во время запуска правила из /etc/audit/audit.rules считываются утилитой auditctl и загружаются в ядро. Кроме того, существует программа augenrules , которая считывает правила из /etc/audit/rules.d/ и компилирует их в файл audit.rules. Сам демон аудита имеет ряд параметров конфигурации, которые администратор может настроить. Они находятся в файле auditd.conf . Этот проект Лицензируется под GPL-2.0 или более поздняя версия, LGPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://github.com/linux-audit/audit-userspace ; (https://man.archlinux.org/man/auditd.8.en ; https://archlinux.org/packages/core/x86_64/audit/ ; https://github.com/ilpianista/arch-audit). "
echo -e "${BLUE}:: ${NC}Что это такое? Linux Audit Daemon - это среда, позволяющая проводить аудит событий в системе Linux. Используя мощную систему аудита возможно отслеживать многие типы событий для мониторинга и проверки системы, например: доступ к файлам; изменение прав на файлы; просмотр пользователей, изменивших конкретный файл; обнаружение несанкционированных изменений; мониторинг системных вызовов и функций; обнаружение аномалий, таких как сбои; мониторинг набора команд. Конфигурация выполняется с помощью двух файлов: auditd.conf - настройка самого демона, audit.rules - настройка правил, используемых средством auditctl. Примечание: auditctl - клиентский инструмент для настройки auditd. Файл auditd.conf настраивает демон аудита Linux (auditd) с акцентом на том, где и как он должен регистрировать события. Он также определяет, как работать с дисками, журналом повторов и количеством хранимых логов. Обычно стандартная конфигурация подходит для большинства систем. "
echo -e "${CYAN}:: ${NC}Чтобы настроить, какие именно события подвергать проверке, в структуре аудита используется файл правил с именем audit.rules. Активные правила можно просмотреть с помощью опции -l: 'auditctl -l'. Посетите auditctl страницу руководства, чтобы увидеть больше примеров аудита. Для получения информации о конкретных параметрах используйте auditctl --help. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_audit  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_audit" =~ [^10] ]]
do
    :
done
if [[ $in_audit == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_audit == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Audit (audit) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) для мониторинга "
############ Зависимости ##############
sudo pacman -S --noconfirm --needed libcap-ng  # Библиотека для Linux, упрощающая использование возможностей posix ; https://archlinux.org/packages/core/x86_64/libcap-ng/ ; https://people.redhat.com/sgrubb/libcap-ng/ ; Обеспечивает: libcap-ng.so=0-64, libdrop_ambient.so=0-64 ; 2024-12-22 12:38 UTC ;
sudo pacman -S --noconfirm --needed krb5  # Система сетевой аутентификации Kerberos ; https://archlinux.org/packages/core/x86_64/krb5/ ; https://web.mit.edu/kerberos/ ; Обеспечивает: libgssapi_krb5.so=2-64, libgssrpc.so=4-64, libk5crypto.so=3-64, libkadm5clnt_mit.so=12-64, libkadm5srv_mit.so=12-64 ; 28 июня 2025 г. 13:43 UTC
sudo pacman -S --noconfirm --needed libldap  # (необязательно) - для audispd-zos-remote ; Клиентские библиотеки облегченного протокола доступа к каталогам (LDAP) ; https://archlinux.org/packages/core/x86_64/libldap/ ; https://www.openldap.org/ ; 2025-07-16 18:19 UTC
############ audit ##############
sudo pacman -S --noconfirm --needed audit  # Компоненты пользовательского пространства структуры аудита ; https://people.redhat.com/sgrubb/audit ; https://archlinux.org/packages/core/x86_64/audit/ ; https://github.com/linux-audit/audit-userspace ; Обеспечивает: libaudit.so=1-64, libauparse.so=0-64 ; 2025-06-05 07:30 UTC
sudo pacman -S --noconfirm --needed lib32-audit  # Компоненты пользовательского пространства структуры аудита ; https://archlinux.org/packages/multilib/x86_64/lib32-audit/ ; https://github.com/linux-audit/audit-userspace ; Обеспечивает: libaudit.so=1-32 ; 2025-06-05 07:30 UTC
########### arch-audit ###############
sudo pacman -S --noconfirm --needed arch-audit  # Утилита типа pkg-audit, основанная на данных Arch Security Team ; https://gitlab.com/ilpianista/arch-audit ; https://archlinux.org/packages/extra/x86_64/arch-audit/ ; 2025-07-17 11:27 UTC
sudo pacman -S --noconfirm --needed arch-audit-gtk  # Уведомления об обновлениях безопасности Arch Linux ; https://github.com/kpcyrd/arch-audit-gtk ; https://archlinux.org/packages/extra/x86_64/arch-audit-gtk/ ; 2023-05-19 15:41 UTC
# sudo pacman -S --noconfirm --needed gnome-shell-extension-appindicator  # (необязательно) — поддержка gnome3 ; Поддержка AppIndicator/KStatusNotifierItem для оболочки GNOME ; https://archlinux.org/packages/extra/any/gnome-shell-extension-appindicator/ ; https://github.com/ubuntu/gnome-shell-extension-appindicator ; 2025-07-17 11:59 UTC
########## python-audit #############
sudo pacman -S --noconfirm --needed python-audit  # Компоненты пользовательского пространства фреймворка аудита — привязки Python ; https://github.com/linux-audit/audit-userspace ; https://archlinux.org/packages/core/x86_64/python-audit/ ; 2025-06-05 07:30 UTC
########## perf #############
sudo pacman -S --noconfirm --needed perf  # Инструмент аудита производительности ядра Linux ; https://archlinux.org/packages/extra/x86_64/perf/ ; https://www.kernel.org/ ; 2025-07-16 18:23 UTC
########## python-auditwheel #############
sudo pacman -S --noconfirm --needed python-auditwheel  #  (необязательно) ; Аудит и перемаркировка дисков Linux для разных дистрибутивов ; https://archlinux.org/packages/extra/any/python-auditwheel/ ; https://github.com/pypa/auditwheel ; 2025-06-14 18:23 UTC
  echo ""
  echo " Включить и запустить сервис auditd.service "
  echo " *Важно! После внесения изменений в /etc/audit/rules.d/audit.rules и /etc/audit/auditd.conf
  нужно ОБЯЗАТЕЛЬНО перезапустить сервис auditd.service "
sudo systemctl enable auditd.service  # Включите auditd демон, чтобы он мог запускаться во время загрузки
sudo systemctl start auditd.service  # запускает службу аудита (auditd) на Linux в системах на базе systemd
# sudo systemctl restart auditd  # Перезапустить службу после изменений в конфигурации или правилах
# sudo systemctl status auditd.service  # Чтобы проверить статус службы auditd
# sudo systemctl restart logrotate.service; systemctl restart auditd.service  # Перезапускаем службы logrotate и auditd
sleep 03
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
