clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Realtime process management (realtime-privileges) — Управление процессами в реальном времени?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Хотя многие современные процессоры достаточно производительны для одновременного воспроизведения дюжины видео- или аудиопотоков, всё равно существует вероятность, что другой поток перехватит процессор на полсекунды для выполнения другой задачи. Это приводит к кратковременным прерываниям аудио- или видеопотоков. Также возможна рассинхронизация видео- и аудиопотоков. Хотя это раздражает обычного слушателя музыки, для создателя контента, композитора или видеоредактора эта проблема гораздо серьёзнее, поскольку прерывает рабочий процесс. Решение — запускать процессы, чувствительные ко времени, в режиме реального времени. В Linux это означает переключение процесса на планировщик реального времени, например SCHED_RR, SCHED_FIFO. Описание этих планировщиков см. в sched (https://man.archlinux.org/man/sched). ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Группа пакетов realtime — дополнительные инструменты для изменения политик планирования. В Arch Linux системную, групповую и пользовательскую настройку можно выполнить с помощью PAM и systemd . Группа пакетов реального времени предоставляет дополнительные инструменты для изменения политик планирования IRQ (https://en.wikipedia.org/wiki/Interrupt_request) и процессов в реальном времени.   Этот проект Лицензируется под GPL3. ${NC}"
echo " Домашняя страница: https://archlinux.org/groups/x86_64/realtime/ ; (https://wiki.archlinux.org/index.php/Realtime_process_management ; https://archlinux.org/packages/extra/any/realtime-privileges/). "
echo -e "${CYAN}:: ${NC}Реальное время — это синоним процесса, способного выполняться без прерывания другими процессами. Однако, несмотря на это, циклы иногда могут прерываться. Возможной причиной может быть низкое энергопотребление или процесс с более высоким приоритетом. Для решения этой проблемы существует масштабирование качества реального времени. В данной статье рассматривается «мягкое » реальное время. «Жёсткое» реальное время обычно не столько желательно, сколько необходимо . В качестве примера можно привести автомобильную антиблокировочную систему тормозов (ABS). Её невозможно «отрисовать», и второго шанса не будет. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_privileges  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_privileges" =~ [^10] ]]
do
    :
done
if [[ $in_privileges == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_privileges == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Realtime process management (realtime-privileges) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
########### realtime-privileges #############
sudo pacman -S --noconfirm --needed realtime-privileges  # Привилегии в реальном времени для пользователей ; https://archlinux.org/packages/extra/any/realtime-privileges/ ; https://wiki.archlinux.org/index.php/Realtime_process_management ; https://archlinux.org/groups/x86_64/realtime/ ; Группы: pro-audio, realtime ; 2024-07-13 18:28 UTC
echo " Добавление пользователя в realtime группу "
sudo usermod -aG realtime $USER  # realtime group, добавление пользователя в realtime группу
# sudo pacman -Rcns realtime-privileges  # Удалить пакет "realtime-privileges"
  echo ""
  echo " Теперь вы можете убедится, что группа была добавлена в файл /etc/group "
sudo cat /etc/group | grep realtime
sleep 03
  echo " Проверка групп: Посмотрим к каким группам принадлежит текущий пользователь "
  groups  # Чтобы увидеть, к каким группам принадлежит текущий пользователь
sleep 05
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
