clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Plocate (plocate) — Альтернатива locate, более быстрая и совместимая с базой данных mlocate?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Со временем альтернативные реализации вытесняли друг друга: от slocate (безопасный locate), который показывал только файлы, доступные пользователю, до mlocate (объединяющий locate), который объединяет базы данных при каждом обновлении, что обеспечивает ускорение производительности, поскольку он может пропускать ранее проверенные файлы, до сегодняшнего plocate (постинг locate), который представляет собой locate, основанный на постинговых списках , использующий базу данных заранее и создающий на ее основе гораздо более быстрый (и меньший) индекс. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Plocate — Альтернатива locate, более быстрая и совместимая с базой данных mlocate, основанный на списках постинга, полностью заменяющий mlocate гораздо более быстрым (и компактным) индексом. Он подходит в качестве locate по умолчанию в вашей системе. plocate работает, создавая инвертированный индекс по триграммам (комбинациям из трёх байтов) в строках поиска, что позволяет быстро сузить набор кандидатов до очень короткого списка вместо линейного сканирования каждой записи. Практически все операции ввода-вывода выполняются асинхронно, используя io_uring, если он доступен (Linux 5.1+), что снижает влияние задержки поиска в системах без SSD. Как и mlocate и slocate, возвращаемый набор файлов зависит от пользователя, то есть пользователь увидит файл только в том случае, если find(1) выведет его (все каталоги от корня имеют права +rx). Этот проект Лицензируется Только GPL-2.0, GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://plocate.sesse.net/ ; (https://github.com/loveencounterflow/plocate ; https://www.gnu.org/software/findutils/ ; https://archlinux.org/packages/extra/x86_64/plocate/ ; https://archlinux.org/packages/core/x86_64/findutils/). "
echo -e "${BLUE}:: ${NC}locate — распространённый инструмент Unix для быстрого поиска файлов по имени. Он обеспечивает более высокую скорость по сравнению с инструментом find , поскольку выполняет поиск в предварительно созданном файле базы данных, а не непосредственно в файловой системе . Недостаток такого подхода заключается в том, что изменения, внесённые после создания файла базы данных, не могут быть обнаружены программой locate. Эту проблему можно минимизировать, планируя обновления базы данных. "
echo -e "${CYAN}:: ${NC}Findutils (Утилиты GNU Find) — это базовые утилиты поиска в каталогах операционной системы GNU. Эти программы обычно используются совместно с другими программами, предоставляя другим командам модульные и мощные возможности поиска в каталогах и файлов. *В комплект поставки входят следующие инструменты: find - поиск файлов в иерархии каталогов. locate (plocate) - вывести список файлов в базах данных, соответствующих шаблону. updatedb - обновить базу данных имен файлов. xargs — создание и выполнение командных строк из стандартного ввода. *Программа поиска просматривает дерево каталогов, чтобы найти файл или группу файлов. Она просматривает дерево каталогов и сообщает обо всех найденных файлах, соответствующих заданным пользователем параметрам. Программа поиска обладает мощными поисковыми функциями. Программа locate сканирует одну или несколько баз данных имён файлов и отображает любые совпадения. Это можно использовать для очень быстрого поиска, если файл присутствовал в базе данных на момент последнего обновления. Программа updatedb обновляет базу данных имён файлов, используемую программой locate . База данных имён файлов содержит списки файлов, которые находились в определённых каталогах на момент последнего обновления баз данных. Обычно это выполняется каждую ночь системным демоном cron. Программа xargs формирует и выполняет командные строки, собирая аргументы, считываемые из стандартного ввода. Чаще всего эти аргументы представляют собой списки имён файлов, сгенерированные find . "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
