############ Зависимости ##############
sudo pacman -S --noconfirm --needed findutils  # Утилиты GNU для поиска файлов ; https://archlinux.org/packages/core/x86_64/findutils/ ; https://www.gnu.org/software/findutils/ ; 2025-07-04 13:52 UTC
######### plocate #########
sudo pacman -S --noconfirm --needed plocate  # Альтернатива locate, более быстрая и совместимая с базой данных mlocate ; https://archlinux.org/packages/extra/x86_64/plocate/ ; https://plocate.sesse.net/ ; Заменяет: mlocate ; Конфликты: mlocate ; 2024-11-27 18:36 UTC
### Команду locate (из пакета mlocate или нового пакета plocate ), которая быстро ищет файлы и каталоги по их именам. Эта команда использует базу данных, созданную командой updatedb (которую следует запускать периодически, например, включив службу plocate-updatedb.timer для plocate).
  echo ""
  echo " Создайть новую системную группу (plocate) "
### sudo addgroup [параметры] имя_группы ; sudo groupadd {{group_name}}
# groupadd plocate
### Создайте новую системную группу:
# sudo groupadd {{[-r|--system]}} {{group_name}}
# Создайте новую группу с определенным идентификатором группы:
# sudo groupadd {{[-g|--gid]}} {{id}} {{group_name}}
sudo groupadd --system plocate
  echo ""
  echo " Добавить службу plocate-updatedb.timer в автозагрузку "
  echo " Команда в Linux активирует таймер (timer unit) для обновления базы данных утилиты updatedb "
# sudo systemctl start plocate-updatedb.timer
sudo systemctl enable plocate-updatedb.timer  # systemctl правление системой systemd и менеджером служб ; systemctl [ПАРАМЕТРЫ...] КОМАНДА [ЕДИНИЦА...]
# sudo systemctl status plocate-updatedb.timer
### Команда systemctl enable plocate-updatedb.timer в Linux активирует таймер (timer unit) для обновления базы данных утилиты updatedb. Это часть механизма systemd, который позволяет запускать задачи по расписанию, например, обновлять системные базы данных.
# Файл таймера — /usr/lib/systemd/system/plocate-updatedb.timer. В нём определены опции, которые указывают, когда запускать таймер, и сервис, который он вызывает:
# OnCalendar=daily — таймер запускается каждый день.
# Unit=plocate-updatedb.service — сервис, который нужно запустить, — это сервис, определённый в /usr/lib/systemd/system/plocate-updatedb.service.
# Persistent=true — если задача может быть выполнена из-за отключения системы, таймер сработает немедленно.
### Принцип работы: Таймер запускается автоматически — он запускается при загрузке системы. Если система не работает, systemd автоматически запускает пропущенные таймеры после восстановления системы (настраивается параметром Persistent=).
###################
  echo ""
  echo " Создайть базу данных (файл индекса) (plocate) "
### Перед первым использованием создайте его базу данных (файл индекса)
# При первом запуске updatedb программа сканирует всю файловую систему, и это может занять некоторое время. Последующие запуски должны выполняться гораздо быстрее. Если я хочу plocate найти файл, созданный после запуска системы, мне нужно sudo updatedb сначала запустить  с помощью следующей команды:
sudo updatedb  # updatedb — это утилита, которая поддерживает базу данных путей к файлам. Она используется командой locate , которая эффективно ищет в ней имена файлов. Поэтому базу данных необходимо обновлять время от времени или при запуске компьютера. Утилита updatedb отвечает за создание и обновление базы данных, что может быть ресурсоёмким при большом количестве файлов. Поэтому может потребоваться её отключение или полное удаление с компьютера. Обычно  команда updatedb связана с другим пакетом, предоставляющим  команду locate , например, GNU  findutils , mlocate или  plocate . Поэтому, чтобы удалить её, сначала нужно найти соответствующий пакет.
### Arch Linux и Manjaro:
# В Arch Linux и Manjaro мы можем использовать pacman для поиска связанного пакета updatedb и эффективного удаления его из системы:
# $ package=$(pacman -Qo /usr/bin/updatedb | cut -d ' ' -f 5) \
# && sudo pacman -Rns "$package"
# Команда находит пакет, связанный с  updatedb , извлекает имя пакета, а затем удаляет его из системы с помощью ключей -Rns .
# Отключить updatedb:
# В некоторых случаях необходимо сохранить пакет, связанный с updatedb . Поэтому можно просто отключить соответствующий ему таймер systemd :
# $ sudo systemctl disable plocate-updatedb.timer
# Removed "/etc/systemd/system/timers.target.wants/plocate-updatedb.timer".
# В качестве альтернативы мы также можем отключить  updatedb в его конфигурационном файле:
# $ sudo sed -i 's/\(PRUNE_BIND_MOUNTS\)="yes"/\1="no"/' /etc/updatedb.conf
# После этого перезапускаем службу cron , чтобы изменения вступили в силу:
# $ sudo systemctl restart cron
#################################
  echo ""
  echo " Посмотрите информацию о версии (plocate) "
# plocate --version  # Показать версию приложения
sudo pacman -Q plocate  # Показать версию приложения
