############# Справка ##############
# Plocate (plocate):
# https://plocate.sesse.net/plocate.1.html
# https://wiki.archlinux.org/title/Locate
# Перед использованием plocate(1) необходимо создать базу данных. Это делается с помощью команды updatedb (https://man.archlinux.org/man/updatedb.8) , которая (как следует из названия) обновляет базу данных. plocate содержит plocate-updatedb.timer модуль, который ежедневно запускает обновление базы данных и активируется при установке. Запустите его вручную, если хотите использовать его перед перезагрузкой. Вы также можете вручную запустить updatedb от имени root в любое время. updatedb - обновление базы данных для plocate (https://man.archlinux.org/man/updatedb.conf.5).
# Для экономии времени updatedb можно настроить (и по умолчанию это делается) на игнорирование определённых файловых систем и путей, отредактировав файл /etc/updatedb.conf. Файл updatedb.conf (https://man.archlinux.org/man/updatedb.conf.5) описывает семантику этого файла. Стоит отметить, что в конфигурации по умолчанию ( PRUNEPATHS) игнорируются пути /mediaи /mnt, поэтому locate может не обнаружить файлы на внешних устройствах.
### Теперь используйте plocateтак же, как и locate. Найдите файл с помощью plocate:
# locate <MY_FILE.EXT>
# Заменяем MY_FILE.EXTна файл, который вы хотите найти.
# Дополнительные параметры, такие как игнорирование регистра, поиск по регулярным выражениям и т. д., см. в справке и на странице руководства инструмента.
### Примеры Findutils (Утилиты GNU Find):
# Вот пример операции, которая позволяет сделать все HTML-файлы в подкаталоге htdocs доступными для чтения всем пользователям с помощью find и xargs. Это типичный пример использования find и xargs с другими утилитами для обеспечения мощных возможностей обхода каталогов.
# find htdocs -name '*.html' -print0 | xargs -0 chmod a+r
# Также доступна онлайн -версия документации , но учтите, что она не всегда полностью актуальна (https://www.gnu.org/software/findutils/manual/find.html).
### Поиск неисправностей Plocate (plocate):
# Для Btrfs:
# Конфигурация по умолчанию запрещает включение файловых систем Btrfs в результаты. Чтобы разрешить включение точек монтирования Btrfs, добавьте:
# /etc/updatedb.conf
# PRUNE_BIND_MOUNTS = "no"
# Обратите внимание, что это также означает, что будут включены и другие точки монтирования. Если вам нужно исключить эти точки монтирования, PRUNEPATHS , можно использовать настройку в том же файле конфигурации.
### К сожалению, по умолчанию он прекрасно работает с файловой системой BTRFS и ее подтомами (см., например, эту ошибку https://bugs.launchpad.net/ubuntu/+source/plocate/+bug/1968190), что в основном приводит к пустым результатам для всех поисков.
# К счастью, решение довольно простое:
# # замените PRUNE_BIND_MOUNTS = “yes” на PRUNE_BIND_MOUNTS = “no”
# сохраните, выйдите и перезапустите updatedb
# Затем вы можете воспользоваться результатами поиска locate.
