echo ""
echo -e "${BLUE}:: ${NC}Установить Pacman Log Viewer (pacmanlogviewer) — Чтения (просмотр) лог-файлов Pacman?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Эта утилита работает только в Archlinux и производных и требует наличия инструментария Qt5 или выше. Будучи средством просмотра журналов для стандартного менеджера пакетов Arch Linux, Pacman, приложение разработано для работы только с Arch Linux или операционной системой на его основе, например, Chakra. Однако оно должно работать и с множеством других производных Arch Linux, поддерживая 32- и 64-разрядные компьютерные платформы. Убедитесь, что установлены наборы графических инструментов Qt4 или Qt5. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Pacman Log Viewer — удобное Qt графическое приложение для просмотра журнала работы Pacman. Pacman Log Viewer — это инструмент для просмотра журнала Pacman, в частности, он отображает список установленных, удалённых и обновлённых пакетов, позволяя фильтровать их по имени и/или дате. Чаще всего он используется после проблемного обновления, когда затронуто много файлов, а внесённые изменения не так важны. Приложение Pacman Log Viewer позволяет просматривать список установленных, обновлённых и удалённых пакетов, позволяя пользователю фильтровать их по дате, имени или по дате и имени одновременно. Оно предоставляет пользователю современный, простой и интуитивно понятный графический интерфейс без лишних кнопок и панелей инструментов. Вы можете выполнять только поиск пакетов, перезагружать журнал по умолчанию, загружать пользовательский журнал, а также добавлять дополнительные фильтры. Этот проект Лицензируется под GNU General Public License version 3.0 (GPLv3). ${NC}"
echo " Домашняя страница: https://github.com/gcala/pacmanlogviewer/ ; (https://archlinux.org/packages/extra/x86_64/pacmanlogviewer/). "
echo -e "${BLUE}:: ${NC}Pacman — система управления пакетами сочетающая в себе простой формат двоичных пакетов и лёгкую в использовании систему сборки. Целью менеджера пакетов Pacman является предоставление возможности лёгкого управления пакетами, вне зависимости от того откуда они взяты, из официальных репозиториев или собраны самостоятельно. Пакетный менеджер Pacman является одной из особенностей дистрибутива Arch Linux. Pacman поддерживает систему в актуальном состоянии синхронизируя список пакетов с сервером. Пакетный менеджер способен сам найти зависимости, автоматически загрузить и установить необходимые пакеты, вывод Pacman сохраняется в файле: /var/log/pacman.log . Лог обычно просматривают в текстовом редакторе, Pacman Log Viewer предоставляет пользователю более наглядный и удобный способ просмотра вывода. "
echo -e "${CYAN}:: ${NC}Если вы задаетесь вопросом, полезен ли вам этот инструмент, стоит отметить, что распространенный случай его использования — после проблемного обновления, когда ваша система ведет себя странно, и вы понятия не имеете, что происходит. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
