clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Zeitgeist (zeitgeist) — Служба регистрации действий и событий пользователей?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Zeitgeist — это основной движок и логика журнала активности GNOME , который в настоящее время рассматривается как одно из основных средств просмотра и управления действиями в GNOME. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Zeitgeist — служба ведения журнала пользовательской активности, системный сервис регистрирующий пользовательские действия и события, от открытых файлов до посещаемых веб-сайтов, почтовых сообщений и разговоров в клиентах обмена сообщениями. Пакет Zeitgeist , включающий демон и datahub. Демон получает метаданные из источников данных и предоставляет их приложениям через D-Bus. Datahub предоставляет пассивные плагины для добавления событий в Zeitgeist . Сервис Zeitgeist (zeitgeist-daemon) предназначен для регистрация всей деятельности пользователя и организации её в хронологическом порядке. Это позволяет быстро найти необходимую информацию и восстановить общую картин того что делал пользователь в заданный промежуток времени. После обработки алгоритмами ассоциации сохранённые данные становятся доступны для использования сторонними приложениями. Чтобы настроить то, что регистрирует Zeitgeist, установим activity-log-manager , который предоставляет графический пользовательский интерфейс, с помощью которого можно отфильтровать определенные папки, типы файлов и приложения. Для мониторинга и проверки журнала Zeitgeist на низком уровне установим zeitgeist-explorer , который предоставляет графический пользовательский интерфейс, в котором вы можете просматривать регистрируемые события в режиме реального времени, как и Wireshark. Этот проект Лицензируется под GPL2, LGPL, BSD-3-Clause ИЛИ CC-BY-3.0, GPL-3.0 или более поздняя версия, LGPL-2.1 или более поздняя версия, LGPL-3.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://launchpad.net/zeitgeist/ ; (https://launchpad.net/activity-log-manager ; https://launchpad.net/zeitgeist-explorer ; https://github.com/dhananjaysathe/zeitgeist-explorer ; https://archlinux.org/packages/extra/x86_64/zeitgeist/ ; https://archlinux.org/packages/extra/x86_64/activity-log-manager/ ; https://archlinux.org/packages/extra/any/zeitgeist-explorer/). "
echo -e "${BLUE}:: ${NC}Activity Log Manager — простой Vala / GTK (Libgee) графический интерфейс (GUI) позволяющий управлять файлам службы пользовательской активности Zeitgeist (zeitgeist-daemon / zeitgeist-datahub). Activity Log Manager (ранее GNOME Activity Journal) позволяет легко контролировать данные регистрируемые Zeitgeist, поддерживает создание "Чёрного списка" в соответствии с несколькими критериями (приложения и/или файлы), сервис можно остановить и запустить, а также удалить журнал по выбранным параметрам. "
echo -e "${CYAN}:: ${NC}Zeitgeist Explorer — простой Python / GTK (PyGObject) графический интерфейс (GUI) для доступа к файлам службы пользовательской активности Zeitgeist (zeitgeist-daemon / zeitgeist-datahub). Графический интерфейс для мониторинга и проверки журнала Zeitgeist на низком уровне (непосредственно просмотр событий и предметов). Zeitgeist Explorer — это инструмент для мониторинга и изучения событий, зарегистрированных Zeitgeist. В режиме мониторинга он отображает зарегистрированные события в реальном времени, как Wireshark. В режиме исследования он может извлекать уже зарегистрированные события для определенного шаблона. Zeitgeist Explorer предоставляет информацию по вкладкам, в первой (Monitor Events) отображается мониторинг текущих событий, вторая вкладка (Applications) выводит сортированным по дате списком данные по приложениям. Сервис можно остановить и запустить, а также удалить весь журнал для отдельного приложения и/или только выбранное событие. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_zeitgeist  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_zeitgeist" =~ [^10] ]]
do
    :
done
if [[ $in_zeitgeist == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_zeitgeist == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Zeitgeist (zeitgeist) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
########### zeitgeist ############
sudo pacman -S --noconfirm --needed zeitgeist  # Служба регистрации действий и событий пользователей ; https://archlinux.org/packages/extra/x86_64/zeitgeist/ ; https://launchpad.net/zeitgeist/ ; Обеспечивает: zeitgeist-datahub ; Заменяет: zeitgeist-datahub ; Конфликты: zeitgeist-datahub ; 2024-12-22 12:59 UTC
  echo ""
  echo " Установка дополнительных утилит (пакетов) графического интерфейса (GUI) "
############ Зависимости ##############
########### activity-log-manager ############
sudo pacman -S --noconfirm --needed activity-log-manager  # Графический пользовательский интерфейс, позволяющий легко контролировать то, что регистрируется Zeitgeist ; https://archlinux.org/packages/extra/x86_64/activity-log-manager/ ; https://launchpad.net/activity-log-manager ; 2024-09-06 18:45 UTC
############# zeitgeist-explorer ##########
sudo pacman -S --noconfirm --needed zeitgeist-explorer  # Графический интерфейс для мониторинга и проверки журнала Zeitgeist на низком уровне ; https://archlinux.org/packages/extra/any/zeitgeist-explorer/ ; https://launchpad.net/zeitgeist-explorer ; https://github.com/dhananjaysathe/zeitgeist-explorer ; 2024-12-22 13:44 UTC
  echo ""
  echo " Посмотрите информацию о версии (zeitgeist) "
# zeitgeist --version  # Показать версию приложения
sudo pacman -Q zeitgeist  #  Показать версию приложения
sudo pacman -Q zeitgeist-explorer  #  Показать версию приложения
sudo pacman -Q activity-log-manager  #  Показать версию приложения
sleep 05
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
