clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Gnome Logs (или просто Logs)(Журналы) (gnome-logs) — Просмотр логов (Просмотр подробной информации о событиях в системе)?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *В Linux логи (файлы с записями о событиях в системе) можно просматривать с помощью стандартных команд или специализированных инструментов. Логи обычно хранятся в каталоге /var/log/. В этом каталоге находятся файлы логов для различных системных компонентов и приложений. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Logs (Журналы) — небольшое C++ / GTK / GNOME графическое приложение для просмотра и анализа журнала SystemD (systemd journal), графический интерфейс (GUI) для консольной утилиты journalctl. Программа позволяет сделать выборку по событиям (категориям). Доступны следующие категории: Важные, Все, Приложения, Система, Безопасность и Оборудование. Поддерживается поиск по событиям. Logs выводит сообщения записанные в журнал после последней загрузки системы, количество выводимых сообщений зависит от прав доступа. Обычные пользователи "по умолчанию" могут просматривать ограниченный набор записей журнала, обычно собственные журналы и журналы приложений. Пользователи с правами администратора могут просматривать более подробные журналы, к примеру журналы ядра и журналы других пользователей. Logs (gnome-logs) позволяет фильтровать записи по датам, поддерживается поиск по событиям, для управления используется мышь и/или клавиатурные сочетания. Приложение является частью проекта GNOME (Gnome Application). Этот проект Лицензируется под GPL. ${NC}"
echo " Домашняя страница: https://apps.gnome.org/Logs ; (https://wiki.gnome.org/Apps/Logs ; https://archlinux.org/packages/extra/x86_64/gnome-logs/). "
echo -e "${BLUE}:: ${NC}*journalctl — стандартная консольная утилита для просмотра и анализа журнала SystemD (systemd journal), системных данных и данных приложений. С помощью дополнительных опций можно осуществлять фильтрацию данных и быстро извлекать нужную информацию. *SystemD — подсистема инициализации и управления службами GNU Linux систем, в 2000-е годы фактически вытеснившая традиционную подсистем init (initialization / инициация). Основной особенностью является интенсивное распараллеливание запуска служб в процессе загрузки систем, что позволяет существенно ускорить запуск операционной системы. Централизованный подход к журналированию используемый SystemD, а также благодаря автоматической записи подробных метаданных, удалось добиться большой гибкости и удобства. Все логи находятся в одном месте, они индексируются и структурируются, что позволяет легко получить к ним доступ. "
echo -e "${CYAN}:: ${NC}Пользовательский интерфейс Logs выполнен в соответствии с концепцией минимализма, управляющие элементы размещены на заголовке окна. В левой части окна расположены категории, в правой части окна выводится с список событий. Кликом по выбранному событию можно просмотреть дополнительную информацию о нём (в всплывающем уведомлении). "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_logs  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_logs" =~ [^10] ]]
do
    :
done
if [[ $in_logs == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_logs == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Gnome Logs (logs) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
######### gnome-logs ##########
sudo pacman -S --noconfirm --needed gnome-logs  # Просмотрщик журналов для журнала systemd ; https://archlinux.org/packages/extra/x86_64/gnome-logs/ ; https://apps.gnome.org/Logs ; https://wiki.gnome.org/Apps/Logs ; Группы: gnome ; 2025-07-24 17:10 UTC
  echo ""
  echo " Посмотрите информацию о версии (gnome-logs) "
sudo pacman -Q gnome-logs  #  Показать версию приложения
sleep 03
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
