echo -e "${YELLOW}==> Примечание! ${BOLD} *pacman.conf — файл конфигурации менеджера пакетов pacman. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Pace — Графический редактор /etc/pacman.conf , в основном для редактирования репозиториев (добавление, удаление) и т.д... Этот проект Лицензируется под GPL3. ${NC}"
echo " Домашняя страница: https://gitlab.com/softwareperonista/pace ; (https://aur.archlinux.org/packages/pace). "
echo -e "${BLUE}:: ${NC}Pacman — это менеджер пакетов для дистрибутивов на базе Arch Linux (например, Arch Linux, Manjaro, ArcoLinux, Artix Linux, Garuda Linux, ArcoLinux, Archlabs Linux и др.). Он устанавливает, удаляет, обновляет и выполняет любые другие операции с вашими пакетами. Это очень мощный менеджер пакетов. Помощники AUR, такие как 'yay', также используют Pacman для установки и других связанных операций. "
echo -e "${CYAN}:: ${NC}Pacman, используя libalpm (https://pacman.archlinux.page/libalpm.3.html) , будет пытаться прочитать pacman.conf при каждом запуске. Этот файл конфигурации разделён на разделы, или репозитории. Каждый раздел определяет репозиторий пакетов, который pacman может использовать при поиске пакетов в режиме --sync . Исключением является раздел options, в котором определяются глобальные параметры. "
echo -e "${CYAN}:: ${NC}Установка Pace (pace) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/pace.git), (https://aur.archlinux.org/packages/pace) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
