#sudo pacman -S --noconfirm --needed diffutils  # (необязательно) – поддержка предварительного просмотра различий ; Утилиты, используемые для создания файлов исправлений ; https://archlinux.org/packages/core/x86_64/diffutils/ ; https://www.gnu.org/software/diffutils ; 2025-04-27 21:12 UTC
