### Пояснения: Первый столбец: Строка TOTAL - итоговые данные, которые учитывают все сжатые и не сжатые файлы и разные алгоритмы (если такие имеются). Строка none - данные, которые не были сжаты. Далее отображаются все использованные алгоритмы (в данном случае - zstd). Второй столбец показывает данные в процентах. Третий столбец отображает фактически использованное место на диске/разделе. Четвертый столбец показывает данные без сжатия. Пятый - видимый размер файла, тот, который зачастую отображается в системе.
