### DMRAID (Device Mapper RAID) — это утилита для работы с RAID-массивами, созданными на основе встроенных программных RAID-контроллеров (так называемых «Fake RAID» или «BIOS RAID»). Программа поддерживает обнаружение устройств RAID, активацию наборов RAID, создание, удаление, перестройку и отображение свойств метаданных ATARAID/DDF1. Однако по некоторым причинам DMRAID не получил широкого признания и остаётся экспериментальным инструментом для специфических сценариев, связанных с использованием Fake RAID в домашних или малых офисных условиях.
