### Dmidecode выдаёт информацию об оборудовании вашей системы, описанную в BIOS, в соответствии со стандартом SMBIOS / DMI (см. пример вывода ). Эта информация обычно включает производителя системы, название модели, серийный номер, версию BIOS, инвентарную метку, а также множество других данных, важность и достоверность которых варьируется в зависимости от производителя. Часто сюда входит информация об использовании процессорных разъёмов, слотов расширения (например, AGP, PCI, ISA) и слотов для модулей памяти, а также список портов ввода-вывода (например, последовательных, параллельных, USB).
