### Aircrack- ng — это полный набор инструментов для оценки безопасности сетей WiFi. Основное внимание уделяется различным областям безопасности Wi-Fi (https://www.aircrack-ng.org/). Aircrack-ng — набор консольных приложений предназначенный для обнаружения беспроводных сетей, перехвата передаваемого через беспроводные сети трафика, аудита WEP и WPA/WPA2-PSK ключей шифрования, работает с любыми беспроводными сетевыми адаптерами драйвер которых поддерживает режим мониторинга.
# yay -S airoscript-ng --noconfirm  # Графический интерфейс, предназначенный в основном для aircrack-ng. Автоматизирует взлом WEP и WPA ; https://aur.archlinux.org/packages/airoscript-ng ; https://aur.archlinux.org/airoscript-ng.git (только для чтения, нажмите, чтобы скопировать) ; https://code.google.com/p/airoscript/ ; https://zenway.ru/page/airoscript-ng ; 28 октября 2016 г. 12:50 (UTC)
### Airoscript-ng предоставляет удобный интерфейс для использования большинства функциональных возможностей Aircrack-ng, позволяя существенно сократить время исключив необходимость написания команд. Airoscript-ng также обеспечивает комплексный способ создания отчётов безопасности, которые способны понять даже неспециалисты, можно расширять функциональные возможности с помощью дополнительных плагинов (например с помощью плагина wkhtml2pdf отчёт можно сохранить в формате PDF). Опционально Airoscript-ng поддерживает графический режим (GUI / Front-end), сделанный в виде zenity (zenity-gtk2) диалогов (аналогичных текстовым), но весь процесс выполняется в терминале, могут использоваться Xterm, Urxvt, Gnome-Terminal или GNU Screen, запускается графический режим командой:
# Для работы Airoscript-ng требуются права администратора (root).
# sudo airoscript-ng -pzenity
