clear
echo -e "${MAGENTA}
  <<< Установка Редактора меню программ (пакетов) в Archlinux 📋 >>> ${NC}"
# Installing the program (package) menu Editor in Archlinux
#clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Alacarte (alacarte) — Редактор меню?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Alacarte создан в соответствии со спецификацией freedesktop.org и должен работать в любой графической среде, поддерживающей эту спецификацию. Если подумать, наши среды рабочего стола Linux довольно умны. В то время как Windows просто создаёт новую папку для только что установленной программы в меню «Пуск», среда рабочего стола Linux автоматически распределяет все установленные приложения по разным категориям. Таким образом, если есть приложение, которое активно использует Интернет, оно, скорее всего, будет в категории «Интернет». ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Alacarte — простой в использовании оконный редактор меню, разрабатываемый в рамках проекта Gnome, позволяющий внести изменения в команду запуска приложения, поменять иконку (при клике по старой), добавить/изменить примечание, пересортировать программы по категориям, как хочется пользователю. Используя пункт «Новый элемент» — есть возможность добавить программу (или скрипт), которой нет в меню. Программа распространяется под свободной LGPL лицензией, и полностью русифицирована, что в полной мере позволяет наслаждаться с одной стороны простотой, а с другой таким незаменимым функционалом. Этот проект Лицензируется под LGPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://gitlab.gnome.org/GNOME/alacarte ; (https://www.archlinux.org/packages/extra/any/alacarte/ ; https://archlinux.org/packages/extra/any/alacarte/). "
echo -e "${BLUE}:: ${NC}*Изменение пунктов системного меню с помощью Alacarte: Одно из главных преимуществ Alacarte заключается в том, что в нём нет абсолютно ничего лишнего, и это становится очевидным сразу после запуска приложения. В левой части окна вы увидите панель со всеми доступными категориями и подкатегориями, которые существуют на данный момент. Вы не можете ничего сделать с категориями на левой панели, кроме как переключаться между ними, но если вы нажмете на самую верхнюю суперкатегорию «Приложения», то сможете менять категории в основной области окна. Вы можете добавить категорию в ту категорию, в которой находитесь в данный момент, с помощью кнопки «Новое меню», кнопка «Свойства» предназначена для редактирования, а кнопка «Удалить», конечно же, для удаления. "
echo -e "${CYAN}:: ${NC}Для редактирования отдельных приложений, относящихся к каждой категории, используйте кнопки «Создать элемент», «Свойства» и «Удалить». При редактировании ярлыка Alacarte запросит у вас имя и команду, а также необязательный комментарий. Командой может быть как имя приложения, так и путь к исполняемому файлу программы. Если ввести в поле команды только имя приложения, это сработает только в том случае, если в /usr/bin есть исполняемый файл с таким именем. Не забывайте, что вы также можете изменить значок ярлыка на любое другое изображение. Иногда изображение меняется само по себе, когда вы вводите имя исполняемого файла в текстовом поле команды. Конечно, вы можете отредактировать и некоторые другие параметры. Вы также можете скрыть пункты, чтобы они существовали в Alacarte, но не отображались в меню. Вы также можете перемещать пункты вверх или вниз в меню, если ваша оболочка не сортирует список по алфавиту. И последнее, но не менее важное: есть кнопка «Отменить», которая позволяет отменить внесённые изменения. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_alacarte  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_alacarte" =~ [^10] ]]
do
    :
done
if [[ $in_alacarte == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_alacarte == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Alacarte (alacarte) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
############ alacarte ##############
sudo pacman -S --noconfirm --needed alacarte  # Редактор меню для gnome ; https://archlinux.org/packages/extra/any/alacarte/ ; https://gitlab.gnome.org/GNOME/alacarte ; 2025-04-26 23:00 UTC
  echo ""
  echo " Посмотрите информацию о версии (alacarte) "
sudo pacman -Q alacarte  #  Показать версию приложения
sleep 03
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
#########

clear
echo ""
echo -e "${BLUE}:: ${NC}Установить MenuLibre (menulibre) — Редактор меню?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Удобный инструмент для редактирования меню приложений. MenuLibre — продвинутый редактор меню, совместимый с FreeDesktop.org. Все поля, указанные в спецификациях FreeDesktop.org Desktop Entry и Menu, доступны для быстрого обновления. Кроме того, MenuLibre предоставляет редактор действий запуска, используемых такими приложениями, как Unity и Plank. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}MenuLibre — удобная Python / GTK графическая утилита для редактирования меню приложений. MenuLibre — программа для редактирования главного меню среды рабочего стола. Поддерживается Unity, Gnome, XFCE, LXDE, предоставляя несколько дополнительных возможностей не имеющихся в стандартных для окружений "Редакторах меню" (те которые их имеют и сторонних). С помощью MenuLibre вы можете отредактировать любую кнопку запуска, которая доступна в главном меню вашей среды рабочего стола, также можно добавлять свои кнопки. Для каждой кнопки можно задать имя, указать команду запуска, иконку, рабочий каталог, а также некоторые базовые опции запуска (например, запуск в термирнале). Также вы можете добавить или удалить категории, в которых будет доступна данная кнопка. Программа полностью переведена на русский язык. Автор проекта: Sean Davis. Этот проект Лицензируется под GPL3.0 . ${NC}"
echo " Домашняя страница: https://github.com/bluesabre/menulibre ; (https://aur.archlinux.org/packages/menulibre). "
echo -e "${BLUE}:: ${NC}Функции: Красивый интерфейс, работающий на базе последней версии GTK+. Создавайте новые лаунчеры или изменяйте существующие с полным контролем общих настроек и доступом к расширенным настройкам. Добавление, удаление и настройка действий на рабочем столе: мощные сочетания клавиш, используемые в Unity, Xfce и Pantheon. Легко переставляйте пункты меню в соответствии с вашими потребностями. "
echo -e "${CYAN}:: ${NC}Установка MenuLibre (menulibre) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/menulibre.git), (https://aur.archlinux.org/packages/menulibre) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_menulibre  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_menulibre" =~ [^10] ]]
do
    :
done
if [[ $in_menulibre == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_menulibre == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) MenuLibre (menulibre) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
