echo ""
echo -e "${BLUE}:: ${NC}Установить Midnight Commander (mc) - Консольный файловый менеджер?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Midnight Commander способен составить очень серьезную конкуренцию любому файловому менеджеру с помощью своей легковесности и неприхотливости к системным ресурсам. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Midnight Commander — это текстовый консольный двухпанельный файловый менеджер написанный специально для Unix-подобных систем, напоминающий Norton Commander, и ничуть не уступающий последнему в популярности. Он поставляется со всеми современными дистрибутивами Linux. Полное название программы: GNU Midnight Commander (миднайт-командер). Сокращенное название: MC. Изначально программа называлась: Mouseless Commander. Исходный код: Open Source (открыт); Языки программирования: C; Приложение переведено на русский язык. Этот проект Лицензируется под GNU GPL-3.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://midnight-commander.org/ ; (https://archlinux.org/packages/extra/x86_64/mc/). "
echo -e "${BLUE}:: ${BOLD}MC поддерживает все основные операции с файлами: копирование, перемещение, архивация, изменение прав доступа, создание ссылок, каталогов и другие. MC может работать с файлами на удаленных системах посредством FTP и SSH. Midnight Commander поддерживает работу с архивами, имеет встроенный быстрый поиск файлов, включая поиск по содержимому файлов. В Midnight Commander встроен текстовый редактор файлов с подсветкой синтаксиса — MCEdit. MC написан с использованием библиотеки NCurses, что позволяет отображать всю информацию о папках и файлах, представленных в системе в понятной и удобной форме. Подсветка имен файлов в зависимости от их типа (архивы розовым, исполняемые программы ярко-зеленые, скрытые файлы темно-серые и т.д), возможность поиска по имени файла и поддержка мыши значительно облегчают навигацию и управление файлами. И при этом, как любая консольная программа она почти не тратит системные ресурсы. Встроенный редактор тоже очень удобен для быстрого редактирования текстовых файлов. В нем есть подсветка синтаксиса, что несомненно понравится программистам, поиск и замена, плавная прокрутка страниц. А если не понравится встроенный редактор, то это легко исправить, прописав путь к вашему любимому редактору в переменной окружения EDITOR (любому и он тоже вызовется по кнопке F4). ${NC}"
echo -e "${CYAN}:: ${NC}Основные возможности программы: Текстовый интерфейс. Различные режимы вывода списка файлов. Просмотр подробной информации о файлах и каталогах. Древовидный режим просмотра. Поддержка работы с архивами. Распаковка архивов "не лету". Выделение файлов с использованием фильтра. Поддержка удаленных файловых систем (FTP, SFTP, Samba). Встроенный текстовый редактор MCEdit с подсветкой синтаксиса. Работа с программой через удаленный доступ, например, по SSH. Многоязычный интерфейс. Поддержка горячих клавиш. Продвинутый поиск файлов. Создание симлинков. Изменение прав доступа. Поддержка всех базовых операций работы с файлами (переименование, копирование, перемещение и так далее). Сравнение файлов. Выполнение некоторых операций над файлами в фоновом режиме. Поиск текста в файлах. Смотрите также: Использование Midnight Commander для поиска текста в файлах (https://pingvinus.ru/note/search-text-in-linux-mc). Поддержка настраиваемого пользовательского меню (User Menu). Пользовательское меню вызывается клавишей F2. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_mc  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_mc" =~ [^10] ]]
do
    :
done
if [[ $in_mc == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_mc == 1 ]]; then
  echo ""
  echo " Установка Midnight Commander (mc) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
############## mc ############
sudo pacman -S --noconfirm --needed mc  # Файловый менеджер, эмулирующий Norton Commande ; https://archlinux.org/packages/extra/x86_64/mc/ ; https://midnight-commander.org/ ; https://github.com/MidnightCommander/mc ; 2025-01-23 12:03 UTC
  echo ""
  echo " Посмотрите информацию о версии (mc) "
sudo pacman -Q mc  #  Показать версию приложения
# mc --version  # Показать версию приложения
echo ""
echo " Установка утилит (пакетов) выполнена "
fi
