clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Ranger (ranger) — Консольный файловый менеджер?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Одной из ключевых особенностей Ranger является его интеграция с множеством сторонних утилит для расширенного предпросмотра файлов. Для получения дополнительной информации о таких инструментах, посетите официальный репозиторий на GitHub (https://github.com/ranger/ranger). ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Ranger — это минималистичный консольный (текстовый) файловый менеджер для Unix-подобных операционных систем. Он предлагает минималистичный и приятный интерфейс Curses с отображением иерархии каталогов. В комплект входит rifle, средство запуска файлов, которое автоматически определяет, какую программу использовать для того или иного типа файлов. С его помощью можно быстро перемещаться по файловой системе в Linux прямо через интерфейс командной строки. Ranger имеет функцию предварительного просмотра файлов. Для навигации между директориями в Ranger используются сочетания клавиш, аналогичные тем, что применяются в редакторе Vi / Vim. Взаимодействие с программой частично реализовано в «в стиле» VIM (с привязками клавиш VI). Лицензия: GPL, GPL-3.0 . ${NC}"
echo " Домашняя страница: https://ranger.github.io/ ; (https://github.com/ranger/ranger ; https://archlinux.org/packages/extra/any/ranger/)."
echo -e "${BLUE}:: ${NC}Основные возможности и особенности программы Ranger: Минималистичный интерфейс. Быстрое переключение между директориями и просмотр файлов. Просмотр содержимого файлов. Просмотр изображений прямо в файловом менеджере (может потребоваться установка дополнительных пакетов). Поддержка основных операций с файлами (создание, копирование, перемещение, удаление, chmod и так далее). Массовое переименование файлов. Консоль в стиле VIM. Поддержка горячих клавиш из VIM. Поддержка вкладок. Поддержка закладок. Поддержка управления мышкой. Поставляется с утилитой rifle, которая предназначена для открытия (запуска) файлов. Она автоматически определяет программу, которая требуется для открытия выбранного файла. Поддержка цветовых схем. Поддержка UTF-8. Изменение директории оболочки после закрытия программы. Поддержка плагинов. "
echo -e "${CYAN}:: ${NC}Интерфейс: Файловый менеджер Ranger имеет минималистичный текстовый интерфейс. Каждый каталог отображается как отдельная панель. При переходе в новый каталог, он открывается (как следующий уровень иерархии) справа от текущего каталога. Текущий список файлов в каталоге отображается в самой правой части (в правой панели). Можно создавать вкладки. Текущая вкладка и номера вкладок отображаются в правом верхнем углу. Для переключения между вкладками используется клавиша Tab или сочетание Alt+номер вкладки. Все действия можно выполнять с использование клавиатурных сочетаний или команд. Поддерживается навигация мышкой. Для комфортной работы необходимо обязательно ознакомиться с горячими клавишами. Для получения справки по использованию программы выполните в терминале команду: man ranger или нажмите клавишу ? прямо в программе, а затем выберите информацию, которую вы хотите просмотреть (список в нижней строке). Внизу расположена строка для ввода команд в стиле VIM. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_ranger  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_ranger" =~ [^10] ]]
do
    :
done
if [[ $in_ranger == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_ranger == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Ranger (ranger) "
