sudo pacman -S --noconfirm --needed ranger  # Простой файловый менеджер в стиле vim ; https://archlinux.org/packages/extra/any/ranger/ ; https://ranger.github.io/ ; https://github.com/ranger/ranger ; 2025-02-26 22:45 UTC
  echo ""
