sudo pacman -S --noconfirm --needed elinks  # (необязательно) — для предварительного просмотра html-страниц ; Расширенный многофункциональный текстовый веб-браузер ; https://archlinux.org/packages/extra/x86_64/elinks/ ; https://github.com/rkd77/elinks ; 29 декабря 2024 г. 08:06 UTC
sudo pacman -S --noconfirm --needed ffmpegthumbnailer  # (необязательно) — для предпросмотра видео ; Легкий инструмент для создания миниатюр видео, который можно использовать в файловых менеджерах ; https://archlinux.org/packages/extra/x86_64/ffmpegthumbnailer/ ; https://github.com/dirkvdb/ffmpegthumbnailer ; 2024-11-07 20:01 UTC
sudo pacman -S --noconfirm --needed highlight  # (необязательно) — для подсветки синтаксиса кода ; Быстрый и гибкий инструмент подсветки исходного кода — версия CLI ; https://archlinux.org/packages/extra/x86_64/highlight/ ; http://www.andre-simon.de/doku/highlight/highlight.html ; 2025-07-16 18:23 UTC
