sudo pacman -S --noconfirm --needed lynx  # (необязательно) — для предварительного просмотра html-страниц ; Текстовый браузер для Всемирной паутины ; https://archlinux.org/packages/extra/x86_64/lynx/ ; https://lynx.invisible-island.net/ ; 2025-06-02 13:04 UTC
sudo pacman -S --noconfirm --needed mediainfo  # (необязательно) — для просмотра информации о медиафайлах ; Предоставляет техническую и теговую информацию о медиафайлах (интерфейс CLI) ; https://archlinux.org/packages/extra/x86_64/mediainfo/ ; https://mediaarea.net/ ; 2025-07-30 00:29 UTC
sudo pacman -S --noconfirm --needed odt2txt  # (необязательно) — для текстов OpenDocument ; Извлекает текст из текстов OpenDocument ; https://archlinux.org/packages/extra/x86_64/odt2txt/ ; https://github.com/dstosberg/odt2txt/ ; 2024-07-13 01:15 UTC
