clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Double Commander (doublecmd-qt5) (doublecmd-qt6) — Двухпанельный Файловый менеджер?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Это современное приложение, разработанное для использования с новейшими операционными системами. Базовая концепция управления восходит к популярному Norton Commander для DOS. Хотя файловый менеджер отличается широкими возможностями настройки дизайна и обширными, подробными возможностями. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Double Commander — двухпанельный файловый менеджер с открытым исходным кодом, аналог Total Commander работающий под Linux с использованием библиотек Qt. Программа имеет множество возможностей по управлению файлами и обладает большим числом настроек. Язык интерфейса: русский, английский и другие... Кроме стандартных возможностей файлового менеджера Double Commander поддерживает монтирование сетевых -шар и локальных дисков, легкое создание символических и жестких ссылок, а также имеет много горячих кнопок. Этот проект Лицензируется под Apache-2.0, BSD-2-Clause, GPL-2.0 или более поздняя версия, LGPL-2.0 или более поздняя версия, MIT, MPL-1.1, MPL-2.0, Zlib. ${NC}"
echo " Домашняя страница: https://doublecmd.sourceforge.io/ ; (http://doublecmd.sourceforge.net/ ; https://github.com/doublecmd/doublecmd ; https://archlinux.org/packages/extra/x86_64/doublecmd-qt5/ ; https://archlinux.org/packages/extra/x86_64/doublecmd-qt6/). "
echo -e "${BLUE}:: ${NC}Описание: Double Commander поддерживает вкладки, может сравнивать файлы и каталоги, поддерживает множественное переименование. Программа имеет расширенные возможности поиска файлов по шаблону, поиска текста в файлах и замены текста. Имеет встроенный редактор текста с подсветкой синтаксиса. Поддерживается работа с архивами, программа может работать с ними как с каталогами. Double Commander обладает большим числом настроек и позволяет настраивать внешний вид. Программа поддерживает плагины. По своей функциональности и оформлению Double Commander напоминает Total Commander и является ему хорошей бесплатной альтернативой в Linux. "
echo -e "${CYAN}:: ${NC}В сценарии (скрипта) присутствуют два варианта (версии) установки: Double Commander (Qt5)(пакет doublecmd-qt5) и Double Commander (Qt6)(пакет doublecmd-qt6) — выбор делать вам. Кому из вас понадобиться Double Commander (Gtk2)(пакет doublecmd-gtk2) или (пакет doublecmd-gtk2-alpha-bin), вы можете скачать их сами с AUR 'Helper' или установите GNOME Commander (пакет gnome-commander) — он создан на основе инструментария GTK и GIO.  "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
