echo -e "${YELLOW}==> Примечание! ${BOLD} *Программа выполнена в стиле традиционных двухпанельных файловых менеджеров, например, таких как Midnight Commander или Total Commander для Windows. Аналогом для рабочего стола KDE является файловый менеджер Krusader. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}GNOME Commander — свободный, двухпанельный файловый менеджер с открытым исходным кодом, работающий под GNU/Linux и использующий библиотеки GTK+ и инструментарии GIO. Применение предпочтительно в среде GNOME, но может быть использован и в других средах. Создан в традициях таких файловых менеджеров, как Norton и Midnight Commander. Свою дополнительную идею берёт уже от современных файловых менеджеров, таких как Total Commander. Языки программирования: C++. Приложение переведено на русский язык. Этот проект Лицензируется под GPL-2.0 или более поздняя версия. ${NC}"
echo " Домашняя страница: https://gcmd.github.io/ ; (https://github.com/GNOME/gnome-commander ; https://archlinux.org/packages/extra/x86_64/gnome-commander/). "
echo -e "${BLUE}:: ${NC}Основные возможности GNOME Commander: Поддержка вкладок. Режим одного экземпляра. Пользовательские цвета LS_COLORS. Возможность выбора/отмены выбора только файлов. Графический интерфейс GTK-3 со стандартным взаимодействием с мышью. MIME-типы Gnome. Встроенный FTP, SFTP и WebDAV клиент (используется модуль GnomeVFS). Сетевой доступ через GIO. Доступ к SAMBA (если GIO поддерживает ее). Контекстное меню мыши, которое можно легко расширить за счет пунктов, вызывающих любые внешние приложения, такие как просмотрщики, редакторы или пользовательские скрипты для работы с выбранными файлами или каталогами. Возможность добавления пунктов в контекстное меню, открывающееся при клике правой кнопкой мыши по файлам. Поддержка горячих клавиш. Кнопки быстрого доступа к устройствам с автоматическим монтированием и размонтированием (вариант «без монтирования» для быстрого доступа только к папкам или иным автоматически монтированным устройствам). Закладки папок. История последних посещенных папок. Перемещение по истории посещения директорий. Создание закладок для быстрого доступа к директориям. Поддержка плагинов находится в стадии разработки. Быстрый внутренний просмотрщик файлов для текста, изображений и метаданных изображений (EXIF, IPTC, ID3, Vorbis, FLAC, APE, PDF, OLE2 и ODF). Встроенная утилита для поиска файлов. Встроенная утилита для сравнения директорий. Встроенная утилита для группового переименования файлов. Быстрый поиск имени файла в текущем каталоге. Символические ссылки, сравнение каталогов. Инструмент для расширенного переименования файлов, поддерживающий различные типы метаданных. Интегрированная (встроенная) командная строка. Поддержка более 40 языков. И другие. Функционально файловый менеджер GNOME Commander для Linux схож с Total Commander для Windows, хотя уступает ему в функциональности. "
echo -e "${CYAN}:: ${NC}Информацию по СИНОПСИС — https://man.archlinux.org/man/extra/gnome-commander/gnome-commander.1.en "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
