######## gnome-commander #############
sudo pacman -S --noconfirm --needed gnome-commander  # Графический двухпанельный файловый менеджер для GNOME ; https://archlinux.org/packages/extra/x86_64/gnome-commander/ ; https://gcmd.github.io/ ; https://github.com/GNOME/gnome-commander ; 2025-07-24 18:06 UTC
  echo ""
