echo -e "${YELLOW}==> Примечание! ${BOLD} *Иногда требуется вывести в терминале информацию о системе Linux вместе с логотипом. Это может потребоваться для скриншота, чтобы было сразу понятно о какой операционной системе идёт речь. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}ScreenFetch — это простая консольная утилита для вывода информации о системе и ресурсах, драйвере и ОЗУ в Linux.
Фактически, это даже не столько утилита, screenFetch это просто скрипт, написанный на bash, запускаемый через штатный терминал, который выводит различную информацию о системе. Он автоматически определяет, какой у вас дистрибутив, и выводит логотип дистрибутива в текстовом виде (ASCII). Справа от логотипа отображается различная информация о системе и ресурсах вашего компьютера. Этот проект Лицензируется под GPL-3.0 . ${NC}"
echo " Домашняя страница: https://github.com/KittyKatt/screenFetch ; (https://archlinux.org/packages/extra/any/screenfetch/). "
echo -e "${BLUE}:: ${NC}ScreenFetch выводит следующую информацию: Названия и версию операционной системы. Версию ядра. Время работы системы (uptime). Количество установленных пакетов. Версию shell’а. Разрешения экрана. Среду рабочего стола. Оконный менеджер. Используемые темы оформления. Название процессора. Название видеоплаты (GPU). Свободное и занятое место ОЗУ. Для запуска утилиты нужно выполнить в командной строке команду: screenfetch. Поддерживаются различные аргументы командной строки. "
echo -e "${CYAN}:: ${NC}Предназначается этот простой и легкий инструмент для получения основных сведений об операционной системе Linux и её основных компонентов. Поддерживая работу с большинством популярных Linux-дистрибутивов, Screenfetch позволяет получать данные о названии системы и ее версии, используемой графической оболочки, темы оформления и оконного менеджера, версии ядра и shell’а, количестве установленных пакетов, драйверах, общее время работы. Показывает Screenfetch также некоторые характеристики железа: название процессора и видеокарты, используемый и свободный объем оперативной памяти, разрешение экрана. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
