### Для запуска утилиты нужно выполнить в командной строке команду:
# screenfetch
# После установки, пропишите в конец файла .bashrc
# Добавьте команду screenfetch в конец файла
# screenfetch
# Поддерживаются различные аргументы командной строки.
# Ниже приведены несколько примеров команд для screenfetch, которые можно использовать в терминале.
# Отображение Системной Информации:
# Запустить screenfetch:
# screenfetch
# Сделайте снимок экрана (требуется 'scrot'):
# screenfetch -s
# Укажите логотип распространения:
# screenfetch -A 'distribution_name'
# Укажите логотип и текст распространения:
# screenfetch -D 'distribution_name'
# Для изменения цветового оформления используются аргументы -c1, -c2 и так далее, например:
# screenfetch -c5
# Удалить все цвета:
# screenfetch -N
# Например, если добавить -n, то логотип отображаться не будет:
# screenfetch -n
# Полный список аргументов:
# screenfetch -h
