clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Fastfetch (fastfetch) — Информация и логотип дистрибутива?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Fastfetch, как быстрая альтернатива Neofetch. В любом случае Fastfetch станет для вас отличной альтернативой. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Fastfetch — это утилита командной строки для получения (вывода) системной информации и её визуального отображения в удобном для понимания формате. Он написан преимущественно на языке C с упором на производительность и настраиваемость. Она уже есть в большом количестве дистрибутивов, но не везде самые свежие версии. В настоящее время он поддерживает Linux, macOS, Windows 7+, Android, FreeBSD, OpenBSD, NetBSD, DragonFly, Haiku и SunOS. Fastfetch — удобный инструмент как для обычного пользователя, так и для энтузиаста технологий. Fastfetch доступен в официальных репозиториях нескольких популярных дистрибутивов Linux. Этот проект Лицензируется под MIT. ${NC}"
echo " Домашняя страница: https://github.com/fastfetch-cli/fastfetch ; (https://github.com/fastfetch-cli/fastfetch/wiki/Configuration ; https://archlinux.org/packages/extra/x86_64/fastfetch/ ; https://github.com/fastfetch-cli/fastfetch/releases/latest). "
echo -e "${BLUE}:: ${NC}Он предлагает похожие функции как Neofetch, включая привлекательный ASCII-логотип вашей операционной системы, также может генерировать системную информацию с различными логотипами. Fastfetch предоставляет массу информации о вашей системе, например, о процессоре, видеокарте, памяти, локальном IP-адресе и многом другом. Кроме того, он обладает широкими возможностями настройки, поэтому вы можете настроить вывод именно так, как вам нужно. Fastfetch намного лучше, чем Neofetch: он быстрее, более функциональный, поддерживает Wayland (Neofetch технически не поддерживал) и активно поддерживается. Действительно, Fastfetch заявляет о себе как о «неофетче подобном инструменте для получения системной информации и ее красивого отображения». "
echo -e "${CYAN}:: ${NC}После установки Fastfetch вы можете использовать команду: fastfetch - для запуска Fastfetch с конфигурацией по умолчанию. В результате будет выведен большой логотип ASCII, а также полный список системной информации. Как можно настроить Fastfetch в соответствии с вашими личными потребностями: Файл конфигурации Fastfetch обычно находится по адресу ~/.config/fastfetch/config.jsonc. Из файла видно, что конфигурация Fastfetch представляет собой JSON-файл с комментариями. Для редактирования файла конфигурации fastfetch рекомендуется использовать редактор с поддержкой JSON Scheme. При первой установке Fastfetch вы не получите файл конфигурации. Поэтому первым шагом будет создание простого файла конфигурации. Для этого выполните команду: fastfetch --gen-config . Иконки не отображаются в Fastfetch? Просто скачайте zip-архив шрифта Nerdfonts только для символов (https://github.com/ryanoasis/nerd-fonts/releases/tag/v3.2.1), распакуйте, установите шрифт обновите кэш шрифтов, и все будет в порядке! Терминал возвращается к поддерживаемому шрифту юникода для отсутствующих символов (текст не затрагивается). "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
