echo -e "${BLUE}:: ${NC}Установить Neofetch (neofetch) — Информация и логотип дистрибутива?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Эта программа до сих пор отлично работает в 2025 году. Настройка конфигурации гораздо ближе к KISS. И выглядит гораздо лучше. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Neofetch — это утилита командной строки, которая выводит информацию о системе. Фактически neofetch представляет собой скрипт (состоящий из одного файла), написанный на языке командной оболочки Bash. Neofetch является аналогом утилиты ScreenFetch. Утилита написанная на Bash и предназначенная для вывода информации о программном и аппаратном обеспечении вашего дистрибутива. Вывод информации приятен взгляду: выводится логотип вашего дистрибутива в формат ASCII и краткая информация о дистрибутиве. После первого запуска утилиты создается конфигурационный файл, в котором можно поменять логотип и вывод информации. Этот проект Лицензируется под GPL-2.0 . ${NC}"
echo " Домашняя страница: https://github.com/dylanaraps/neofetch ; (https://aur.archlinux.org/neofetch.git ; https://aur.archlinux.org/packages/neofetch). "
echo -e "${BLUE}:: ${NC}Основные возможности: Вывод информации о системе. Вывод логотипа операционной системы (ascii) или произвольного изображения (Image Mode). Использование файла конфигурации: $HOME/.config/neofetch/config.conf (создается при первом запуске). Вывод информации, определенной пользователем. Настройка цвета шрифта (для каждой строки). Neofetch может выводить следующую информацию о системе: Название и версию операционной системы. Название компьютера (хоста). Версия ядра Linux. Время непрерывной работы системы — Uptime. Количество пакетов. Название и версию командной оболочки. Разрешение экрана. Название оконного менеджера. Название темы оформления оконного менеджера. Название темы оформления среды. Название темы иконок. Наименование терминала. Шрифт терминала. Информацию о процессоре. Информацию о графической карте. Количество занятой и общий объем оперативной памяти. Логотип операционной системы. "
echo -e "${CYAN}:: ${NC}Neofetch имеет довольно гибкую конфигурацию, и каждый может настроить его под себя. Neofetch хранит свою конфигурацию в файле config.conf в каталоге ~/.config/neofetch/config.conf в вашей домашней папке. С момента его появления в конце 2015 года, Neofetch стал почти обязательным приложением для каждого пользователя Linux, особенно среди энтузиастов кастомизации, которые любят демонстрировать свои настройки в сообществе. С 26 апреля 2024 года оригинальный Neofetch больше не поддерживается, но некоторые его форки всё ещё обновляются. "
echo -e "${CYAN}:: ${NC}Установка Neofetch (neofetch) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/neofetch.git), (https://aur.archlinux.org/packages/neofetch) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_neofetch  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_neofetch" =~ [^10] ]]
do
    :
done
if [[ $in_neofetch == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_neofetch == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Neofetch (neofetch) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) "
