# https://linuxsimply.com/neofetch-command-in-linux/
# Как заменить логотип дистрибутива в neofetch?
# gedit ~/.config/neofetch/config.conf
# 763 строка (изменить логотип на любой из списка)
# 711 строка (путь/до/своего/файла.ascii)
# и еще, что бы постоянно не вводить команду в терминале, добавьте команду neofetch в конец файла ~/.bashrc.
# gedit ~/.bashrc
# Так же могу посоветовать установить lolcat
# после этих манипуляций дописать в конец файла ~/.bashrc к команде neofetch еще прямой слеш и команду lolcat, должно выглядеть так:
# neofetch | lolcat
# сохранить. на этом все.
# Теперь после каждого вызова терминала, вы будете любоваться красивым neofetch.
# Также lolcat можно применять к абсолютно любому выводу в терминале, добавляя после введенной команды, прямой слеш "|" и саму команду "lolcat".
# Пара примеров:
# inxi -F | lolcat
# df -Th | lolcat
