clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Cowfortune (cowfortune) — Информация и логотип (с изображением коровы или пингвина)?"
echo -e "${YELLOW}==> Предисловие! ${BOLD} *Linux не всегда связан с работой. Иногда можно и нужно немного подурачиться и повеселиться. Установите Cowfortune (Коровья Удача) - Настраиваемое Печенье С Предсказанием, Изображающее Корову (И Несколько Других Существ). И Fortune — это инструмент, который выводит данные о состоянии из базы данных ... и получайте удовольствие! (эй, рифмуется!). ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Cowfortune (cowsay) —  это программа, которая генерирует ASCII- арты коровы с сообщением. Она также может генерировать изображения, используя готовые изображения других животных, например, пингвина Такса, талисмана Linux. Она написана на Perl. Существует также родственная программа под названием cowthink , в которой коровы используют пузыри мыслей, а не речевые пузыри. Существуют файлы для cowsay, которые могут создавать различные варианты коров, с разными типами глаз и т. д. Иногда она используется в IRC , на снимках экрана рабочего стола и в документации к программному обеспечению. Это более или менее шутка в хакерской культуре , но существует достаточно давно, чтобы ее использование стало довольно распространенным. В 2007 году она была выделена как пакет дня Debian. Доступна в репозитории extra дистрибутива Arch Linux. Этот проект Лицензируется под GPL-2.0 . ${NC}"
echo " Домашняя страница: https://github.com/anthraxx/cowfortune ; (https://archlinux.org/packages/extra/any/cowfortune/ ; https://www.shlomifish.org/open-source/projects/fortune-mod/ ; https://github.com/busyloop/lolcat ; https://github.com/Macchina-CLI/macchina). "
echo -e "${BLUE}:: ${NC}Функции: Команду Unix fortune также можно передать в команду cowsay : fortune | cowsay . Используя параметр -f и после него tux , можно заменить корову другими существами, например, Tux , талисманом Linux: fortune | cowsay -f tux . При использовании параметра -l отображаются все доступные файлы cow: cowsay -l . "
echo -e "${CYAN}:: ${NC}Ну и зачем все это? Основной сценарий использования - в случае необходимости быстро поделиться информацией о своем дистрибутиве на форуме или в мессенджере. Также подобные утилиты используются для украшательства терминала при запуске. Если изменить конфигурационный файл оболочки и внести туда имя команды, то при запуске терминала она будет запускаться. У меня стоит оболочка ZSH, потому мне достаточно изменить файл .zshrc, который находится в домашней директории пользователя. "
echo -e "${CYAN}:: ${NC}Установка пакета Для русификации утилиты Fortune Mod (fortune-mod-ru) проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/fortune-mod-ru.git) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_cowfortune  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_cowfortune" =~ [^10] ]]
do
    :
done
if [[ $in_cowfortune == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_cowfortune == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Cowfortune (cowfortune) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) (cowsay, fortune-mod, lolcat, macchina и т.д...) "
