echo ""
echo -e "${BLUE}:: ${NC}Установить Htop (htop) - Монитор ресурсов?"
echo -e "${MAGENTA}:: ${BOLD}Htop — продвинутый монитор системных ресурсов для Linux. Утилита htop предназначена для расширенного анализа использования системных ресурсов процессами в реальном времени. Отображает информацию о загрузке процессора, использовании оперативной памяти, swap, виртуальной памяти и других параметров. Программа работает в текстовом режиме и может запускаться из консоли или из эмулятора терминала. Утилита htop обладает большими возможностями чем утилита top в Linux. Преимущества htop перед top: Графическое отображение загрузки процессора, оперативной памяти и подкачки. Поддержка управления с помощью клавиатуры и мыши. Полные командные строки процессов. Горизонтальная и вертикальная прокрутка списка процессов. Интерактивное управление приоритетами процессов. Возможность сортировки процессов по различным параметрам. Отображение зависимостей процессов в виде дерева. Гибкие настройки интерфейса и цветовых схем. Радует огромный функционал и одновременная простота. ${NC}"
echo " Домашняя страница: https://htop.dev/ ; (https://archlinux.org/packages/extra/x86_64/htop/). "
echo -e "${BLUE}:: ${NC}Функции: Позволяет искать и "убивать" задачи легкой комбинацией клавиш. А так же просто смотреть нагрузку системы в реальном времени. Процессор - нагрузка на каждое ядро в процентах (%). Оперативная память - использование в мегабайтах и гигабайтах. SWP-раздел подкачки - использование в мегабайтах и гигабайтах. Рядом отображается количество задач и время работы системы (uptime). "
echo -e "${CYAN}:: ${NC}Представьте ситуацию когда X-сервер безбожно тормозит из-за какого нибудь весомого приложения и единственное, что вы смогли сделать, это выйти в консоль (CTRL+ALT+F1). Консольный вывод как правило не настроен и вывод команды "ps aux" растягивается на многие страницы экрана. Что делать? Используйте "волшебную" команду htop и перед вами появится разноцветный интерфейс программы, написанный с помощью библиотек NCurses. Перед вами появится информация о текущей загрузке системы, оперативной памяти, файла подкачки, использование процессорного времени и даже о том, какие процессы каким файлом были запущены, обновляясь в реальном времени. Он позволит вам перелистывать вверх и вниз активные процессы, группировать их в деревья и производить с ними различные операции с помощью сигналов вроде SIGTERM и SIGKILL. Большую часть "окна" занимает сама панель с задачами а ниже указаны горячие клавиши для управления задачами в этом системном мониторе. Htop можно легко настроить: окно настроек можно вызвать, нажав клавишу F2. Вы можете настроить внешний вид программы, параметры, которые вы хотите просматривать и прочее. В htop можно с легкостью изменить приоритет процесса или остановить его, отобразить процессы в виде дерева (клавиша F5), задать сортировку по какому-либо параметру (клавиша F6). Этот проект распространяется по лицензии GNU General Public License v2.0 . "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
