### Atop — это полноэкранный ASCII-монитор производительности для Linux, способный отслеживать активность всех процессов (даже если процессы были завершены в течение заданного интервала), ежедневно регистрировать активность системы и процессов для долгосрочного анализа, выделять перегруженные системные ресурсы цветами и т. д. Atop регулярно отображает системную активность, связанную с процессором, памятью, подкачкой, дисками (включая LVM) и сетевыми уровнями, а для каждого процесса (и потока) показывает, например, загрузку процессора, рост памяти, загрузку диска, приоритет, имя пользователя, состояние и код завершения.
