clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Glances (glances) - Мониторинг ресурсов системы?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Допустим, что у нас не очень обширная инфраструктура: несколько небольших VPSок, подкроватник, NAS и два ноутбука, торчащих в сеть. Тем не менее, за ней всё равно надо приглядывать, и заниматься этим вручную раздражает всё больше с каждой новой машиной. Искал утилиту мониторинга системы, которая могла бы не съедая лишних ресурсов агрегировать информацию отовсюду в единый дашборд, желательно без геморроя с настройкой. В итоге, как только десятки мелких консольных утилит были отброшены вместе с чрезмерно усложнёнными корпоративными хреновинами вроде Prometheus и RabbitMQ, поиск быстро привёл меня к Glances — утилите, берущей лучшее от обоих миров. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Glances — консольный монитор системных ресурсов, который отображает максимум информации на одном экране. Написанный на Python с использованием библиотеки psutil для получения данных от системы. Glances будет работать практически на любой платформе: GNU/Linux, FreeBSD, OS X и Windows. Glances включает в себя сервер XML-RPC и RESTful JSON API, которые могут использоваться другим клиентским программным обеспечением. Нет терминала под рукой? Используйте встроенный веб-интерфейс и контролируйте свою систему с любого устройства. Экспортируйте всю системную статистику в CSV, InfluxDB, Cassandra, OpenTSDB, StatsD, ElasticSearch или даже RabbitMQ. Glances также предоставляет специальную панель инструментов Grafana. Кстати, Glances умеет работать и на мобильных устройствах (но, очевидно, только на рутованном андроиде, что сильно сужает круг применения). Этот проект Лицензируется под GPL-3.0 . ${NC}"
echo " Домашняя страница: https://nicolargo.github.io/glances/ ; (https://archlinux.org/packages/extra/any/glances/). "
echo -e "${BLUE}:: ${NC}Функции: Glances не имеет функциональности по управлению процессами. Убивать или изменять состояние процессов нельзя. Glances поддерживает работу в режиме клиент-севера. Удаленный доступ к утилите можно выполнить через терминал, Web-интерфейс или используя Application Programming Interface (API). Поддерживается экспорт данных в форматы CSV, InfluxDB, Cassanda и другие. Управление осуществляется с клавиатуры. Список горячих клавиш можно получить, нажав клавишу h. Всю информацию по настройке и использованию утилиты можно почитать в официальном руководстве: https://glances.readthedocs.io/en/latest/ . "
echo -e "${CYAN}:: ${NC}Утилита позволяет просматривать следующую информацию: Запущенные процессы; Использование ЦПУ; Загрузку ядер ЦПУ; Использование ОЗУ; Использование SWAP; Использование Дисков; Сетевой мониторинг, включая WiFi и другие данные. Поддерживаются плагины, которые имеют отдельные настройки и позволяют отображать дополнительную информацию. Например: Информацию о размере определенных директорий; Информацию о портах; Информацию о прерываниях; Температуру и так далее... "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
