### Glances - https://archlinux.org/packages/extra/any/glances/ ; https://glances.readthedocs.io/en/latest/quickstart.html
# Мощный мониторинг за пять минут с помощью Glances
# https://habr.com/ru/companies/vdsina/articles/545274/
# Установите Glances на дистрибутивы Linux: Ubuntu, CentOS, RHEL, Debian, Arch Linux и т. д.
# https://www.linuxuntu.com/install-glances-linux/
# Установка Glances в Linux с помощью скрипта автоматической установки
# https://raw.githubusercontent.com/nicolargo/glancesautoinstall/master/install.sh
# Чтобы установить Glances этим методом, вам нужно всего лишь открыть окно терминала с помощью сочетания клавиш Ctrl+Alt+T и ввести следующую команду:
# curl -L https://bit.ly/glances | /bin/bash
# Или,
# wget -O- https://bit.ly/glances | /bin/bash
# Парамертры Glances:
# Поле указания атрибутов открывается клавишей «Enter» во время работы программы. Все доступные атрибуты можно посмотреть, нажав «h»:
# a – сортировать процессы автоматически;
# c – сортировать процессы по CPU%;
# m – сортировать процессы по MEM%;
# p – сортировать процессы по имени;
# i – сортировать процессы по скорости ввода/вывода;
# d – показать/скрыть статистику дискового ввода-вывода;
# f – показать/скрыть статистику директорий и файлов;
# n – показать/скрыть сетевую статистику;
# s – показать/скрыть статистику датчиков;
# y – показать/скрыть статистику hddtemp;
# l – показать/скрыть логи;
# b – байты или биты для сетевых входов/выходов;
# w – удалить журналы предупреждений;
# x – удалить предупреждения и критические журналы;
# 1 – общая статистика ЦП;
# h – показать/скрыть этот экран справки;
# T – просмотреть сетевой ввод/вывод как комбинации;
# U – просмотреть совокупный сетевой ввод/вывод;
# q – выйти (Esc и Ctrl+C тоже работают).
# Для запуска утилиты введите её название в терминале:
# glances
# Команда glances также имеет свои опции. Чтобы вывести их на экран, выполните в терминале:
# glances --help
# glances --version  # Показать версию приложения (номер версии программы Glances и позволяет выйти из неё)
# Также возможно вывести статистику RAW (Python) непосредственно на стандартный вывод, используя:
# glances --stdout cpu.user,mem.used,load,network.wlp2s0.bytes_all
# или в формате CSV благодаря опции stdout-csv (ключ не поддерживается в этом режиме):
# glances --stdout-csv now,cpu.user,mem.used,load
# или в формате JSON благодаря опции stdout-json (атрибут не поддерживается в этом режиме):
# glances --stdout-json cpu,mem
# Примечание: при каждом обновлении будет отображаться одна строка для каждой статистики.
