clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Gnome System Monitor (gnome-system-monitor) - Системный монитор?"
echo -e "${MAGENTA}:: ${BOLD}Gnome System Monitor — программа для мониторинга работы системы. Является штатным системным монитором в рабочей среде Gnome. Системный монитор — простой инструмент для просмотра и управления процессами. Системный монитор поможет определить, какие приложения используют процессор или память компьютера, может управлять запущенными приложениями, останавливать зависшие процессы и изменять состояние или приоритет выполняющихся процессов. ${NC}"
echo " Домашняя страница: https://apps.gnome.org/SystemMonitor ; (http://freecode.com/projects/gnome-system-monitor ; https://github.com/GNOME/gnome-system-monitor ; https://archlinux.org/packages/extra/x86_64/gnome-system-monitor/). "
echo -e "${BLUE}:: ${NC}Функция отображения графика ресурсов предоставляет краткий обзор того, что происходит с компьютером, показывая использования сети, памяти и процессора. Интерфейс программы довольно простой. Вся информация распределена по четырем вкладкам. В первой вкладке «Система» выводится базовая минимальная информация о системе. Во второй вкладке «Процессы» можно просматривать и управлять, работающими процессами. Каждый процесс можно приостановить, остановить, изменить приоритет и выполнить некоторые другие действия. Наиболее интересно выглядит вкладка «Ресурсы». В ней утилита выводит в виде графиков информацию в реальном времени о ресурсах — использование процессора (CPU), использование оперативной памяти (RAM) и файла подкачки (SWAP), а также использование сети. И в последней вкладке можно просматривать информацию о файловых системах. "
echo -e "${CYAN}:: ${NC}Оно обладает такими функциями, как древовидная структура зависимостей процессов, значки процессов, возможность скрывать процессы, которые вы не хотите видеть, графическое отображение истории использования ЦП/памяти/свопинга, возможность завершать/сбрасывать процессы, требующие доступа root, а также стандартные функции, которые можно ожидать от средства просмотра процессов. Этот проект распространяется по лицензии GNU General Public License v2.0 . "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_monitor  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_monitor" =~ [^10] ]]
do
    :
done
if [[ $in_monitor == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_monitor == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Gnome System Monitor (gnome-system-monitor) "
