############ gnome-system-monitor #############
sudo pacman -S --noconfirm --needed gnome-system-monitor  # Просмотр текущих процессов и мониторинг состояния системы ; https://archlinux.org/packages/extra/x86_64/gnome-system-monitor/ ; https://apps.gnome.org/SystemMonitor ; https://welcome.gnome.org/ru/app/SystemMonitor/ ; https://github.com/GNOME/gnome-system-monitor ; 2025-04-12 18:08 UTC
  echo ""
  echo " Посмотрите информацию о версии Gnome System Monitor (gnome-system-monitor) "
sudo pacman -Q gnome-system-monitor  #  Показать версию приложения
