clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Btop++ (btop) - Монитор системных ресурсов?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Если вы долгое время используете команды Htop или Top вместе с другими дополнительными командами для мониторинга ресурсов на вашем компьютере с Linux и хотите опробовать новый инструмент, который показывает больше информации в причудливом и футуристическом виде, то вам определенно стоит попробовать Btop. Все мы пом­ним утилиту bashtop, так вот Btop++ — это его реали­зация на C++ с повышен­ной про­изво­дитель­ностью. Умень­шен­ный интервал обновле­ния гра­фиков не при­водит к зна­читель­ному повыше­нию наг­рузки на про­цес­сор. При этом даш­борд выг­лядит столь же кра­соч­но и эффек­тно для неис­кушен­ного посети­теля тво­ей сер­верной! ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Btop++ — это инструмент FOSS с простым, но подробным и футуристичным дизайном для мониторинга ресурсов Linux. Он отображает очень подробную информацию (статистику процессора, памяти, дисков, сети и процессов) и имеет футуристический пользовательский интерфейс. С этим приложением нам не нужно полагаться на другие дополнительные команды, такие как 'ps', 'df', 'ifconfig', 'lscpu' или 'free -m' . Это единая точка отслеживания всех ресурсов, которая также позволяет настраивать её в соответствии с потребностями пользователя. btop++ – это как bashtop и bpytop, но написанный на (плюсах) C++ , отсюда и название, видимо. Называется она «btop++», но сайт не даёт вписать плюсы в название. И да, это уже третья итерация той же утилиты от того же разработчика. Btop богат темами, возможностями настройки и функциями, а также красивыми графиками и анимацией. Поначалу он кажется очень сложным из-за обилия информации на экране, но со временем вы поймёте, что всё это кажется привычным, и в будущем вам не придётся выполнять множество команд для решения простой проблемы. Он служит достойной альтернативой командам top и htop. Этот проект Лицензируется под Apache 2.0.. ${NC}"
echo " Домашняя страница: https://github.com/aristocratos/btop ; (https://archlinux.org/packages/extra/x86_64/btop/ ; https://github.com/aristocratos/bashtop). "
echo -e "${BLUE}:: ${NC}Функции: Простая в использовании, с игровой системой меню. Полная поддержка мыши: все кнопки с выделенной клавишей можно нажимать, а прокрутка мышью работает в списке процессов и полях меню. Быстрый и отзывчивый пользовательский интерфейс с клавишами выбора процессов ВВЕРХ и ВНИЗ. Функция отображения подробной статистики для выбранного процесса. Возможность фильтрации процессов. Простое переключение между вариантами сортировки. Древовидный структура (вид) процессов. Отправка любого сигнала выбранному процессу. Меню пользовательского интерфейса для изменения всех параметров конфигурационного файла. Автоматическое масштабирование графиков в блоке использования сети. Отображение активность ввода-вывода и скорость для дисков. Статистика батареи (Индикатор батареи) для устройств с встроенным аккумулятором. Выбор символов для построения графиков. Пользовательские предустановки (пресеты). Поддержка тем оформления. И многое другое... Вы также можете выбрать и настроить интерфейс Btop, скрыв некоторые показатели, которые не нужно отображать постоянно. Вы можете выбрать несколько макетов в настройках Btop. "
echo -e "${CYAN}:: ${NC}Для запуска btop необходимо выполнить в терминале команду btop. По умолчанию btop отображает блок статистики процессора, вывод активных процессов, доступное место на жестких дисках, статистика использования памяти и сети. Настройки группируются по категориям general, cpu, mem, net, proc. В general находятся основные настройки btop — выбор темы, настройка выводимых блоков, время обновления статистики. В cpu, mem, net и proc находятся настройки отображения каждого из блоков. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
