### Пакет i2c-tools содержит разнообразный набор инструментов I2C для Linux: инструмент для зондирования шины, средство создания дампа микросхемы, средства доступа к SMBus на уровне регистров, скрипты декодирования EEPROM, инструменты программирования EEPROM и модуль Python для доступа к SMBus. Поддерживаются все версии Linux, при условии, что поддержка I2C включена в ядро. Эти инструменты раньше входили в пакет lm-sensors, но позже были выделены в отдельный пакет. Это обусловлено тем, что не все микросхемы аппаратного мониторинга являются устройствами I²C, и не все устройства I²C являются микросхемами аппаратного мониторинга, поэтому размещение всех компонентов в одном пакете было запутанным и непрактичным.
