sudo pacman -S --noconfirm --needed btop  # Монитор системных ресурсов bpytop, портированный на C++ ; https://archlinux.org/packages/extra/x86_64/btop/ ; https://github.com/aristocratos/btop ; 2025-07-07 10:59 UTC
