echo ""
echo -e "${BLUE}:: ${NC}Установить Monitorix (monitorix) - Монитор системных ресурсов?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *Говоря о системах мониторинга, многие системные администраторы сразу представляют себе мощные централизованные системы наподобие Zabbix, внедрение которых требует времени и ресурсов. Но это неверное представление, существуют простые и легкие приложения, позволяющие собирать и визуализировать статистику для одиночного узла. Да, их возможности гораздо скромнее, но тем не менее даже простой мониторинг - это лучше чем никакого. Одна из таких систем - Monitorix - простое и легкое решение, которое поможет вам быть в курсе происходящего на вашем сервере. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Monitorix — это бесплатный, лёгкий инструмент мониторинга системы с открытым исходным кодом, предназначенный для мониторинга максимально возможного количества служб и системных ресурсов (как аппаратных, так и программных). Он был разработан для использования на рабочих серверах Linux/UNIX , но благодаря своей простоте и небольшому размеру может использоваться и на встраиваемых устройствах. Поддерживается мониторинг: активных системных процессов, загруженность памяти, процессора, сетевых интерфейсов, температурных сенсоров, системных сервисов (Apache, Sendmail, Postfix, Nginx, Lighttpd, MySQL) и многое другое. Программа написана на Perl. Доступ к Monitorix осуществляется через web-интерфейс, поэтому для работы программы нужны Apache и Perl. После установки на локальном компьютере Monitorix можно вызвать, набрав в браузере http://localhost/monitorix/ . Программа Monitorix это скорее профессиональный инструмент. Если вам нужен более простой инструмент мониторинга, тогда можно воспользоваться, например, утилитой HTop. Этот проект Лицензируется под GNU General Public License версии 2 (GNU GPLv2). ${NC}"
echo " Домашняя страница: https://www.monitorix.org/ ; (https://www.monitorix.org/documentation.html ; https://github.com/mikaku/Monitorix ; https://aur.archlinux.org/packages/monitorix ; https://aur.archlinux.org/packages/monitorix-git). "
echo -e "${BLUE}:: ${NC}Он состоит в основном из двух программ: сборщика, называемого monitorix, представляющего собой демон Perl, который запускается автоматически, как и любая другая системная служба, и CGI-скрипта monitorix.cgi. Monitorix включает в себя собственный встроенный HTTP-сервер (который по умолчанию прослушивает порт 8080/TCP) для просмотра графиков статистики, поэтому вам не нужно устанавливать сторонний веб-сервер для его использования. Просто откройте в браузере http://localhost:8080/monitorix. "
echo -e "${CYAN}:: ${NC}Все разработки изначально создавались для мониторинга систем Red Hat, Fedora и CentOS Linux, поэтому этот проект создавался с учётом этих типов дистрибутивов. Сегодня он работает в различных дистрибутивах GNU/Linux и даже в других UNIX-системах, таких как FreeBSD, OpenBSD и NetBSD. В настоящее время он находится в стадии активной разработки, в ходе которой добавляются новые функции, новые графики и исправляются ошибки в попытке предложить отличный инструмент для ежедневного системного администрирования. "
echo -e "${CYAN}:: ${NC}Установка Monitorix (monitorix) и (monitorix-git), проходит через сборку из исходников, которые устанавливаются из 'AUR' через 'yay' в зависимости от вашего выбора. Также в сценарии (скрипта) прописана установка с помощью git clone, PKGBUILD, makepkg - скачивается с сайта 'Arch Linux' (https://aur.archlinux.org/monitorix.git), (https://aur.archlinux.org/monitorix-git.git) - собирается и устанавливается. Но эта функция закомментирована # , если нужно раскомментируйте или воспользуйтесь сценарием (скрипта) как шпаргалкой ! "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
