clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Evisum (evisum) - EFL Системный монитор?"
echo -e "${MAGENTA}:: ${BOLD}Evisum — это монитор процессов и системный монитор, написанный на EFL, использующий библиотеки Enlightenment Foundation Libraries (EFL) - величайший из когда-либо написанных системных мониторов. Evisum — мощный, эффективный и многофункциональный инструмент для мониторинга процессов и системы для Linux, OpenBSD, FreeBSD, macOS и DragonFlyBSD . В отличие от других системных мониторов, Evisum предлагает архитектуру «сервер-клиент» с элегантным и отзывчивым интерфейсом. Он предлагает надежные инструменты для мониторинга процессов, использования процессора, потребления памяти, сетевой активности, состояния хранилища и системных датчиков, а также является основой всех эталонных реализаций для обеспечения портативности. Он был написан органично, и его реализация потребовала много часов и чтения большого количества ручного кода. Он красивый и отдаёт дань уважения приложениям FOSS 90-х годов. С Лицензией не совсем разобрался: где то написано, что у продукта Лицензия: BSD, а также написано, что Лицензия: OpenSource GPL-2 ISC (Это бесплатное программное обеспечение с открытым исходным кодом). ${NC}"
echo " Домашняя страница: https://www.enlightenment.org/ ; (https://github.com/haxworx/evisum ; https://archlinux.org/packages/extra/x86_64/evisum/ ; https://git.enlightenment.org/enlightenment/evisum). "
echo -e "${BLUE}:: ${NC}Особенности: Кроссплатформенная поддержка — работает на Linux, FreeBSD, OpenBSD, macOS и DragonFlyBSD с одинаковым набором функций. Архитектура «сервер -клиент» для эффективного мониторинга системы. Инструменты для мониторинга: Процессы (список процессов, просмотр отдельного процесса, запуск/остановка/завершение отдельного процесса); Загрузка ЦП (PID процесса, UID, имя, количество потоков, использование памяти, nice, приоритет, состояние, идентификатор ЦП, использование ЦП и мониторинг ЦП); Потребление памяти (мониторинг памяти); Сетевая активность (мониторинг использования сети); Состояние хранилища (мониторинг использования диска); Системные датчики (мониторинг температуры ЦП); Состояние батареи и питания ; Разработано для скорости, надежности и удобства использования. "
echo -e "${CYAN}:: ${NC}Особенности включают в себя (Основные моменты): Введение традиционного меню приложений. Добавление средства просмотра ядер ЦП с элементарными графиками. Добавление API для запросов к файловой системе. Поддержка бесконечного количества датчиков и батарей. Учёт использования ZFS в системах FreeBSD. Добавление средства просмотра документации в представление процесса. Создание окна процесса для процессов (разделение пользовательского интерфейса). Просмотр использования ядра процессом по потокам. Поддержка потоков в Linux, FreeBSD, OpenBSD и DragonFlyBSD. Уточнение разбора аргументов процесса. Рефакторинг кода API запросов к процессам и потокам. Исправление утечек памяти. Выравнивание и улучшение пользовательского интерфейса. Значительная перестройка дерева исходного кода. Указание сортировки списка процессов. Исправление расчёта подкачки в macOS. Исправления для машин, отличных от Linux, на базе aarch64. Разрешён доступ пользователю к процессу (больше никаких оправданий, пользователи!!!). Добавлено окно «О программе». Отзывы: Некоторые положительные стороны, отмеченные пользователями: программа полезна для мониторинга в реальном времени; интерфейс отзывчивый. Некоторые недостатки, упомянутые в отзывах: колесо прокрутки мыши не работает для списка процессов; программа не включает историю. "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
echo ""
while
echo " Действия ввода, выполняется сразу после нажатия клавиши "
    read -n1 -p "
    1 - *Да установить,     0 - НЕТ - Пропустить установку: " in_evisum  # sends right after the keypress; # отправляет сразу после нажатия клавиши
    echo ''
    [[ "$in_evisum" =~ [^10] ]]
do
    :
done
if [[ $in_evisum == 0 ]]; then
echo ""
echo " Установка утилит (пакетов) пропущена "
elif [[ $in_evisum == 1 ]]; then
  echo ""
  echo " Установка утилиты (пакета) Evisum (evisum) "
#sudo pacman -Syy  # обновление баз пакмэна (pacman)
# sudo pacman -Syyu  # --noconfirm --needed  # -y – обновить списки пакетов из репозиториев ; -u – обновить пакеты ; Ключ -Syyu является наиболее часто используемой опцией и служит для обновления системы и всех установленных пакетов
  echo ""
  echo " Установка дополнительных утилит (пакетов) для мониторинга (efl) "
############ Зависимости ##############
sudo pacman -S --noconfirm --needed efl  # Библиотеки Фонда Просвещения ; https://archlinux.org/packages/extra/x86_64/efl/ ; https://www.enlightenment.org/ ; Заменяет: Elementary, emotions_generic_players, evas_generic_loaders ; 2025-03-17 16:14 UTC
############ evisum ##############
