clear
echo ""
echo -e "${BLUE}:: ${NC}Установить Psensor (psensor) - Мониторинг температуры?"
echo -e "${YELLOW}==> Примечание! ${BOLD} *В большинстве случаев нам не нужно беспокоиться о температуре компьютера. Все устроено так что температура не будет превышать максимальную если у вашего оборудования нет никаких производственных дефектов. Но перегрев могут вызвать не только аппаратные ошибки, это также может произойти из-за багов в драйвере графической карты или неправильно настроенной программы управления вентилятором. Частой причиной перегрева также может быть пыль, грязь, мусор попавшие в систему охлаждения (вентилятор, радиатор). Такое часто происходит со старым оборудованием. ${NC}"
echo -e "${MAGENTA}:: ${BOLD}Psensor — простая утилита с графическим интерфейсом на базе GTK+ для мониторинга температуры оборудования компьютера для Linux. Psensor может контролировать температуру датчиков CPU, GPU Nvidia, GPU ATI/AMD, жестких дисков, материнской платы. Также отображать скорость вращения вентиляторов и использование CPU. Psensor обладает простым и понятным интерфейсом. В табличном виде отображается список датчиков и температура. Также доступен динамический график изменения температуры. Линии на графике можно включать или отключать для каждого датчика отдельно. Этот проект Лицензируется под GPL-2.0 . ${NC}"
echo " Домашняя страница: https://wpitchoune.net/psensor ; (https://github.com/chinf/psensor ; https://archlinux.org/packages/extra/x86_64/psensor/). "
echo -e "${BLUE}:: ${NC}Функции: Psensor рисует графики в реальном времени и выдает оповещения о: температура датчиков материнской платы и процессора (с помощью lm-сенсоры) ; температура графических процессоров NVidia (с помощью XNVCtrl) ; температура графических процессоров ATI (с использованием ATI ADL SDK) ; температура жестких дисков (с помощью hddtemp или библиотеки atasmart, libatasmart или udisks2) ; скорость вращения вентиляторов (с использованием lm-sensors) ; датчики температуры удаленного компьютера (с использованием psensor-server) ; загрузка процессора. Оповещения используют уведомления на рабочем столе и специальный значок статуса GTK+ . "
echo -e "${CYAN}:: ${NC}Psensor использует два пакета (lm-sensor и hddtemp) для получения отчетов о температуре и скорости вращения вентилятора. А также psensor-server – это дополнительный пакет, который необходим, если вы хотите собрать информацию о температуре и скорости вращения вентилятора удаленного сервера. Установка Psensor Server — необязательна, требуется только в том случае, если вы хотите видеть температуру и скорость вращения вентилятора удаленного сервера. Запуск приложения производится из консоли или меню. Перейдите в меню Psensor → Настройки → Интерфейс . Здесь вы можете настроить интерфейс, единицы измерения температуры и положение сенсорной панели. В меню Psensor → Настройки → Автозагрузка можно настроить параметры «Запускать/Скрывать при запуске», а также «Восстанавливать положение и размер окна». В разделе «График» ( Psensor → Настройки → График ) вы можете настроить цвет переднего плана/фона, длительность мониторинга, интервал обновления и т. д.. Вы можете настроить параметры датчиков в разделе ( Psensor → Preferences → Sensors ). Последняя вкладка ( Psensor → Настройки → Поставщики ) предоставляет вам возможность включить/отключить конфигурацию всех датчиков. Настройки датчика можно настроить в разделе ( Psensor → Настройки датчика ). Расширенная информация: Для получения более полной информации достаточно нажать правой кнопкой мыши на имени нужного сенсора и в выпадающем меню выбрать Параметры. Настройки приложения находятся в меню Psensor. Они очень просты и понятны. Для выхода из программы достаточно выбрать в меню Psensor последний пункт Выход. В операционной системе Linux приложение Psensor является не только очень полезный инструмент, позволяющий увидеть те «серые зоны» мониторинга системы, которые часто упускаются из виду, например, мониторинг температуры оборудования, но и простым в использовании для всех начинающих пользователей.  "
echo -e "${YELLOW} Примечание! ${BOLD} *Будьте внимательны! Процесс установки был прописан полностью автоматическим. В данной опции выбор всегда остаётся за вами. ${NC}"
