# sudo sensors-detect  # Это необязательный, но рекомендуемый шаг, чтобы диагностировать оборудование с помощью датчиков, и ввести параметр по умолчанию, 'Yes'пока не будете знать, что делать.
# sudo sensors  # Посмотреть температуру процессора Linux и других аппаратных компонентов. Опять же, необязательный шаг, но для настройки подсказок вам следует запустить команду sensorsот имени root, чтобы отобразить температуру различных устройств из командной строки. Все эти данные будут использоваться Psensor .
sudo pacman -S --noconfirm --needed hddtemp  # Показывает вам информацию о температуре вашего жесткого диска, считывая информацию SMART ; https://archlinux.org/packages/extra/x86_64/hddtemp/ ; https://savannah.nongnu.org/projects/hddtemp/ ; 2024-03-18 18:16 UTC
# sudo hddtemp -d /dev/sdX  # Еще вам нужно запустить hddtemp для контроля температуры жестких дисков. Выполните эту команду для запуска hddtemp в качестве демона . Это нужно сделать для каждого диска. Также необходимо добавить эту программу в автозагрузку.
############ psensor ##############
sudo pacman -S --noconfirm --needed psensor  # Графический аппаратный монитор температуры для Linux ; https://archlinux.org/packages/extra/x86_64/psensor/ ; https://github.com/chinf/psensor ; 2023-05-19 17:12 UTC
  echo ""
  echo " Посмотрите информацию о версии (psensor) "
sudo pacman -Q psensor   # Показать версию приложения
#psensor --version  # Показать версию приложения
sleep 03
echo ""
echo " Установка утилит (пакетов) выполнена "
