############# Справка ##############
# Синтаксис Psensor:
# psensor [КЛЮЧ]...
# Параметры:
# -u, --url=URL
# URL psensor-сервера, пример: http://hostname:3131
# -n, --new-instance
# Принудительно запустить новую копию программы Psensor
# -d, --debug=УРОВЕНЬ
# Установить уровень отладки, целое значение между 0 и 3
# -h, --help
# Показать эту справку и выйти
# -v, --version
# Показать версию и выйти
# Настройка мониторинга температуры Linux
# Сначала нужно настроить низкоуровневые инструменты для считывания данных о температуре компонентов lm_sensors и hddtemp. Начнем с lm_sensors. После этого вы уже сможете посмотреть температуру linux.
# 1. Настройка lm_sensors
# Для запуска мастера настройки ls_sensors выполните команду:
#  sudo sensors-detect
# Отвечайте Y на все вопросы. Утилита попытается обнаружить все доступные в системе встроенные аппаратные датчики (для процессора, видеокарты, памяти и других микросхем), а также автоматически определить подходящие драйвера для них.
# Когда сканирование датчиков завершится вам будет предложено добавить обнаруженные модули ядра в автозагрузку:
# В Ubuntu или Debian модули будут добавлены в /etc/modeuls. А в Fedora будет создан файл /etc/sysconfig/lm_sensors. Для автоматической загрузки нужных модулей достаточно добавить lm_sensors в автозагрузку:
# sudo systemctl enable lm-sensors
# Теперь вы можете посмотреть температуру процессора Linux и других аппаратных компонентов с помощью команды sensors:
# sensors
# Настройка hddtemp:
# Еще вам нужно запустить hddtemp для контроля температуры жестких дисков. Выполните эту команду для запуска hddtemp в качестве демона, /dev/sda замените на адрес своего диска.
#  sudo hddtemp -d /dev/sdX
# Это нужно сделать для каждого диска. Также необходимо добавить эту программу в автозагрузку.
# Измерение и мониторинг температуры:
# Теперь можно начать мониторинг температуры linux с помощью psensor. Для этого просто запустите программу. Вы можете сделать это с помощью главного меню или же выполнив команду: psensor
# Для пользователей Ubuntu Psensor предоставляет индикатор приложений, который включает красный под тревожным индикатором и меню для быстрой проверки всех датчиков.
# Удаленный мониторинг компьютера возможен:
#  * запустить +psensor-server+ на удаленном компьютере.
#  * запустите +psensor+, используя: +psensor --url=http://hostname:3131+.
# +psensor-server+ — это минимальный веб-сервер, для которого можно использовать веб-браузер.
# контролировать удаленный компьютер, открыв URL-адрес:
# +http://имя_хоста:3131+.
# [ПРЕДУПРЕЖДЕНИЕ]
# +psensor-server+ не предоставляет возможности ограничить соединение к HTTP-серверу, худшее, что не было предпринято никаких усилий против вредоносных HTTP-атаки. Вам следует сделать порт +psensor-server+ доступным.
# только к сети или компьютеру, которому вы доверяете, используя обычную сеть
# средства безопасности системы (например: http://www.netfilter.org/projects/iptables/index.html[iptables] ).
